NOISE_PALS = {
    # NoiseModelling style files: "Coloring Noise" (Tomio, for the DIN 45682 revision) and DIN 18005-2 / UNI 9884
    "coloring": ["82a7ac", "a0bbbf", "b8d6d1", "cfe4cc", "e3f2bf", "f4c683", "e87d4d", "cd463f", "a11a4d", "75095d", "430a4a"],
    "din": ["B7CE8E", "1D8435", "0E4C3C", "ECD721", "9F6F2C", "EF7926", "C71932", "8D1A27", "88497B", "18558C", "134367"]}


def ramp(hexes, n):
    cols = [C(h) for h in hexes]
    if n <= 1:
        return [cols[len(cols) // 2]]
    out = []
    for k in range(n):
        t = k * (len(cols) - 1) / float(n - 1)
        i = min(len(cols) - 2, int(t))
        out.append(mix(cols[i], cols[i + 1], t - i))
    return out


def nice_step(span, n):
    raw = span / float(max(1, n))
    mag = 10 ** math.floor(math.log10(raw)) if raw > 0 else 1.0
    for m in (1, 2, 2.5, 5, 10):
        if m * mag >= raw:
            return m * mag
    return 10 * mag


def fmt_h(h):
    m = int(round(h * 60))
    return "%d:%02d" % (m // 60, m % 60)


# ------------------------------------------------------------ grids -> classed regions -> board
def building_blocks(S, cell=2.0):
    """All footprints merged into blocks (2 m raster, traced back to outlines): one shape per block."""
    if S.env.get("blocks") is not None:
        return S.env["blocks"]
    F = S.F
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    grid = [[None] * nx for _ in range(ny)]
    for b in S.env["solids"][0]:
        for Q in convex_parts(b["P"]):
            for j, a0, a1 in raster_rows([F.local(x, y) for x, y in Q], F, cell, nx, ny):
                row = grid[j]
                for i in range(a0, a1):
                    row[i] = 1
    loops = []
    for c, outer, holes in class_regions(grid, nx, ny):
        loops.append([[F.world(F.u0 + i * cell, F.v0 + j * cell) for i, j in lp] for lp in [outer] + holes])
    S.env["blocks"] = loops
    return loops


# ------------------------------------------------------------ the four analyses as map panels
def lst_grid(S, season, cell=10.0):
    L_ = S.env["lst"].get(season)
    if not L_:
        return None
    memo = env_memo(S)
    mk = ("lst_grid", season, cell)
    r = memo.get(mk)
    if r is not None:
        return r
    F = S.F
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    g = [[lst_sample(L_, *F.world(F.u0 + (i + 0.5) * cell, F.v0 + (j + 0.5) * cell)) for i in range(nx)] for j in range(ny)]
    r = memo[mk] = (g, nx, ny, cell)
    return r


# ------------------------------------------------------------ solar radiation in 3D (axonometric)
# ------------------------------------------------------------ legends and key figures
def canopy_note(S, short=False):
    """The crowns of this bake, their leaf types (with the evidence) and the leaf season (for the sheets)."""
    tr = S.env["solids"][2] if getattr(S, "env", None) else []
    k = dict((nm, sum(1 for t in tr if t["kind"] == nm)) for nm in ("olive", "pine", "tree"))
    src = dict((v, sum(1 for t in tr if t.get("leaf_src") == v)) for v in (1, 2, 3))
    a, b = leaf_dates()
    s = "Crowns: {} from the 1 m canopy height map".format(len(tr))
    if short:
        return s + (" ({} evergreen, {} deciduous; leaf type from CLC+ Backbone 2021 / Sentinel-2), the deciduous ones in "
                    "leaf from {} to {} (Sentinel-2 2019-2025).".format(k["olive"] + k["pine"], k["tree"], a, b)
                    if src[1] + src[2] + src[3] else " ({} evergreen, {} deciduous from the land-use zones), the deciduous "
                    "ones in leaf from {} to {}.".format(k["olive"] + k["pine"], k["tree"], a, b))
    if src[1] + src[2] + src[3]:
        s += (", {} evergreen broadleaf, {} needle-leaved and {} deciduous (leaf type: the Copernicus CLC+ Backbone 2021 "
              "tree class under {} of them, their own Sentinel-2 seasonality 2019-2025 for {}, the nearest CLC+ tree pixel "
              "for {})".format(k["olive"], k["pine"], k["tree"], src[1], src[2], src[3]))
    else:
        s += ", {} evergreen and {} deciduous (leaf type from the survey's land-use zones)".format(k["olive"] + k["pine"], k["tree"])
    return s + ("; the deciduous ones in leaf from {} to {} (Sentinel-2 2019-2025). Crown heights are modelled (Meta/WRI map v1, "
                "machine-learning estimates, mean absolute error 2.8 m; Tolan et al. 2024), not measured. An olive crown "
                "passes 15 % of the direct sun all year (Castillo-Ruiz et al. 2016: 13.3-24.6 %), any other crown in leaf "
                "3 %, a bare one 46 % (Konarska et al. 2014).".format(a, b))


def height_note(S):
    """Where the building heights come from, with the counts of this bake (one sentence for every sheet)."""
    mains = [u for u in S.bld if not u["annex"]]
    n = dict((k, len([u for u in mains if u["floors_src"] == k])) for k in ("survey", "neighbours", "published", "osm",
                                                                            "unlabelled"))   # v50 (P06.3)
    t = getattr(S, "floor_test", (0, 0.0, 0.0))
    s = ("Building heights: floors x typical storey height; {} buildings carry a surveyed floor count".format(n["survey"]))
    if n["neighbours"]:
        s += (", {} without one take the count shared by most of the {} nearest surveyed buildings (civic, sacred and "
              "industrial ones: the nearest of their own use); tried on each of the {} surveyed floor labels in turn, "
              "this rule gives the same count {:.0f} % of the time and is within one floor {:.0f} %".format(
                  n["neighbours"], NB_K, t[0], t[1], t[2]))
    if n["osm"]:
        s += ", {} from OpenStreetMap levels".format(n["osm"])
    if n["unlabelled"]:                                  # v50 (MIRAQUA 28 Oct, P06.3)
        s += ", {} house outlines the survey closed without a floor label count as one storey".format(n["unlabelled"])
    if n["published"]:
        s += "; the Red Basilica hall and rotundas at their published heights (19 m, 18 m)"
    return s + "."


def traffic_rows(S):
    """Per street type with traffic in the frame: (type name, km in the frame, how its flow was found, k, AADT used
    for a two-way street, source)."""
    plan = traffic_plan(S)
    F = S.F
    agg = {}
    for r, tr in zip(getattr(S, "roads_noise", []), plan):
        if tr is None:
            continue
        km = sum(pl_length(run) for run in F.clip_line(r["P"])) / 1000.0
        if km <= 0.0:
            continue
        if tr["kind"] == "counted":
            key = ("counted", tr["src"])
        else:
            key = (tr["kind"], tr["cat"], round(tr["k"], 4), tr["src"])
        a = agg.setdefault(key, dict(tr=tr, km=0.0))
        a["km"] += km
    rows = []
    for key, a in agg.items():
        tr = a["tr"]
        c = tr["cat"]
        day = GPG_D[c] + GPG_E[c] + GPG_N[c]
        if tr["kind"] == "counted":
            rows.append((GPG_NAMES[c], a["km"], "counted", None, None, tr["src"]))
        else:
            rows.append((GPG_NAMES[c], a["km"], tr["kind"], tr["k"], tr["k"] * day, tr["src"]))
    order = {"counted": 0, "correlated": 1, "default": 2}
    rows.sort(key=lambda r_: (order[r_[2]], GPG_NAMES.index(r_[0]), -r_[1]))
    return rows


def traffic_note(S):
    """Which roads carry traffic in the sound model, and from what (v16.3: every street, counted or correlated)."""
    parts = []
    for nm, km, kind, k, aadt, src in traffic_rows(S):
        if kind == "counted":
            parts.append("{} {:.2f} km: counted ({})".format(nm, km, src))
        elif kind == "correlated":
            parts.append("{}s {:.2f} km: CORRELATED, k = {:.2f} ({:+.1f} dB) from {} -> {:,.0f} veh/day".format(
                nm, km, k, 10.0 * math.log10(k), src, aadt))
        else:
            parts.append("{}s {:.2f} km: GPG DEFAULT, no count of this type in reach (k = 1) -> {:,.0f} veh/day".format(
                nm, km, aadt))
    return ("Traffic (v16.3): every street carries traffic. KGM counts where KGM counted (hours split by VBUS Table 2, "
            "row 3: day 06-18, evening 18-22, night 22-06); every other street takes the default flow of its type from the EU noise-mapping guidance ({}), "
            "multiplied by k = counted AADT / GPG default of the nearest KGM-counted road of the SAME type (DERIVED, "
            "not measured on that street; types KGM never counts keep the plain default). Heavy share: vehicles over "
            "3.5 t from KGM's class counts on the counted roads (KGM's OYTT class taken as heavy, an assumption); "
            "KGM's printed truck share on the correlated streets. One-way OSM ways carry half. "
            "Speed: the signed limit where mapped, else 50 km/h, the urban limit. ".format(GPG_SRC) + "; ".join(parts) + ".")


def water_grid(S):
    gW = Grid(30.0)
    for P in getattr(S, "water_outline", []):
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            gW.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))
    return gW


def env_memo(S):
    """Small results reused within a bake and kept with the environment analyses for the next one."""
    m = S.env.get("memo")
    if m is None:
        m = S.env["memo"] = {}
    return m


def water_band(S, gW, x, y):
    """0 = within 50 m of the river's edge, 2 = farther than 150 m, 1 = between (the same test as the distance)."""
    segs = gW.query((x - 50.0, y - 50.0, x + 50.0, y + 50.0))
    if segs and min(seg_dist(x, y, a[0], a[1], b[0], b[1]) for a, b in segs) <= 50.0:
        return 0
    segs = gW.query((x - 150.0, y - 150.0, x + 150.0, y + 150.0))
    if segs and min(seg_dist(x, y, a[0], a[1], b[0], b[1]) for a, b in segs) <= 150.0:
        return 1
    return 2


def lst_tiles(S, season):
    """v38 (was lst_figures, a paragraph): the season's surface-temperature readings as tiles."""
    G = lst_grid(S, season)
    if not G:
        return []
    vals, nx, ny, cell = G
    F = S.F
    memo = env_memo(S)
    bands = memo.get(("lst_bands", nx, ny, cell))
    if bands is None:                                   # distance to the river: the same for every season
        gW = water_grid(S)
        bands = {}
        for j in range(0, ny, 2):
            for i in range(0, nx, 2):
                bands[(i, j)] = water_band(S, gW, *F.world(F.u0 + (i + 0.5) * cell, F.v0 + (j + 0.5) * cell))
        memo[("lst_bands", nx, ny, cell)] = bands
    allv, near, far = [], [], []
    for j in range(0, ny, 2):
        for i in range(0, nx, 2):
            v = vals[j][i]
            if v is None:
                continue
            allv.append(v)
            b_ = bands[(i, j)]
            if b_ == 0:
                near.append(v)
            elif b_ == 2:
                far.append(v)
    allv.sort()
    if not allv:
        return []
    out = [("heat", "COOLEST 5 % · BELOW", "{:.1f} °C".format(allv[len(allv) // 20]), "[1]"),
           ("heat", "HOTTEST 5 % · ABOVE", "{:.1f} °C".format(allv[19 * len(allv) // 20]), "[1]")]
    if near and far:
        a_, b_ = sum(near) / len(near), sum(far) / len(far)
        dd = a_ - b_
        out += [("water", "WITHIN 50 m OF STREAM", "{:.1f} °C".format(a_), "[1]"),
                ("ground", "BEYOND 150 m", "{:.1f} °C".format(b_), "[1]"),
                ("water", "AT THE STREAM", "{} °C".format("0.0" if abs(dd) < 0.05 else "%+.1f" % dd), "[1]")]
    return out


# ------------------------------------------------------------ renders for each analysis
def noise_pal():
    """The sound bands' colours: input noise_palette ("brussels": the Brussels noise map's colour order over 11 DIN-style
    5 dB classes, not its 8 classes or colours (v21, R01-17), "coloring": Coloring Noise /
    DIN 45682 draft, "din": DIN 18005-2), else the graded bands (v16.4: quiet pale, loud dark, one hue run)."""
    if NOISE_PALETTE == "brussels":
        return list(TECH_PAL["noise"])
    if NOISE_PALETTE in NOISE_PALS:
        return list(NOISE_PALS[NOISE_PALETTE])
    if NOISE_PALETTE:
        LOG.append("noise_palette '{}' not known (brussels, coloring or din): the graded bands were used.".format(
            NOISE_PALETTE))
    return list(TECH_PAL["noise_graded"])


def noise_np(nm, key):
    """A sound grid as values (NaN inside buildings) and the receivers with no counted road within reach (out)."""
    nx, ny = nm["nx"], nm["ny"]
    vals = np.full(nx * ny, np.nan)
    out = np.zeros(nx * ny, bool)
    for j, row in enumerate(nm["grid"]):
        for i, c in enumerate(row):
            if not c:
                continue
            if c.get("out"):
                out[j * nx + i] = True
            elif c.get(key) is not None:
                vals[j * nx + i] = c[key]
    return vals, out


def noise_render(S, key, path, res):
    nm = S.env["noise"]
    vals, out = noise_np(nm, key)
    edges = [35, 40, 45, 50, 55, 60, 65, 70, 75, 80]
    return render_tech(path, S, S.F, res, vals, nm["nx"], nm["ny"], nm["cell"], 0.0, lut_classes(edges, noise_pal()),
                       roof="white", canopy_alpha=0.30, nodata=out if out.any() else None,
                       rkey=fp(S.env["keys"]["noise"], key))


def lst_np(S, season):
    """The season's surface temperature on a 10 m grid of the frame: (values (NaN = no clear pixel), nx, ny, cell)."""
    G = lst_grid(S, season)
    if not G:
        return None
    g, nx, ny, cell = G
    return np_grid(g, nx, ny).ravel(), nx, ny, cell


def heat_scale(S, season):
    """The season's surface temperature, centred on its own median: (grid, median, low, high); None without data."""
    G = lst_np(S, season)
    if not G:
        return None
    vals = np.sort(G[0][np.isfinite(G[0])])
    if vals.size == 0:
        return None
    med = float(vals[vals.size // 2])
    span = max(1.0, float(vals[int(0.98 * (vals.size - 1))]) - med, med - float(vals[int(0.02 * (vals.size - 1))]))
    return G, med, med - span, med + span


def shade_scale(daylight):
    """Hours in shade in classes of one hour, from 0 to the day's daylight."""
    n = max(1, int(math.ceil(daylight - 1e-6)))
    cols = ramp_hex(TECH_PAL["shade"], n)
    edges = [float(k) for k in range(1, n)]
    return n, cols, edges


def ramp_hex(hexes, n):
    cols = [hexrgb(h_) for h_ in hexes]
    out = []
    for k in range(n):
        t = k * (len(cols) - 1) / float(max(1, n - 1))
        i = min(len(cols) - 2, int(t))
        f = t - i
        out.append(tuple(int(round(cols[i][q] * (1 - f) + cols[i + 1][q] * f)) for q in range(3)))
    return out


def near_stream(S, xx, yy, R):
    """Which of the points lie within R metres of the river's edge (memoised per point set and distance)."""
    memo = env_memo(S)
    mk = ("near_stream", xx.size, float(xx[0]) if xx.size else 0.0, float(yy[-1]) if yy.size else 0.0, R)
    r = memo.get(mk)
    if r is not None:
        return r
    gW = water_grid(S)
    out = np.zeros(xx.size, bool)
    for k in range(xx.size):
        x, y = float(xx[k]), float(yy[k])
        segs = gW.query((x - R, y - R, x + R, y + R))
        if segs and min(seg_dist(x, y, a[0], a[1], b[0], b[1]) for a, b in segs) <= R:
            out[k] = True
    memo[mk] = out
    return out


def shade_items(S):
    """The rows of the shade sheet: the four key days and the mean day of the year."""
    sh = S.env["shade"]
    items = []
    for sd in SEASONS:
        d = sh["days"][sd["key"]]
        items.append(dict(key=sd["key"], season=sd["key"], name=sd["event"].upper(), hours=d["hours"], daylight=d["daylight"],
                          sub="sun up {}-{} local · {} h daylight · every minute [1]".format(fmt_h(d["sunrise"]), fmt_h(d["sunset"]),
                                                                                    fmt_h(d["daylight"]))))
    y = sh["year"]
    items.append(dict(key="year", season=None, name="THE MEAN DAY OF THE YEAR · ALL 365 DAYS", hours=y["hours"],
                      daylight=y["daylight"], sub="all 365 days averaged · {} h daylight on the mean day [1]".format(
                          fmt_h(y["daylight"]))))
    return items


def shade_tiles(S, it):
    """v38 (was shade_figures, a paragraph): the open ground's shade readings as tiles."""
    sh = S.env["shade"]
    h = it["hours"]
    o = np.isfinite(h)
    v = h[o]
    if v.size == 0:
        return []
    mean = float(v.mean())
    half = 100.0 * float((v >= it["daylight"] / 2.0).mean())
    G = sh["grid"]
    xx, yy = G["xx"][o], G["yy"][o]
    step = 4                                              # every 4th open cell for the stream band (a large sample)
    near = near_stream(S, xx[::step], yy[::step], 30.0)
    out = [("shade", "OPEN GROUND · MEAN SHADE", "{} h".format(fmt_h(mean)), "[1]"),
           ("clock", "SHARE OF THE DAYLIGHT", "{:.0f} %".format(100.0 * mean / it["daylight"]), "[1]"),
           ("shade", "SHADED > HALF THE DAY", "{:.0f} %".format(half), "[1]")]
    if near.any():
        out.append(("water", "WITHIN 30 m OF STREAM", "{} h".format(fmt_h(float(v[::step][near].mean()))), "[1]"))
    return out


def rad_scale(S, n=9):
    """Classes holding about equal shares of the ground and roof cells over all four seasons, in kWh/m2 per day
    rounded to 0.1 (one scale for the four maps, so the seasons compare)."""
    rd = S.env["rad"]
    vals = np.sort(np.concatenate([rd["seasons"][sd["key"]]["kwh"] for sd in SEASONS]))
    edges = []
    for k in range(1, n):
        e = round(float(vals[int(k * (vals.size - 1) / float(n))]) * 10.0) / 10.0
        if not edges or e > edges[-1]:
            edges.append(e)
    return edges


def rad_tiles(S, season):
    """v38 (was rad_figures_top, a line of figures): the season's radiation means as tiles, kWh/m2 per day."""
    rd = S.env["rad"]
    s = rd["seasons"][season]
    v = s["kwh"]
    gr = np.sort(v[~rd["roof"]])
    return [("roof", "ROOFS · MEAN kWh/m²·day", "{:.2f}".format(s["roof_mean"] or 0.0), "[1]"),
            ("ground", "GROUND · MEAN kWh/m²·day", "{:.2f}".format(s["ground_mean"] or 0.0), "[1]"),
            ("shade", "LOWEST 10 % GROUND · BELOW", "{:.2f}".format(float(gr[gr.size // 10]) if gr.size else 0.0), "[1]"),
            ("sun", "OPEN FLAT GROUND", "{:.2f}".format(s["ghi"]), "[3]")]


# ------------------------------------------------------------ the sheets
def sheet_sound(S, B, X, Y, U, rects, d):
    L = "LU_TECH::Sound"
    B.begin("TECHNICAL T1 · Sound", "LU_TECH")
    nm = S.env["noise"]
    cal = ("Calibrated with {} on-site measurements ({:+.1f} dB).".format(nm["n_meas"], nm["offset"]) if nm.get("n_meas")
           else "Not yet calibrated with on-site measurements.")
    # v38: keyword subtitle; the method paragraph as the footer's numbered key ([1]-[9] on this sheet)
    top, bottom = tech_frame(S, B, X, Y, U, "T1", "SOUND · ROAD TRAFFIC NOISE",
                             "Lden dB(A) · 4 m above ground · annual mean · top view [1]",
                             ["Method: RLS-90 road emission and segment method with distance, air and ground terms.",
                              "Screening: building screening by an "
                              "RLS-90-type D_z with the ISO 9613-2 limits (20 / 25 dB) and sign, the larger of it and the ground "
                              "term counted (VBUS eq. 6); VBUS's weather and reflection terms are not used; the "
                              "screening of each building block over its roof and round its two sides (ISO 9613-2 lateral "
                              "diffraction, v16.4).",
                              "Receivers 4 m above ground on a 10 m grid; colours: 5 dB bands, each darker "
                              "than the one before (the loudest darkest); Lden = day 06-18, evening 18-22 (+5 dB), night 22-06 (+10 dB), the periods of the "
                              "VBUS Table 2 hourly shares, from the "
                              "annual average daily traffic. Grey: no counted road within 300 m, not computed.",
                              "Streets (the sources): "
                              + ("solid grey surfaces with their edges, over the colours (v16.7)." if ROAD_SOLID else
                                 "hatched, with their edges, over the colours (v16.6)."),
                              traffic_note(S), height_note(S), "Trees: Meta/WRI 1 m canopy height map. Terrain: survey.",
                              "WHO Environmental Noise Guidelines (2018): road traffic below 53 dB Lden and 45 dB at night.",
                              cal])
    x0, W = X + PM * U, (PW - 2 * PM) * U
    p = os.path.join(d, "T1_sound_lden.png")
    noise_render(S, "lden", p, 1.0)
    V, wv, hv = tech_map(S, B, S.F, p, x0, top, W, 19.5 * U, U, L, crop_bar=False)   # v40: bands and tiles beside the bar
    road_overlay(S, B, V, L, 7)                           # v16.6: the streets (the sources) over the sound colours
    edges = [35, 40, 45, 50, 55, 60, 65, 70, 75, 80]
    labels = ["< 35"] + ["%d-%d" % (edges[k], edges[k + 1]) for k in range(len(edges) - 1)] + ["> 80"]
    cells = [c for row in nm["grid"] for c in row if c and c.get("lden") is not None]
    n_out = sum(1 for row in nm["grid"] for c in row if c and c.get("out"))
    share = [0] * 11
    for c in cells:
        share[sum(1 for e in edges if c["lden"] >= e)] += 1
    ntot = max(1, len(cells) + n_out)
    ly = tech_bands(B, x0 + 12.0 * U, top - hv - 0.6 * U, W * 0.56, noise_pal(), labels, U, L,
                    title="Lden dB(A) · share of the open ground" + (
                        " · {:.0f} % not computed [3]".format(100.0 * n_out / ntot) if n_out else ""),
                    sub=["{:.0f}%".format(100.0 * s / ntot) for s in share])
    who_d = 100.0 * sum(1 for c in cells if c["lden"] > 53.0) / ntot
    who_n = 100.0 * sum(1 for c in cells if c["night"] is not None and c["night"] > 45.0) / ntot
    tx = x0 + 12.0 * U + W * 0.56 + 2.0 * U
    vis_tiles(B, tx, top - hv - 0.6 * U, x0 + W - tx, [           # v38: the WHO reading as tiles (was a paragraph)
        ("limit", "ABOVE WHO 53 dB · Lden", "{:.0f} %".format(who_d), "[8]"),
        ("limit", "ABOVE WHO 45 dB · NIGHT", "{:.0f} %".format(who_n), "[8]"),
        ("gauge", "CALIBRATION", "{} pts · {:+.1f} dB".format(nm["n_meas"], nm["offset"]) if nm.get("n_meas")
         else "none", "[9]")], U, L)
    yB = ly - 1.0 * U
    pw = (W - 2 * 2.0 * U) / 3.0
    ph = pw * S.F.h / S.F.w
    for k, (key, name) in enumerate((("day", "DAY 06-18 · Ld"), ("evening", "EVENING 18-22 · Le"), ("night", "NIGHT 22-06 · Ln"))):
        px_ = x0 + k * (pw + 2.0 * U)
        t_title(B, px_, yB, name, pw, U, L, h=0.5)
        pp = os.path.join(d, "T1_sound_%s.png" % key)
        noise_render(S, key, pp, 2.0)
        Vk, _w, _h = tech_map(S, B, S.F, pp, px_, yB - 0.9 * U, pw, ph, U, L, scale=False)
        road_overlay(S, B, Vk, L, 7)
    yC = yB - 0.9 * U - ph - 1.6 * U
    if S.selinus and yC - bottom > 6.0 * U:
        t_title(B, x0, yC, "Lden ALONG THE STREAM · upstream left · WHO 53 dB dashed", W, U, L, h=0.5)
        tech_profile(S, B, x0, yC - 0.9 * U, W, min(7.5 * U, yC - bottom - 2.8 * U), U, L, who_ref="[8]")
    rects.append(("T1 · Sound", (X, Y - PH * U, X + PW * U, Y)))


def tech_rows(S, B, X, Y, U, rects, num, title, subtitle, sources, layer, render_fn, side_fn, items=None):
    """A sheet of map rows (the four seasons, or the given items), each with its side panel."""
    items = items or SEASONS
    L = "LU_TECH::" + layer
    B.begin("TECHNICAL %s · %s" % (num, layer), "LU_TECH")
    top, bottom = tech_frame(S, B, X, Y, U, num, title, subtitle, sources)
    x0, W = X + PM * U, (PW - 2 * PM) * U
    rowh = (top - bottom) / float(len(items))
    mh = rowh - 1.4 * U
    mw = min(W * 0.6, mh * S.F.w / S.F.h)
    ps = par_renders([(lambda sd_=sd: render_fn(sd_)) for sd in items])      # v18: the pictures side by side
    for k, sd in enumerate(items):
        y = top - k * rowh
        p = ps[k]
        V, wv, hv = tech_map(S, B, S.F, p, x0, y, mw, mh, U, L, scale=(k == len(items) - 1))
        side_fn(sd, x0 + wv + 2.4 * U, y, x0 + W - (x0 + wv + 2.4 * U), L)
    rects.append(("%s · %s" % (num, layer), (X, Y - PH * U, X + PW * U, Y)))


def lst_note(S, season):
    """When the season's surface temperature was seen: the scenes behind the mean (or the single scene of v1 data)."""
    L_ = S.env["lst"].get(season, {})
    if L_.get("n_scenes"):                            # v38: keywords (was a sentence)
        return ("{} clear scenes · {} to {} · {} UTC ({} local)".format(
            L_["n_scenes"], L_["first"], L_["last"], L_["utc_mean"], "%02d:%s" % ((int(L_["utc_mean"][:2]) + 3) % 24, L_["utc_mean"][3:])))
    when = L_.get("datetime_utc", "")
    return "Landsat {} · {} {} UTC (one scene)".format(L_.get("scene", "")[3:4], when[:10], when[11:16])


def sheet_heat(S, B, X, Y, U, rects, d):
    multi = any(v.get("n_scenes") for v in S.env["lst"].values())

    def render(sd):
        r = heat_scale(S, sd["key"])
        p = os.path.join(d, "T2_surface_heat_%s.png" % sd["key"])
        if r:
            (g, nx, ny, cell), med, vmin, vmax = r
            render_tech(p, S, S.F, 1.5, g, nx, ny, cell, 0.5, lut_ramp(vmin, vmax, TECH_PAL["heat"]), roof="field",
                        season=sd["key"], canopy_alpha=0.22, nodata=~np.isfinite(g) if (~np.isfinite(g)).any() else None,
                        rkey=fp(S.env["E_fp"], site_prints(S)["frame"], "lst", sd["key"]))
        else:
            render_tech(p, S, S.F, 1.5, np.zeros(4), 2, 2, max(S.F.w, S.F.h), 0.0, lut_ramp(0.0, 1.0, TECH_PAL["heat"]),
                        nodata=np.ones(4, bool), rkey=fp("no lst", sd["key"]))
        return p

    def side(sd, x, y, w, L):
        months = {"spring": "MARCH-MAY", "summer": "JUNE-AUGUST", "autumn": "SEPTEMBER-NOVEMBER", "winter": "DECEMBER-FEBRUARY"}
        t_title(B, x, y, "{} · {}".format(sd["name"], months[sd["key"]]), w, S.U, L)
        B.fit(lst_note(S, sd["key"]) + " [1]", x, y - 0.9 * S.U, 0.3 * S.U, w, T_GREY, L)
        r = heat_scale(S, sd["key"])
        if not r:
            B.fit("No clear scene: map grey [1]", x, y - 1.6 * S.U, 0.3 * S.U, w, T_INK, L)
            return
        _, med, vmin, vmax = r
        yy = tech_colorbar(B, x, y - 1.6 * S.U, w, TECH_PAL["heat"], vmin, vmax, S.U, L,
                           title="LST °C · white = season median {:.2f} °C [3]".format(med), unit="")
        yy = vis_tiles(B, x, yy - 0.1 * S.U, w, lst_tiles(S, sd["key"]), S.U, L, h=0.9)   # v38: tiles (was a paragraph)
        hs = (seam_pack().get("heat") or {}).get("seasons", {}).get(sd["key"])
        if hs:
            heat_canopy_inset(B, hs, x, yy - 0.35 * S.U, w * 0.55, S.U, L, ref="[4]")
    tech_rows(S, B, X, Y, U, rects, "T2", "SURFACE HEAT · FOUR SEASONS",
              "LST °C · Landsat 8/9 · late morning · " + ("mean of the clear scenes" if multi else "one clear scene a season")
              + " · 3D site from above [1]",
              ["Landsat 8/9 Collection 2 Level-2 surface temperature (USGS), band 10, cloud-masked (QA_PIXEL); "
               + ("every scene of 2021-2026 with at least 95 % of the area clear, averaged per season (each cell over the scenes "
                  "that saw it clear)." if multi else "one cloud-free scene per season."),
               "Thermal pixels are 100 m (delivered at 30 m), so read whole blocks, not single roofs; surface temperature is "
               "not air temperature.", "Each season is centred on its own median. Roofs carry the satellite value.",
               "Under the trees: mean surface temperature of the 30 m cells by canopy cover, with the cells counted and "
               "Pearson's r."],
              "Surface heat", render, side)


def heat_canopy_inset(B, hs, x, y, w, U, L, ref=""):
    """v33 (plant analysis panel 6): mean surface temperature of the frame's 30 m cells by their canopy cover, one bar
    per cover class, with the cells counted and Pearson's r. An association at block scale, not cooling per tree.
    v35: the classes are re-binned from the cells (25-100 % in one class; v34's 50-100 % held 3 cells)."""
    bins = hs["bins"]
    pts = hs.get("points") or []
    if pts:
        bins = []
        for lab, lo, hi in (("0 %", None, None), ("0-10 %", 0.0, 0.10), ("10-25 %", 0.10, 0.25), ("25-100 %", 0.25, 1.01)):
            v = [t for c, t in pts if (c <= 0.0 if lo is None else (c > 0.0 and lo <= c < hi))]
            if v:
                bins.append(dict(label=lab, n=len(v), mean=sum(v) / len(v)))
    lo = min(b_["mean"] for b_ in bins) - 0.5
    hi = max(b_["mean"] for b_ in bins)
    B.fit("UNDER THE TREES · {:,} cells · {} scenes · Pearson r {:.2f} {}".format(        # v38: keywords + [n]
        hs["cells"], hs.get("scenes", "?"), hs["pearson_r"], ref), x, y, 0.28 * U, w, T_INK, L)
    y -= 0.75 * U
    lw, vw = 2.2 * U, 1.6 * U
    bw = w - lw - vw
    for b_ in bins:
        f = (b_["mean"] - lo) / max(1e-6, hi - lo)
        B.text(b_["label"] + " cover", x, y, 0.24 * U, T_GREY, L)
        B.fill([rect(x + lw, y, x + lw + bw * f, y + 0.26 * U)], mix(LEAF_COL[0], (200, 70, 30), f), L, 30)
        B.text("{:.2f} °C · {:,} cells".format(b_["mean"], b_["n"]),
               x + lw + bw * f + 0.15 * U, y, 0.24 * U, T_INK, L)
        y -= 0.42 * U
    return y


def sheet_shade(S, B, X, Y, U, rects, d):
    items = shade_items(S)
    sh = S.env["shade"]
    G = sh["grid"]

    def render(it):
        n, cols, edges = shade_scale(it["daylight"])
        p = os.path.join(d, "T3_shade_%s.png" % it["key"])
        render_tech(p, S, S.F, 0.3, it["hours"], G["nx"], G["ny"], G["cell"], 0.5, lut_classes(edges, cols),
                    roof="white", season=it["season"], canopy_alpha=0.28, rkey=fp(S.env["keys"]["shade"], it["key"]))
        return p

    def side(it, x, y, w, L):
        t_title(B, x, y, it["name"], w, S.U, L)
        B.fit(it["sub"], x, y - 0.9 * S.U, 0.3 * S.U, w, T_GREY, L)
        n, cols, edges = shade_scale(it["daylight"])
        yy = tech_bands(B, x, y - 1.6 * S.U, w, cols, ["%d" % k for k in range(n)], S.U, L,
                        title="Hours in shade (from the hour shown)" + (" on the mean day" if it["key"] == "year" else ""))
        vis_tiles(B, x, yy - 0.1 * S.U, w, shade_tiles(S, it), S.U, L, h=0.9)     # v38: tiles (was a paragraph)
    tech_rows(S, B, X, Y, U, rects, "T3", "SHADE · THE KEY DAYS AND THE YEAR",
              "Hours in shade · key days + the year · sunrise to sunset [1]",
              ["Every minute the sun is up (NOAA sun position, UTC+3): the four key days of 2025, and every day of the year "
               "averaged.",
               "Casters: every building (exact footprint, roof at its surveyed floors over the surveyed ground), "
               "3D tree crowns from the 1 m canopy height map at their modelled heights (Meta/WRI, mean absolute error 2.8 m), the terrain horizon (PVGIS DEM) and "
               "the ground's own slope; obstruction found exactly for every degree of sun azimuth, {:g} m cells (v16.6; "
               "v16.5: 3 m).".format(SHADE_CELL), canopy_note(S), height_note(S)],
              "Shade", render, side, items=items)


def sheet_radiation(S, B, X, Y, U, rects, d):
    L = "LU_TECH::Solar radiation"
    B.begin("TECHNICAL T4 · Solar radiation", "LU_TECH")
    rd = S.env["rad"]
    top, bottom = tech_frame(S, B, X, Y, U, "T4", "SOLAR RADIATION · FOUR SEASONS",
                             "kWh/m² per day · ground + roofs · season means [1]",
                             ["Every hour of the PVGIS-SARAH2 typical year 2005-2020 for these coordinates, the sun at its exact "
                              "position.",
                              "Direct and circumsolar sun through the obstruction of that sun position (buildings, 3D "
                              "tree crowns by their transmission, terrain horizon, the ground's own slope), isotropic sky "
                              "(Perez 1990) through the cosine-weighted sky each cell sees (72 sectors, exact in elevation), the "
                              "Perez horizon band and ground reflection (albedo 0.2) on slopes. Ground and roofs every 1.5 m.",
                              "On open flat ground the model returns the typical year's global horizontal (within 0.1 %).",
                              "Area: " + ("the whole frame." if S.env["focus"] is S.F else "the focus area (key plan)."),
                              canopy_note(S),
                              "Classes: one scale for the four seasons, each class holding about an equal share of the "
                              "ground and roof cells."])
    x0, W = X + PM * U, (PW - 2 * PM) * U
    Fo = S.env["focus"]
    if Fo is S.F:                                     # v16.5: the whole frame, a row per season as on T5-T7
        return sheet_radiation_rows(S, B, X, Y, U, rects, d, L, top, bottom)
    kp_w = 18.0 * U
    key_plan(S, B, x0 + W - kp_w, Y - 1.9 * U, kp_w, Fo, U, L)
    cw = (W - 2.4 * U) / 2.0
    rowh = (top - bottom) / 2.0
    edges = rad_scale(S)
    cols = ramp_hex(TECH_PAL["rad"], len(edges) + 1)
    lut = lut_classes(edges, cols)
    labels = ["< %.2f" % edges[0]] + ["%.2f-%.2f" % (edges[i], edges[i + 1]) for i in range(len(edges) - 1)] + ["> %.2f" % edges[-1]]
    months = {"spring": "MARCH-MAY", "summer": "JUNE-AUGUST", "autumn": "SEPTEMBER-NOVEMBER", "winter": "DECEMBER-FEBRUARY"}
    def pic(sd):
        v = rd["seasons"][sd["key"]]["kwh"]
        gnd = np.where(rd["roof"], np.nan, v)
        roofv = np.where(rd["roof"], v, np.nan)
        p = os.path.join(d, "T4_solar_radiation_%s.png" % sd["key"])
        render_tech(p, S, Fo, 0.3, gnd, rd["nx"], rd["ny"], rd["cell"], 0.5, lut, roof="grid", roof_grid=roofv,
                    season=sd["key"], canopy_alpha=0.62, rkey=fp(S.env["keys"]["rad"], sd["key"], edges))
        return p
    ps = par_renders([(lambda sd_=sd: pic(sd_)) for sd in SEASONS])        # v18: the pictures side by side
    for k, sd in enumerate(SEASONS):
        cx = x0 + (k % 2) * (cw + 2.4 * U)
        cy = top - (k // 2) * rowh
        t_title(B, cx, cy, "{} · {} · {} DAYS".format(sd["name"], months[sd["key"]], days_in_season(sd["key"])), cw, U, L, h=0.55)
        p = ps[k]
        V, wv, hv = tech_map(S, B, Fo, p, cx, cy - 0.9 * U, cw, rowh - 5.0 * U, U, L, scale=True)
        yy = tech_bands(B, cx + 9.0 * U, cy - 0.9 * U - hv - 0.4 * U, cw - 9.0 * U, cols, labels, U, L, h=0.27,
                        title="kWh/m² per day · one scale, four seasons [6]")
        vis_tiles(B, cx, yy - 0.05 * U, cw, rad_tiles(S, sd["key"]), U, L, h=0.6)     # v38: tiles (was a line)
    rects.append(("T4 · Solar radiation", (X, Y - PH * U, X + PW * U, Y)))


def sheet_radiation_rows(S, B, X, Y, U, rects, d, L, top, bottom):
    """v16.5: T4 over the whole frame: one row per season (the map, then its classes and figures beside it), drawn on
    the sheet tech_frame already began."""
    rd = S.env["rad"]
    x0, W = X + PM * U, (PW - 2 * PM) * U
    edges = rad_scale(S)
    cols = ramp_hex(TECH_PAL["rad"], len(edges) + 1)
    lut = lut_classes(edges, cols)
    labels = ["< %.2f" % edges[0]] + ["%.2f-%.2f" % (edges[i], edges[i + 1]) for i in range(len(edges) - 1)] + ["> %.2f" % edges[-1]]
    months = {"spring": "MARCH-MAY", "summer": "JUNE-AUGUST", "autumn": "SEPTEMBER-NOVEMBER", "winter": "DECEMBER-FEBRUARY"}
    rowh = (top - bottom) / float(len(SEASONS))
    mh = rowh - 1.4 * U
    mw = min(W * 0.6, mh * S.F.w / S.F.h)
    def pic(sd):
        v = rd["seasons"][sd["key"]]["kwh"]
        gnd = np.where(rd["roof"], np.nan, v)
        roofv = np.where(rd["roof"], v, np.nan)
        p = os.path.join(d, "T4_solar_radiation_%s.png" % sd["key"])
        render_tech(p, S, S.F, 0.3, gnd, rd["nx"], rd["ny"], rd["cell"], 0.5, lut, roof="grid", roof_grid=roofv,
                    season=sd["key"], canopy_alpha=0.62, rkey=fp(S.env["keys"]["rad"], sd["key"], edges))
        return p
    ps = par_renders([(lambda sd_=sd: pic(sd_)) for sd in SEASONS])        # v18: the pictures side by side
    for k, sd in enumerate(SEASONS):
        y = top - k * rowh
        p = ps[k]
        V, wv, hv = tech_map(S, B, S.F, p, x0, y, mw, mh, U, L, scale=(k == len(SEASONS) - 1))
        sx = x0 + wv + 2.4 * U
        sw = x0 + W - sx
        t_title(B, sx, y, "{} · {} · {} DAYS".format(sd["name"], months[sd["key"]], days_in_season(sd["key"])), sw, U, L)
        yy = tech_bands(B, sx, y - 1.1 * U, sw, cols, labels, U, L, h=0.27,
                        title="kWh/m² per day · one scale, four seasons [6]")
        vis_tiles(B, sx, yy - 0.1 * U, sw, rad_tiles(S, sd["key"]), U, L, h=0.9)      # v38: tiles (was a paragraph)
    rects.append(("T4 · Solar radiation", (X, Y - PH * U, X + PW * U, Y)))


# ------------------------------------------------------------ wind, air and felt temperature: the period means
def comfort_sources(S=None):
    """v38: the climate and site sources of T5-T8 and their sections as the first five entries [1]-[5] of the sheet's
    numbered key (was one paragraph)."""
    CF = S.env.get("comfort") if S is not None else None
    lab = CF["label"] if CF else window_label()
    return ["Climate: the PVGIS typical meteorological year 2005-2020 for these coordinates (EU JRC): air temperature, "
            "humidity, 10 m wind and long-wave sky radiation from ERA5, sun from SARAH-2.",
            "Every map is the mean over " + lab + " of each season (input hours: daylight, all, or a range such as 10-17).",
            "Site: the buildings, terrain from the survey and PVGIS horizons.",
            canopy_note(S, short=True) if S is not None else "",
            height_note(S) if S is not None else ""]


def comfort_scales(S):
    """One wind scale and one temperature scale for the three sheets and their sections."""
    CF = S.env["comfort"]
    memo = env_memo(S)
    r = memo.get("comfort_scales")
    if r is not None:
        return r
    ts, ws = [], []
    for sd in SEASONS:
        c = CF["seasons"][sd["key"]]
        for k in ("ta", "utci"):
            v = c[k][np.isfinite(c[k])]
            if v.size:
                ts += [float(v.min()), float(v.max())]
        v = c["uped"][np.isfinite(c["uped"])]
        if v.size:
            ws.append(float(v.max()))
    lo, hi = 5.0 * math.floor(min(ts) / 5.0), 5.0 * math.ceil(max(ts) / 5.0)
    if hi - lo < 10.0:
        hi = lo + 10.0
    wmax = max(2.0, math.ceil(max(ws) * KT / 2.0) * 2.0 / KT) if ws else 2.0
    r = memo["comfort_scales"] = dict(t_range=(lo, hi), w_max=wmax)
    return r


def prevailing(c):
    """The sector the season's wind came from most often in the window (16 sectors) and its share of the hours."""
    tot = [sum(r) for r in c["rose"]]
    k = max(range(16), key=lambda q: tot[q])
    return k * 22.5, tot[k]


def sheet_wind(S, B, X, Y, U, rects, d):
    CF = S.env["comfort"]
    G = CF["grid"]
    wmax = comfort_scales(S)["w_max"]
    win_ = analysis_window(S, "wind")                 # v16.5: one window for the plan and every wind section
    scs = {sd["key"]: stretch_scale(WINDY_WIND, 0.0, WIND_SCALE_HI, CF["seasons"][sd["key"]]["uped"], to=WIND_STRETCH_TO,
                                    ab=win_) for sd in SEASONS}
    names = ("N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW")
    CP = Compass(S.env["E"]["location"]["lon"], S.env["E"]["location"]["lat"])

    def render(sd):
        c = CF["seasons"][sd["key"]]
        p = os.path.join(d, "T5_wind_%s.png" % sd["key"])
        dir_from, _ = prevailing(c)
        to = frame_dir(S.F, CP.vec((dir_from + 180.0) % 360.0))
        field = [[(None if not np.isfinite(v) else float(v)) for v in row] for row in c["uped"].reshape(G["ny"], G["nx"])]
        render_tech(p, S, S.F, 1.5, c["uped"], G["nx"], G["ny"], G["cell"], 0.5, scs[sd["key"]][0], roof="white",
                    season=sd["key"], canopy_alpha=0.22, relief=0.45, post=wind_streaks(S.F, 1.5, field, G["nx"], G["ny"], G["cell"], to),
                    rkey=fp(S.env["keys"]["comfort"], sd["key"], "uped", wmax))
        return p

    def side(sd, x, y, w, L):
        c = CF["seasons"][sd["key"]]
        dir_from, share = prevailing(c)
        t_title(B, x, y, "{} · MEAN OF {:,} HOURS · MOSTLY FROM {}".format(sd["name"], c["hours"], names[int(round(dir_from / 22.5)) % 16]),
                w, S.U, L)
        B.fit("{} · 10 m {:.2f} m/s ({:.2f} kt) · from {} {:.0f} % of hours [1]".format(        # v38: keywords
            CF["label_short"], c["u10_mean"], c["u10_mean"] * KT, names[int(round(dir_from / 22.5)) % 16], 100.0 * share),
            x, y - 0.9 * S.U, 0.3 * S.U, w, T_GREY, L)
        R = min(3.4 * S.U, (w - 2.0 * S.U) * 0.16)
        draw_wind_rose(B, x + R + 0.6 * S.U, y - 2.0 * S.U - R, R, c["rose"], c["calm"], page_north(S.F), S.U, L)
        tx = x + 2 * R + 2.0 * S.U
        tw_ = x + w - tx
        yb = stretch_bar(B, tx, y - 1.45 * S.U, tw_, WINDY_WIND, 0.0, WIND_SCALE_HI, scs[sd["key"]], S.U, L,
                         "kt at 1.5 m · mean · Windy colours 0-{:.0f} m/s = 0-{:.0f} kt [6]".format(
                             WIND_SCALE_HI, WIND_SCALE_HI * KT), k=KT, th=0.24, vals=c["uped"])
        vals = c["uped"][np.isfinite(c["uped"])]
        open_v = c["u10_mean"] * PED_WIND
        shel = 100.0 * float((vals < 0.5 * open_v).mean()) if vals.size else 0.0
        vis_tiles(B, tx, yb - 0.2 * S.U, tw_, [                  # v38: tiles (was a paragraph); calm stays on the rose
            ("wind", "OPEN GROUND · 1.5 m", "{:.2f} m/s · {:.2f} kt".format(open_v, open_v * KT), "[6]"),
            ("wind", "ACROSS THE SITE · MEAN", "{:.2f} m/s".format(float(vals.mean()) if vals.size else 0.0), "[6]"),
            ("build", "SHELTERED < HALF OPEN", "{:.0f} %".format(shel), "[6]")], S.U, L, h=0.9)
    tech_rows(S, B, X, Y, U, rects, "T5", "WIND · FOUR SEASONS",
              "Wind at 1.5 m · colour = speed · streaks = prevailing flow [6]",
              comfort_sources(S) + [
                  "Wind: every hour's 10 m wind (ERA5) brought to 1.5 m over open ground (log law, z0 0.1 m) "
                  "and reduced behind every building and crown upwind within 300 m (also beyond the frame) with measured "
                  "windbreak wake curves (Heisler & DeWalle 1988), for that hour's direction in 10-degree sectors; then "
                  "averaged; colours after Windy.",
                  "An estimate of shelter, not CFD: no corner jets or gusts. ERA5 wind is regional; valley "
                  "channelling is not resolved."],
              "Wind", render, side)


def draw_day_chart(B, x, ytop, w, h, series, lo, hi, U, L, window=None, bands=None, band_fill=None, unit="°C"):
    """24-hour curves by local hour. series: [(values[24] (None = no value), colour, width, label)], band_fill:
    (low[24], high[24], colour); window: the averaging window's hours, shaded."""
    X_ = lambda t: x + 1.6 * U + (w - 1.6 * U) * t / 24.0
    Y_ = lambda v: ytop - h + h * (max(lo, min(hi, v)) - lo) / (hi - lo)
    B.fill([rect(x + 1.6 * U, ytop - h, x + w, ytop)], (250, 250, 251), L, 20)
    if window is not None:
        for hh in range(24):
            if window[hh]:
                B.fill([rect(X_(max(0.0, hh - 0.5)), ytop - h, X_(min(24.0, hh + 0.5)), ytop)], (238, 238, 242), L, 20)
    for (b0, b1, col, lab) in (bands or []):
        if b1 <= lo or b0 >= hi:
            continue
        B.fill([rect(x + 1.6 * U, Y_(b0), x + w, Y_(b1))], col, L, 21)
        B.fit(lab, x + w - 0.15 * U, Y_(min(b1, hi)) - 0.3 * U, 0.2 * U, 9.0 * U, T_GREY, L, align="R")
    step = nice_step(hi - lo, 4)
    v = math.ceil(lo / step) * step
    while v <= hi + 1e-9:
        B.line([(x + 1.6 * U, Y_(v)), (x + w, Y_(v))], (214, 214, 220), L, 22, 0.02)
        B.text("%.0f" % v, x + 1.35 * U, Y_(v) - 0.1 * U, 0.24 * U, T_GREY, L, align="R")
        v += step
    for t in range(0, 25, 6):
        B.text("%02d:00" % (t % 24) if t < 24 else "24:00", X_(t), ytop - h - 0.5 * U, 0.22 * U, T_GREY, L, align="C")
    if band_fill:
        lo_v, hi_v, col = band_fill
        pts = [(X_(t), Y_(hi_v[t])) for t in range(24) if hi_v[t] is not None]          # values at the full hour
        pts += [(X_(t), Y_(lo_v[t])) for t in range(23, -1, -1) if lo_v[t] is not None]
        if len(pts) >= 3:
            B.fill([pts], col, L, 23)
    for vals, col, lw, lab in series:
        run = []
        for t in range(25):
            if t < 24 and vals[t] is not None:
                run.append((X_(t), Y_(vals[t])))
                continue
            if len(run) >= 2:
                B.line(run, col, L, 25, lw)
            run = []
    B.line(rect(x + 1.6 * U, ytop - h, x + w, ytop) + [(x + 1.6 * U, ytop - h)], T_RULE, L, 27, 0.04)
    B.text(unit, x + 1.6 * U, ytop + 0.45 * U, 0.22 * U, T_GREY, L, align="R")
    return ytop - h - 0.9 * U


def window_hours(CF):
    """Which local hours the averaging window holds (for the charts): 24 booleans."""
    kind, rng = CF["window"]
    if kind == "all":
        return [True] * 24
    if kind == "range":
        return [((hh - rng[0]) % 24) < (rng[1] - rng[0]) for hh in range(24)]
    return None


def sheet_air(S, B, X, Y, U, rects, d):
    CF = S.env["comfort"]
    G = CF["grid"]
    lo, hi = tsec_comfort_scales(S, tsec_lines(S))[1:]    # v16.5: the sections' scale, so plan and sections match
    win_ = analysis_window(S, "ta")                   # v16.5: one window for the plan and every air section
    scs = {sd["key"]: stretch_scale(WINDY_TEMP, lo, hi, CF["seasons"][sd["key"]]["ta"], ab=win_) for sd in SEASONS}

    def render(sd):
        c = CF["seasons"][sd["key"]]
        p = os.path.join(d, "T6_air_temperature_%s.png" % sd["key"])
        render_tech(p, S, S.F, 1.5, c["ta"], G["nx"], G["ny"], G["cell"], 0.5, scs[sd["key"]][0], roof="white", season=sd["key"],
                    canopy_alpha=0.22, rkey=fp(S.env["keys"]["comfort"], sd["key"], "ta", lo, hi))
        return p

    def side(sd, x, y, w, L):
        c = CF["seasons"][sd["key"]]
        t_title(B, x, y, "{} · MEAN OF {:,} HOURS · AIR {:.2f} °C · RH {:.0f} %".format(sd["name"], c["hours"], c["ta_mean"],
                                                                                     c["rh_mean"]), w, S.U, L)
        vals = c["ta"][np.isfinite(c["ta"])]
        B.fit("{} · dry bulb 2 m · only height changes it [6]".format(CF["label_short"]),          # v38: keywords
              x, y - 0.9 * S.U, 0.3 * S.U, w, T_GREY, L)
        yy = stretch_bar(B, x, y - 1.5 * S.U, w * 0.46, WINDY_TEMP, lo, hi, scs[sd["key"]], S.U, L,
                         "°C · same scale on T6 and T7", vals=c["ta"])
        day = c["day"]
        mean = [q[0] for q in day]
        p10 = [q[1] for q in day]
        p90 = [q[2] for q in day]
        vv = [v for v in p10 + p90 if v is not None]
        lo_c = math.floor(min(vv) / 5.0) * 5.0
        hi_c = math.ceil(max(vv) / 5.0) * 5.0
        draw_day_chart(B, x + w * 0.5, y - 1.95 * S.U, w * 0.5, 5.2 * S.U, [(mean, T_INK, 0.1, "mean")], lo_c, hi_c, S.U, L,
                       window=window_hours(CF), band_fill=(p10, p90, (226, 214, 190)))
        yy = vis_tiles(B, x, yy - 0.2 * S.U, w * 0.46, [          # v38: the site's range as a tile (was in a sentence)
            ("air", "ACROSS THE SITE · DRY BULB", "{:.2f}–{:.2f} °C".format(float(vals.min()), float(vals.max())), "[6]")],
            S.U, L, h=0.9)
        B.fit("chart: typical day · mean line · 80 % band [8]", x + w * 0.5 + 1.6 * S.U, y - 1.95 * S.U - 5.2 * S.U - 0.95 * S.U,
              0.22 * S.U, w * 0.5 - 1.6 * S.U, T_GREY, L)
    tech_rows(S, B, X, Y, U, rects, "T6", "AIR TEMPERATURE · DRY BULB · FOUR SEASONS",
              "Dry bulb °C · 2 m above ground · season mean · Windy [6]",
              comfort_sources(S) + [
                  "Dry bulb from the PVGIS climate data (ERA5-Land 2 m air temperature of its grid cell; "
                  "that cell's ground height is not reported), adjusted to the surveyed terrain with the standard lapse rate "
                  "(-0.65 K per 100 m) from PVGIS's point elevation ({:.0f} m), taken as its height (an assumption); colours "
                  "after Windy's scale.".format(CLIMATE["elevation"]),
                  "Street-scale air differences (shade, water, traffic) are small and are not modelled.",
                  "Chart: the season's typical day, every day of it: mean dry bulb by local hour (line) and the band holding "
                  "80 % of the hours. The air is the same across the site; how it feels is not (T7)."],
              "Air temperature", render, side)


def utci_reference_day(S, season):
    """The season's typical day by local hour for two reference spots, from every hour of it: open sun (whole sky, full
    sun, full wind) and street shade (half the sky, no direct sun, half the wind)."""
    memo = env_memo(S)
    mk = ("utci_ref", season)
    r = memo.get(mk)
    if r is not None:
        return r
    TT = S.env["TT"]
    m = TT["si"] == SEASON_INDEX[season]
    hs = np.flatnonzero(m)
    ta, rh = TT["t2m"][hs], TT["rh"][hs]
    pa = es_hpa_np(ta) * rh / 1000.0
    K = utci_K(ta, pa)
    el = TT["el"][hs]
    sun = el >= 2.0
    c1 = np.where(sun, MRT_K * proj_np(el) * TT["dni"][hs], 0.0)
    c2 = np.where(sun, MRT_K * 0.5 * F_EFF * (TT["dhi"][hs] + TT["ghi"][hs] * MRT_ALBEDO), 0.0)
    tsky = (np.maximum(1.0, TT["ir"][hs]) / (0.95 * 5.6697e-8)) ** 0.25 - 273.15
    out = {}
    for nm_, svf, T, wf in (("sun", 1.0, 1.0, 1.0), ("shade", 0.5, 0.0, 0.5)):
        D = svf * (c2 + 0.5 * (tsky - ta)) + c1 * T
        va = np.clip(TT["ws10"][hs] * wf, 0.5, 17.0)
        U_ = np.array([np.einsum("i,ij,j->", va[k] ** _P7, K[k, 0], D[k] ** _P7) for k in range(hs.size)])
        lh = TT["local"][hs]
        out[nm_] = [float(U_[lh == hh].mean()) if (lh == hh).any() else None for hh in range(24)]
    memo[mk] = out
    return out


def sheet_felt(S, B, X, Y, U, rects, d):
    CF = S.env["comfort"]
    G = CF["grid"]
    lo, hi = tsec_comfort_scales(S, tsec_lines(S))[1:]    # v16.5: the sections' scale, so plan and sections match
    win_ = analysis_window(S, "utci")                 # v16.5: one window for the plan and every felt section
    scs = {sd["key"]: stretch_scale(WINDY_TEMP, lo, hi, CF["seasons"][sd["key"]]["utci"], ab=win_) for sd in SEASONS}

    def render(sd):
        c = CF["seasons"][sd["key"]]
        p = os.path.join(d, "T7_felt_temperature_%s.png" % sd["key"])
        render_tech(p, S, S.F, 1.5, c["utci"], G["nx"], G["ny"], G["cell"], 0.5, scs[sd["key"]][0], roof="white", season=sd["key"],
                    canopy_alpha=0.22, rkey=fp(S.env["keys"]["comfort"], sd["key"], "utci", lo, hi))
        return p

    def side(sd, x, y, w, L):
        c = CF["seasons"][sd["key"]]
        vals = c["utci"][np.isfinite(c["utci"])]
        parts = []
        if c["utci_sun"] is not None:
            parts.append("{:.2f} °C IN SUN".format(c["utci_sun"]))
        if c["utci_shade"] is not None:
            parts.append("{:.2f} °C IN SHADE".format(c["utci_shade"]))
        t_title(B, x, y, "{} · MEAN FELT {:.2f} °C{}".format(sd["name"], float(vals.mean()) if vals.size else 0.0,
                                                             (" · " + " · ".join(parts)) if parts else ""), w, S.U, L)
        sv = c["sun"][np.isfinite(c["sun"])]
        B.fit("{} hours ({}) · air {:.2f} °C [1]".format("{:,}".format(c["hours"]), CF["label_short"], c["ta_mean"]),
              x, y - 0.9 * S.U, 0.3 * S.U, w, T_GREY, L)                     # v38: keywords; sun share as a tile
        sc_ = scs[sd["key"]]
        yy = stretch_bar(B, x, y - 1.5 * S.U, w * 0.46, WINDY_TEMP, lo, hi, sc_, S.U, L,
                         "UTCI °C, mean over the hours · same scale as T6", vals=c["utci"])
        yy = utci_band_marks(B, x, yy + 0.1 * S.U, w * 0.46, sc_[1], sc_[2], S.U, L)
        hist = c["hist"]
        tot = float(sum(hist)) or 1.0
        top = sorted(range(10), key=lambda k: -hist[k])[:4]
        tl = [("sun", "OPEN GROUND IN SUN · SUNNY h", "{:.0f} %".format(100.0 * float(sv.mean()) if sv.size else 0.0), "[7]")]
        tl += [("comfort" if k == 5 else "felt", (UTCI_NAMES[k] + ("" if k == 5 else " stress")).upper(),
                "{:.0f} %".format(100.0 * hist[k] / tot), "[6]") for k in sorted(top, key=lambda k: -k) if hist[k] > 0]
        vis_tiles(B, x, yy - 0.15 * S.U, w * 0.46, tl, S.U, L, cols=2, h=0.8)   # v38: every open spot, every hour (tiles)
        ref = utci_reference_day(S, sd["key"])
        site = c["by_hour"]
        vv = [v for v in ref["sun"] + ref["shade"] + site if v is not None]
        lo_c = math.floor(min(vv) / 5.0) * 5.0
        hi_c = math.ceil(max(vv) / 5.0) * 5.0
        bands = [(26.0, 32.0, (253, 236, 206), "moderate heat"), (32.0, 38.0, (250, 214, 180), "strong heat"),
                 (38.0, 46.0, (244, 186, 160), "very strong heat"), (46.0, 99.0, (232, 160, 150), "extreme heat"),
                 (0.0, 9.0, (214, 228, 240), "slight cold"), (-13.0, 0.0, (196, 214, 236), "moderate cold")]
        draw_day_chart(B, x + w * 0.5, y - 1.95 * S.U, w * 0.5, 5.2 * S.U,
                       [(ref["sun"], (200, 70, 30), 0.12, "open sun"), (ref["shade"], (40, 90, 150), 0.12, "street shade"),
                        (site, T_INK, 0.08, "site")], lo_c, hi_c, S.U, L, window=window_hours(CF), bands=bands)
        ky = y - 1.95 * S.U - 5.2 * S.U - 0.95 * S.U
        kx = x + w * 0.5 + 1.6 * S.U
        for col, lab in (((200, 70, 30), "open sun"), ((40, 90, 150), "street shade"), (T_INK, "this site's mean, window hours")):
            B.line([(kx, ky + 0.1 * S.U), (kx + 0.9 * S.U, ky + 0.1 * S.U)], col, L, 30, 0.14)
            B.text(lab, kx + 1.1 * S.U, ky, 0.22 * S.U, T_GREY, L)
            kx += 1.4 * S.U + tw(lab, 0.22 * S.U) + 0.6 * S.U
    tech_rows(S, B, X, Y, U, rects, "T7", "FELT TEMPERATURE · UTCI · FOUR SEASONS",
              "UTCI °C · air + humidity + wind + sun/shade · season [6]",
              comfort_sources(S) + [
                  "Universal Thermal Climate Index (Broede et al. 2012) every hour at every open 3 m cell, then averaged; "
                  "tiles: the share of every open spot and every hour in each stress class.",
                  "Mean radiant temperature from SolarCal (ASHRAE 55, outdoor form as in Ladybug): that hour's sun "
                  "or shade from every building, crown, the terrain and the ground's slope, the sky each spot sees, ground albedo "
                  "0.25 and the sky's long-wave radiation; that hour's wind as on T5.",
                  "Charts: the season's typical day; near "
                  "sunrise and sunset the site's mean holds only the days on which that hour is inside the window."],
              "Felt temperature", render, side)


