def es_hpa(t):
    """Saturation vapour pressure over water, hPa (Hardy 1998, as used with UTCI)."""
    g = (-2836.5744, -6028.076559, 19.54263612, -0.02737830188, 0.000016261698, 7.0229056e-10, -1.8680009e-13)
    tk = t + 273.15
    es = 2.7150305 * math.log(tk)
    for k, c in enumerate(g):
        es += c * tk ** (k - 2)
    return math.exp(es) * 0.01


def utci(ta, tr, va, pa):
    """Universal Thermal Climate Index (Broede et al. 2012, sixth-order approximation). pa: vapour pressure in kPa,
    va: wind at 10 m (0.5..17 m/s)."""
    va = min(17.0, max(0.5, va))
    d = tr - ta
    T, V, D, P = [1.0], [1.0], [1.0], [1.0]
    for _ in range(6):
        T.append(T[-1] * ta)
        V.append(V[-1] * va)
        D.append(D[-1] * d)
        P.append(P[-1] * pa)
    return sum(c * T[a] * V[b] * D[e] * P[f] for c, a, b, e, f in UTCI_COEF)


def stops_table(stops, vmin, vmax, n=1024):
    """Colour lookup over [vmin, vmax] from value stops (fast enough for every pixel)."""
    table = []
    for k in range(n):
        v = vmin + (vmax - vmin) * k / float(n - 1)
        c = stops[-1][1]
        if v <= stops[0][0]:
            c = stops[0][1]
        else:
            for q in range(len(stops) - 1):
                a, ca = stops[q]
                b, cb = stops[q + 1]
                if v <= b:
                    t = (v - a) / (b - a)
                    c = tuple(int(round(ca[r] + (cb[r] - ca[r]) * t)) for r in range(3))
                    break
        table.append(c)
    span = max(1e-9, vmax - vmin)

    def g(v):
        k = int((v - vmin) / span * (n - 1))
        return table[0 if k < 0 else (n - 1 if k >= n else k)]
    g._lut = ("ramp", vmin, span, n, table)
    return g


# ------------------------------------------------------------ drawing helpers
def page_north(F):
    return math.atan2(math.cos(F.ang), math.sin(F.ang))


def frame_dir(frame, vec):
    o = frame.local(0.0, 0.0)
    e = frame.local(vec[0], vec[1])
    return e[0] - o[0], e[1] - o[1]


def wind_streaks(frame, res, field, nx, ny, cell, to_local, seed=7, spacing=15):
    """Windy-like flow streaks: white strokes along the wind, longer where it blows harder, broken by buildings."""
    def post(rgb, w, h, TB):
        rnd = random.Random(seed)
        bid = TB["bid"]
        dx, dy = to_local[0], -to_local[1]
        for gy in range(0, h, spacing):
            for gx in range(0, w, spacing):
                px, py = gx + rnd.uniform(0, spacing), gy + rnd.uniform(0, spacing)
                ix, iy = int(px), int(py)
                if ix >= w or iy >= h or bid[iy * w + ix]:
                    continue
                i = int((px * res) / cell)
                j = int((frame.h - py * res) / cell)
                if not (0 <= i < nx and 0 <= j < ny) or field[j][i] is None:
                    continue
                U = field[j][i]
                L_ = max(3.0, U * 8.0 / res)
                n = int(L_ * 2.0) + 1
                strength = min(1.0, 0.3 + U / 2.5)
                for k in range(n, -1, -1):           # head first, stop at the first building behind it
                    t = k / float(n)
                    qx, qy = px - dx * L_ * (1.0 - t), py - dy * L_ * (1.0 - t)
                    qi, qj = int(qx), int(qy)
                    if not (0 <= qi < w and 0 <= qj < h) or bid[qj * w + qi]:
                        break
                    a = 0.8 * strength * t * t
                    for oi, oj, wgt in ((qi, qj, 1.0), (qi, qj + 1, 0.4)):
                        if 0 <= oj < h:
                            o = (oj * w + oi) * 3
                            for c in range(3):
                                rgb[o + c] = int(rgb[o + c] + (255 - rgb[o + c]) * a * wgt)
    post._key = repr((frame.P, res, nx, ny, cell, to_local, seed, spacing))
    return post


def draw_wind_rose(B, cx, cy, R, rose, calm, north, U, L):
    """Wind rose in the maps' orientation: where the wind comes from, stacked by speed (Windy colours)."""
    tot = [sum(r) for r in rose]
    fmax = max(tot) if tot else 0.1
    ring = 0.05 if fmax <= 0.3 else 0.1
    rmax = ring * math.ceil(fmax / ring)
    mids = (1.25, 3.0, 5.0, 7.0, 9.0, 11.0)
    cols = [stops_table(WINDY_WIND, 0.0, 12.0)(m) for m in mids]
    B.fill([circle_pts(cx, cy, R, 48)], (247, 247, 249), L, 20)
    r_ = ring
    while r_ <= rmax + 1e-9:
        B.line(circle_pts(cx, cy, R * r_ / rmax, 48) + [circle_pts(cx, cy, R * r_ / rmax, 48)[0]], (200, 200, 206), L, 21, 0.03)
        B.text("%d%%" % round(100 * r_), cx + 0.15 * U, cy + R * r_ / rmax + 0.08 * U, 0.22 * U, T_GREY, L)
        r_ += ring
    for k in range(16):
        a_mid = north - math.radians(k * 22.5)
        a0, a1 = a_mid - math.radians(9.0), a_mid + math.radians(9.0)
        cum = 0.0
        for c, f in enumerate(rose[k]):
            if f <= 0:
                continue
            r0, r1 = R * cum / rmax, R * (cum + f) / rmax
            arc1 = [(cx + r1 * math.cos(a0 + (a1 - a0) * q / 4.0), cy + r1 * math.sin(a0 + (a1 - a0) * q / 4.0)) for q in range(5)]
            arc0 = [(cx + r0 * math.cos(a1 - (a1 - a0) * q / 4.0), cy + r0 * math.sin(a1 - (a1 - a0) * q / 4.0)) for q in range(5)]
            B.fill([arc1 + arc0], cols[c], L, 22)
            cum += f
    for k, lab in ((0, "N"), (4, "E"), (8, "S"), (12, "W")):
        a = north - math.radians(k * 22.5)
        B.text(lab, cx + (R + 0.45 * U) * math.cos(a), cy + (R + 0.45 * U) * math.sin(a), 0.3 * U, T_INK, L,
               font=FONT_TITLE, bold=True, align="MC")
    B.line(circle_pts(cx, cy, R, 48) + [circle_pts(cx, cy, R, 48)[0]], T_RULE, L, 23, 0.04)
    B.text("calm %.0f%%" % (100 * calm), cx, cy - R - 0.85 * U, 0.24 * U, T_GREY, L, align="C")


def utci_band_marks(B, x, y, w, lo, hi, U, L):
    """The official UTCI stress categories under a temperature bar."""
    for k in range(len(UTCI_STRESS) - 1):
        top_, name = UTCI_STRESS[k - 1][0] if k > 0 else 99.0, UTCI_STRESS[k][1]
        b0, b1 = UTCI_STRESS[k][0], top_
        a0, a1 = max(lo, b0), min(hi, b1)
        if a1 <= a0:
            continue
        xa, xb = x + w * (a0 - lo) / (hi - lo), x + w * (a1 - lo) / (hi - lo)
        B.line([(xa, y), (xb, y)], T_INK, L, 31, 0.05)
        B.line([(xa, y - 0.1 * U), (xa, y + 0.1 * U)], T_INK, L, 31, 0.04)
        B.fit(name if name.startswith("no ") else name.replace(" stress", ""), (xa + xb) / 2.0, y - 0.42 * U, 0.2 * U,
              max(0.5 * U, xb - xa - 0.1 * U), T_GREY, L, align="C")
    return y - 0.75 * U


# ------------------------------------------------------------ v16.3: close extremes get stretched colours
# When the values of one picture cover only a small part of the shared scale (the air temperature of a section, which
# only height changes, spans a few tenths of a degree on a 40-degree scale), the picture's colours are stretched so the
# differences can be seen: the values' own range takes a wide window of the palette, placed where the values sit on the
# shared scale (warm stays warm, calm stays calm). Each stretched legend draws the shared scale as a thin bar with the
# stretched part bracketed, then its own bar with ticks in true units: the colours exaggerate, the numbers stay exact.
# v16.4: every picture whose values do not fill the shared scale is stretched, and the closer its extremes the more:
# the values' range always gets at least STRETCH_TO of the palette, so the gain is STRETCH_TO x scale / range (v16.3
# stretched only below 40 % of the scale, so wind, spread over about half of its scale, kept its close blues)
STRETCH_BELOW = 1.0     # stretch when the values (min-max, or 1st-99th percentile) span less than this share of the scale
STRETCH_TO = 0.75       # and give them at least this share of the palette
WIND_SCALE_HI = 15.0    # m/s: v16.4: wind takes Windy's colours from calm (0) to 15 m/s (blue, teal, green, olive, brown),
#                         all of them spread over the picture's own range; Windy's colours below the mean winds of the
#                         site (0-5 m/s) are only blues, which is why v16.3's wind pictures read as one colour
WIND_STRETCH_TO = 1.0   # the whole of that part of the palette


def finite_values(vals):
    """Every finite number in a field: a numpy array, or nested lists with None for no value."""
    if isinstance(vals, np.ndarray) and vals.dtype != object:
        v = vals.astype(float).ravel()
        return v[np.isfinite(v)]
    out = []
    stack = [vals]
    while stack:
        x = stack.pop()
        if x is None:
            continue
        if isinstance(x, (list, tuple, np.ndarray)):
            stack.extend(x)
            continue
        f = float(x)
        if math.isfinite(f):
            out.append(f)
    return np.asarray(out, float)


def analysis_window(S, kind):
    """v16.5: ONE colour window per analysis (kind "wind", "ta" or "utci"), shared by its plan's four seasons and every
    section of every line and season, so pictures compare with each other (v16.4 stretched each picture to its own
    values). The window is the 0.5th-99.5th percentile of all their values pooled; values beyond it take the end
    colours. Returns (a, b)."""
    CF = S.env["comfort"]
    lines = tsec_lines(S)
    sec_key = {"wind": "wind_sections", "ta": "air_sections", "utci": "felt_sections"}[kind]
    plan_k = {"wind": "uped", "ta": "ta", "utci": "utci"}[kind]
    memo = env_memo(S)
    mk = ("analysis_window", kind, S.env["keys"].get("comfort"), repr(lines.get(sec_key, [])), WINDOW_PCT)
    r = memo.get(mk)
    if r is not None:
        return r
    parts = []
    for sd in SEASONS:
        v = np.asarray(CF["seasons"][sd["key"]][plan_k], float).ravel()
        parts.append(v[np.isfinite(v)])
    for k, a, b in lines.get(sec_key, []):
        cf = tsec_comfort(S, tsec_geom(S, a, b))
        for sd in SEASONS:
            parts.append(finite_values(cf["seasons"][sd["key"]][kind]))
    v = np.concatenate([q for q in parts if q.size]) if any(q.size for q in parts) else np.zeros(0)
    if v.size < 2:
        r = None
    else:
        a, b = (float(q) for q in np.percentile(v, [WINDOW_PCT, 100.0 - WINDOW_PCT]))
        r = (a, b) if b > a else None
    memo[mk] = r
    return r


WINDOW_PCT = 0.5          # v16.5: the shared window leaves out this percentage of the values at either end


def stretch_scale(stops, lo, hi, vals, below=STRETCH_BELOW, to=STRETCH_TO, ab=None):
    """(lut, a, b, gain) for one picture. Not stretched: the shared [lo, hi] scale, gain 1.0. Stretched: the values'
    range [a, b] (min-max; the 1st-99th percentile when a few outliers alone make it wide) takes the colours of a window
    to x (hi - lo) wide on the shared palette, centred on where the values sit (kept inside the scale); gain = how many
    times the colours are stretched. Values beyond [a, b] (only the outer 1 % when percentiles were used) take the end
    colours."""
    plain = (stops_table(stops, lo, hi), lo, hi, 1.0)
    span = float(hi - lo)
    if ab is not None:                                # v16.5: the analysis' shared window (analysis_window)
        a, b = max(lo, ab[0]), min(hi, ab[1])
        if span <= 0 or b - a <= 1e-6 * span or b - a >= below * span:
            return plain
        v = None
    else:
        v = finite_values(vals)
        if v.size < 2 or span <= 0:
            return plain
        a, b = float(v.min()), float(v.max())
    if v is not None and b - a >= below * span:
        a, b = (float(q) for q in np.percentile(v, [1.0, 99.0]))
        if b - a >= below * span:
            return plain
    if b - a <= 1e-6 * span:                          # one value only: nothing to tell apart
        return plain
    width = max(to * span, b - a)                     # v16.4: never compressed (gain >= 1)
    gain = width / (b - a)
    c = min(max(0.5 * (a + b), lo + 0.5 * width), hi - 0.5 * width)
    pa = c - 0.5 * width
    st = [(a + (x - pa) / gain, col) for x, col in stops]     # the palette's stops in this picture's units
    return stops_table(st, a, b), a, b, gain


VAL_DEC = 2              # v16.6: values with decimals (temperatures, wind, kWh, dB) are printed with at least 2
VAL_FMT = "%.2f"         # (Nil: "we need at least 2 decimals"); counts, percentages, heights and distances unchanged


def tick_fmt(step, dec=None):
    """'%.Nf' with as many decimals as a tick step needs (v16.6: at least dec)."""
    d = dec or 0
    while d < 4 and abs(step * 10 ** d - round(step * 10 ** d)) > 1e-6:
        d += 1
    return "%." + str(d) + "f"


def stretch_bar(B, x, y, w, stops, lo, hi, sc, U, L, title, k=1.0, th=0.3, vals=None, dec=VAL_DEC):
    """Colour bar for a picture coloured with stretch_scale (sc). Stretched: the shared [lo, hi] scale as a thin bar with
    the stretched part bracketed, then the stretched bar with ticks in true units. k converts values to the unit shown
    (KT for knots). v16.5: the zoomed bar's two ends carry their numbers (the minimum and maximum of the analysis'
    shared window), and with vals this picture's own lowest and highest values are marked on it. Returns the y below
    it."""
    lut, a, b, gain = sc
    f10 = tick_fmt(nice_step((b - a) * k, 4) / 10.0, dec)
    if gain > 1.0:
        title += " · window {}-{}, plan + sections · colours x{}".format(          # v38: keywords (was a clause)
            f10 % (a * k), f10 % (b * k), ("%.1f" % gain) if gain < 9.95 else ("%.0f" % gain))
    B.fit(title, x, y, th * U, w, T_INK, L)
    y -= (0.35 + th) * U
    n = 60
    if gain > 1.0:
        full = stops_table(stops, lo, hi, 256)
        for q in range(n):
            B.fill([rect(x + w * q / n, y - 0.16 * U, x + w * (q + 1) / n + 0.01 * U, y)], full(lo + (hi - lo) * (q + 0.5) / n),
                   L, 30)
        f_ = tick_fmt(nice_step((hi - lo) * k, 4), dec)
        B.text(f_ % (lo * k), x - 0.12 * U, y - 0.15 * U, 0.18 * U, T_GREY, L, align="R")
        B.text(f_ % (hi * k), x + w + 0.12 * U, y - 0.15 * U, 0.18 * U, T_GREY, L)
        xa = x + w * (max(lo, a) - lo) / (hi - lo)
        xb = x + w * (min(hi, b) - lo) / (hi - lo)
        B.line([(xa, y + 0.06 * U), (xa, y - 0.22 * U), (xb, y - 0.22 * U), (xb, y + 0.06 * U)], T_INK, L, 31, 0.04)
        B.line([(xa, y - 0.22 * U), (x, y - 0.55 * U)], T_GREY, L, 31, 0.02)
        B.line([(xb, y - 0.22 * U), (x + w, y - 0.55 * U)], T_GREY, L, 31, 0.02)
        y -= 0.6 * U
        if vals is not None:                          # v16.5: room for the picture's min / max marks
            y -= 0.45 * U
    vv = finite_values(vals) if vals is not None else np.zeros(0)
    if vv.size and gain > 1.0:                        # v16.5: this picture's own lowest and highest values, above the bar
        for v_, lab_ in ((float(vv.min()), "min"), (float(vv.max()), "max")):
            tx = x + w * (min(b, max(a, v_)) - a) / (b - a)
            B.fill([[(tx, y + 0.02 * U), (tx - 0.12 * U, y + 0.22 * U), (tx + 0.12 * U, y + 0.22 * U)]], T_INK, L, 31)
            B.text("{} {}".format(lab_, f10 % (v_ * k)), tx, y + 0.3 * U, 0.2 * U, T_INK, L,
                   align="R" if lab_ == "min" else "L")
    for q in range(n):
        B.fill([rect(x + w * q / n, y - 0.45 * U, x + w * (q + 1) / n + 0.01 * U, y)], lut(a + (b - a) * (q + 0.5) / n), L, 30)
    step = nice_step((b - a) * k, 4)
    f_ = tick_fmt(step, dec)
    ends = gain > 1.0                                 # v16.5: the zoomed bar's ends carry their own numbers
    t = math.ceil(a * k / step - 1e-9) * step
    while t <= b * k + 1e-9:
        tx = x + w * (t / k - a) / (b - a)
        if not ends or min(tx - x, x + w - tx) > 0.9 * U:
            B.line([(tx, y - 0.45 * U), (tx, y - 0.62 * U)], T_INK, L, 31, 0.04)
            B.text(f_ % t, tx, y - 1.0 * U, 0.24 * U, T_INK, L, align="C")
        t += step
    if ends:
        for tx, v_, al in ((x, a, "L"), (x + w, b, "R")):
            B.line([(tx, y - 0.45 * U), (tx, y - 0.7 * U)], T_INK, L, 31, 0.06)
            B.text(f10 % (v_ * k), tx, y - 1.0 * U, 0.26 * U, T_INK, L, align=al, bold=True)
    return y - 1.45 * U


def stretch_levels(sc, base):
    """Contour levels for a stretched picture (about five inside its range); the given ones when not stretched."""
    lut, a, b, gain = sc
    if gain <= 1.0:
        return base
    step = nice_step(b - a, 5)
    v = math.ceil(a / step + 1e-9) * step
    out = []
    while v < b - 1e-9:
        out.append(round(v, 6))
        v += step
    return out


# ------------------------------------------------------------ the three sheets
# ============================================================ SECTION ART: a small raster engine (numpy only)
# Anti-aliased polygons, strokes and soft discs on a float RGB canvas, composited with "over". Used to draw the soft
# part of every section (trees at their measured size, buildings beyond the cut, ground beyond, scale figures, the
# analysis wash); the crisp part (the cut, the ground line, text) stays vector on top of the picture.


class SArt(object):
    """A canvas in pixels: x to the right, y down. rgb is float32 0..1."""

    def __init__(self, W, H, bg=(1.0, 1.0, 1.0)):
        self.W, self.H = int(W), int(H)
        self.rgb = np.empty((self.H, self.W, 3), np.float32)
        self.rgb[:] = np.asarray(bg, np.float32)

    def over(self, x0, y0, cov, col, alpha=1.0):
        """Composite colour col (rgb 0..1, or an (h, w, 3) array) with coverage cov (h, w) at (x0, y0)."""
        h, w = cov.shape
        xa, ya = max(0, x0), max(0, y0)
        xb, yb = min(self.W, x0 + w), min(self.H, y0 + h)
        if xb <= xa or yb <= ya:
            return
        c = cov[ya - y0:yb - y0, xa - x0:xb - x0]
        a = (c * alpha)[..., None]
        dst = self.rgb[ya:yb, xa:xb]
        if isinstance(col, np.ndarray) and col.ndim == 3:
            src = col[ya - y0:yb - y0, xa - x0:xb - x0]
        else:
            src = np.asarray(col, np.float32)
        dst *= (1.0 - a)
        dst += a * src

    def to_bytes(self):
        return (np.clip(self.rgb, 0.0, 1.0) * 255.0 + 0.5).astype(np.uint8)


def sa_poly_cov(polys, ss=4, clip=None):
    """Even-odd coverage of one or more rings (lists of (x, y) pixel points): exact across x, ss samples per pixel down y.
    Returns (x0, y0, cov) or None. clip = (W, H) limits the box."""
    rings = [np.asarray(P, np.float64) for P in polys if P is not None and len(P) >= 3]
    if not rings:
        return None
    allp = np.concatenate(rings)
    x0 = int(math.floor(allp[:, 0].min()))
    y0 = int(math.floor(allp[:, 1].min()))
    x1 = int(math.ceil(allp[:, 0].max())) + 1
    y1 = int(math.ceil(allp[:, 1].max())) + 1
    if clip is not None:
        x0, y0 = max(x0, 0), max(y0, 0)
        x1, y1 = min(x1, clip[0]), min(y1, clip[1])
    w, h = x1 - x0, y1 - y0
    if w <= 0 or h <= 0:
        return None
    ax, ay, bx, by = [], [], [], []
    for R in rings:
        S_ = np.roll(R, -1, axis=0)
        ax.append(R[:, 0]); ay.append(R[:, 1]); bx.append(S_[:, 0]); by.append(S_[:, 1])
    ax = np.concatenate(ax) - x0
    ay = np.concatenate(ay) - y0
    bx = np.concatenate(bx) - x0
    by = np.concatenate(by) - y0
    keep = ay != by
    ax, ay, bx, by = ax[keep], ay[keep], bx[keep], by[keep]
    if ax.size == 0:
        return None
    ys = (np.arange(h * ss) + 0.5) / ss                          # sample rows
    # crossings of every edge with every sample row (half-open in y so vertices count once)
    lo = np.minimum(ay, by)
    hi = np.maximum(ay, by)
    out_cov = np.zeros((h, w + 2), np.float64)
    # process sample rows in chunks to bound memory
    E = ax.size
    chunk = max(1, int(4_000_000 // max(1, E)))
    for r0 in range(0, ys.size, chunk):
        yy = ys[r0:r0 + chunk][:, None]
        m = (yy >= lo) & (yy < hi)
        if not m.any():
            continue
        t = (yy - ay) / (by - ay)
        xs = np.where(m, ax + t * (bx - ax), np.inf)
        xs.sort(axis=1)
        k = m.sum(axis=1)
        kmax = int(k.max())
        if kmax < 2:
            continue
        xs = xs[:, :kmax - (kmax % 2)]
        a_ = xs[:, 0::2]
        b_ = xs[:, 1::2]
        ok = np.isfinite(a_) & np.isfinite(b_)
        rows = np.broadcast_to(((np.arange(r0, r0 + yy.shape[0])) // ss)[:, None], a_.shape)[ok]
        a_ = np.clip(a_[ok], 0.0, w)
        b_ = np.clip(b_[ok], 0.0, w)
        good = b_ > a_
        if not good.any():
            continue
        rows, a_, b_ = rows[good], a_[good], b_[good]
        # integral F(i) = sum over spans of clip(i - a, 0, b - a); pixel i covers F(i + 1) - F(i)
        W2 = w + 2
        for v, sgn in ((a_, 1.0), (b_, -1.0)):
            ci = np.ceil(v).astype(np.int64)
            idx = rows * W2 + np.clip(ci, 0, W2 - 1)
            cnt = np.bincount(idx, minlength=h * W2).reshape(h, W2)
            sm = np.bincount(idx, weights=v, minlength=h * W2).reshape(h, W2)
            c = np.cumsum(cnt, axis=1)
            s = np.cumsum(sm, axis=1)
            i = np.arange(W2)[None, :]
            out_cov += sgn * (i * c - s)
    cov = (out_cov[:, 1:w + 1] - out_cov[:, :w]) / ss
    return x0, y0, np.clip(cov, 0.0, 1.0).astype(np.float32)


def sa_fill(art, polys, col, alpha=1.0, ss=4):
    r = sa_poly_cov(polys, ss, clip=(art.W, art.H))
    if r is not None:
        art.over(r[0], r[1], r[2], col, alpha)


def sa_stroke_polys(P, w):
    """Quads (and small square joints) covering a polyline of width w (pixels)."""
    out = []
    hw = 0.5 * w
    for i in range(len(P) - 1):
        (x0, y0), (x1, y1) = P[i], P[i + 1]
        dx, dy = x1 - x0, y1 - y0
        L = math.hypot(dx, dy)
        if L < 1e-9:
            continue
        nx, ny = -dy / L * hw, dx / L * hw
        ex, ey = dx / L * hw * 0.5, dy / L * hw * 0.5           # a short cap so joints close
        out.append([(x0 - ex + nx, y0 - ey + ny), (x1 + ex + nx, y1 + ey + ny), (x1 + ex - nx, y1 + ey - ny),
                    (x0 - ex - nx, y0 - ey - ny)])
    return out


def sa_line_cov(P, w, clip, ss=4):
    """Coverage of a stroked polyline (union of its segment quads, max-combined)."""
    quads = sa_stroke_polys(P, w)
    if not quads:
        return None
    allp = np.asarray([p for q in quads for p in q])
    x0 = max(0, int(math.floor(allp[:, 0].min())))
    y0 = max(0, int(math.floor(allp[:, 1].min())))
    x1 = min(clip[0], int(math.ceil(allp[:, 0].max())) + 1)
    y1 = min(clip[1], int(math.ceil(allp[:, 1].max())) + 1)
    if x1 <= x0 or y1 <= y0:
        return None
    acc = np.zeros((y1 - y0, x1 - x0), np.float32)
    for q in quads:
        r = sa_poly_cov([q], ss, clip=clip)
        if r is None:
            continue
        qx, qy, c = r
        h, w_ = c.shape
        sub = acc[qy - y0:qy - y0 + h, qx - x0:qx - x0 + w_]
        np.maximum(sub, c[:sub.shape[0], :sub.shape[1]], out=sub)
    return x0, y0, acc


def sa_stroke(art, P, w, col, alpha=1.0):
    r = sa_line_cov(P, w, (art.W, art.H))
    if r is not None:
        art.over(r[0], r[1], r[2], col, alpha)


def sa_blob_cov(cx, cy, r, soft=0.8, wob=None, clip=None):
    """A disc of radius r (pixels) with an edge softened over `soft` pixels; wob = [(amplitude, frequency, phase)]
    makes the edge irregular (leaf clumps)."""
    R = r * (1.0 + (sum(abs(a) for a, f, p in wob) if wob else 0.0)) + soft + 1.0
    x0, y0 = int(math.floor(cx - R)), int(math.floor(cy - R))
    x1, y1 = int(math.ceil(cx + R)) + 1, int(math.ceil(cy + R)) + 1
    if clip is not None:
        x0, y0 = max(0, x0), max(0, y0)
        x1, y1 = min(clip[0], x1), min(clip[1], y1)
    if x1 <= x0 or y1 <= y0:
        return None
    yy, xx = np.mgrid[y0:y1, x0:x1].astype(np.float32)
    dx, dy = xx + 0.5 - cx, yy + 0.5 - cy
    d = np.sqrt(dx * dx + dy * dy)
    rr = np.float32(r)
    if wob:
        th = np.arctan2(dy, dx)
        m = np.ones_like(th)
        for a, f, p in wob:
            m += a * np.sin(f * th + p)
        rr = r * m
    cov = np.clip((rr - d) / max(0.5, soft) + 0.5, 0.0, 1.0)
    return x0, y0, cov.astype(np.float32)


def sa_blob(art, cx, cy, r, col, alpha=1.0, soft=0.8, wob=None):
    b = sa_blob_cov(cx, cy, r, soft, wob, (art.W, art.H))
    if b is not None:
        art.over(b[0], b[1], b[2], col, alpha)


def sa_mix(a, b, t):
    return tuple(float(a[i]) * (1.0 - t) + float(b[i]) * t for i in range(3))


# ============================================================ SECTION ART: trees and scale figures

# foliage palettes (light, mid, shadow), 0..255: deciduous by season, evergreen broadleaf (olive), needle-leaved
SA_TREE_PAL = {
    "tree": ((178, 196, 132), (140, 164, 102), (104, 128, 82)),
    "tree_spring": ((198, 214, 146), (168, 192, 114), (132, 158, 94)),
    "tree_autumn": ((196, 190, 124), (166, 160, 100), (128, 128, 84)),
    "olive": ((190, 196, 166), (154, 164, 132), (116, 128, 104)),
    "pine": ((132, 158, 124), (100, 128, 102), (74, 98, 82)),
}
SA_TRUNK = (110, 98, 90)


class SASprite(object):
    """A small premultiplied RGBA buffer a tree is drawn into before it is laid on the canvas as one piece."""

    def __init__(self, x0, y0, w, h):
        self.x0, self.y0, self.w, self.h = int(x0), int(y0), int(w), int(h)
        self.c = np.zeros((self.h, self.w, 3), np.float32)
        self.a = np.zeros((self.h, self.w), np.float32)

    def over(self, x0, y0, cov, col, alpha=1.0):
        h, w = cov.shape
        xa, ya = max(self.x0, x0), max(self.y0, y0)
        xb, yb = min(self.x0 + self.w, x0 + w), min(self.y0 + self.h, y0 + h)
        if xb <= xa or yb <= ya:
            return
        s = (cov[ya - y0:yb - y0, xa - x0:xb - x0] * alpha)
        dc = self.c[ya - self.y0:yb - self.y0, xa - self.x0:xb - self.x0]
        da = self.a[ya - self.y0:yb - self.y0, xa - self.x0:xb - self.x0]
        k = (1.0 - s)
        dc *= k[..., None]
        dc += s[..., None] * np.asarray(col, np.float32)
        da *= k
        da += s

    def onto(self, art, alpha=1.0, toward=None, fade=0.0):
        """Lay the sprite on the canvas; fade > 0 mixes its colours toward `toward` (atmosphere)."""
        xa, ya = max(0, self.x0), max(0, self.y0)
        xb, yb = min(art.W, self.x0 + self.w), min(art.H, self.y0 + self.h)
        if xb <= xa or yb <= ya:
            return
        c = self.c[ya - self.y0:yb - self.y0, xa - self.x0:xb - self.x0]
        a = self.a[ya - self.y0:yb - self.y0, xa - self.x0:xb - self.x0]
        if fade > 0.0 and toward is not None:
            c = c * (1.0 - fade) + a[..., None] * np.asarray(toward, np.float32) * fade
        k = (a * alpha)[..., None]
        dst = art.rgb[ya:yb, xa:xb]
        dst *= (1.0 - k)
        dst += c * alpha


def _sa_c(c):
    return tuple(v / 255.0 for v in c)


def _sa_mix(a, b, t):
    return tuple(a[i] * (1.0 - t) + b[i] * t for i in range(3))


def sa_tree(kind, px, gy, yb, yt, hw, seed, leaf=1.0, season=""):
    """One tree in elevation at its measured size, pixels: trunk from the ground (gy) to the crown base (yb), crown
    from yb up to yt, hw wide each side. leaf: share of foliage for deciduous crowns (0 = bare)."""
    rnd = random.Random(seed)
    hh = 0.5 * (yb - yt)                       # crown half height (pixels, y down)
    if hh < 0.6 or hw < 0.6:
        return None
    cy = 0.5 * (yb + yt)
    pad = 2.0
    x0 = int(math.floor(px - hw * 1.3 - pad))
    y0 = int(math.floor(yt - hh * 0.3 - pad))
    x1 = int(math.ceil(px + hw * 1.3 + pad))
    y1 = int(math.ceil(gy + pad))
    sp = SASprite(x0, y0, x1 - x0, y1 - y0)
    clip = None
    size = max(hw, hh)
    if kind == "pine":
        pal = SA_TREE_PAL["pine"]
    elif kind == "olive":
        pal = SA_TREE_PAL["olive"]
    else:
        pal = SA_TREE_PAL.get("tree_" + season, SA_TREE_PAL["tree"])
    lt, md, sh = _sa_c(pal[0]), _sa_c(pal[1]), _sa_c(pal[2])
    trunk = _sa_c(SA_TRUNK)
    lean = rnd.uniform(-0.06, 0.06) * hh
    # ---- trunk: tapered, a little leaning, into the lower crown
    tb = max(0.7, min(0.16 * hw, 0.05 * (gy - yt) + 0.6))        # trunk width at the ground (pixels)
    tt = max(0.5, 0.55 * tb)
    ytop_tr = yb - (0.35 if kind != "pine" else 0.9) * (yb - yt) * (0.5 if leaf > 0.3 or kind != "tree" else 1.0)
    tr = [(px - tb / 2, gy), (px + tb / 2, gy), (px + lean + tt / 2, ytop_tr), (px + lean - tt / 2, ytop_tr)]
    r = sa_poly_cov([tr], 4)
    if r is not None:
        sp.over(r[0], r[1], r[2], trunk, 0.95)
    # ---- branches: a few limbs into the crown; for a bare deciduous crown the whole structure, finer and finer
    if kind != "pine":
        nb = 3 + rnd.randint(0, 2)
        depth = 4 if (kind == "tree" and leaf < 0.5) else 2
        stack = []
        for k in range(nb):
            ang = math.radians(rnd.uniform(-58, 58) + (k - (nb - 1) / 2.0) * 10.0)
            ln = (0.55 + 0.35 * rnd.random()) * hh * 1.25
            stack.append((px + lean * 0.8, yb - 0.05 * (yb - yt), ang, ln, max(0.5, tt * 0.75), depth))
        while stack:
            bx, by, ang, ln, wd, dp = stack.pop()
            ex, ey = bx + math.sin(ang) * ln * (hw / max(hh, 1e-6)) ** 0.5, by - math.cos(ang) * ln
            # keep inside the crown envelope
            nx_, ny_ = (ex - px) / max(hw, 1e-6), (ey - cy) / max(hh, 1e-6)
            m = math.hypot(nx_, ny_)
            lim = 0.92 if (kind == "tree" and leaf < 0.5) else 0.62
            if m > lim:
                ex, ey = px + nx_ / m * lim * hw, cy + ny_ / m * lim * hh
            rr = sa_line_cov([(bx, by), (ex, ey)], wd, (10 ** 9, 10 ** 9))
            if rr is not None:
                sp.over(rr[0], rr[1], rr[2], trunk, 0.85 if leaf < 0.5 or kind != "tree" else 0.7)
            if dp > 1 and wd > 0.35:
                for sgn in (-1, 1):
                    stack.append((ex * 0.4 + bx * 0.6, ey * 0.4 + by * 0.6, ang + sgn * math.radians(rnd.uniform(22, 38)),
                                  ln * rnd.uniform(0.5, 0.68), wd * 0.62, dp - 1))
                stack.append((ex, ey, ang + math.radians(rnd.uniform(-18, 18)), ln * 0.55, wd * 0.6, dp - 1))
    # ---- foliage
    if kind == "tree" and leaf <= 0.02:
        return sp
    dens = leaf if kind == "tree" else 1.0
    if kind == "pine" and hw < 0.42 * hh:
        _sa_cypress(sp, rnd, px + lean, yb, yt, hw, lt, md, sh)
        return sp
    if kind == "pine":
        _sa_pine(sp, rnd, px + lean, yb, yt, hw, hh, lt, md, sh)
        return sp
    # rounded crowns (deciduous, olive): a mass, then leaf clumps over it, lit from the upper left
    _sa_round(sp, rnd, px + lean * 0.6, cy, hw, hh, lt, md, sh, dens, kind)
    return sp


def _sa_lumpy(rnd, cx, cy, rx, ry, n=28, amp=0.06):
    ph = [rnd.uniform(0, 6.3) for _ in range(3)]
    P = []
    for q in range(n):
        a = 2 * math.pi * q / n
        k = 1.0 + amp * (math.sin(5 * a + ph[0]) + 0.6 * math.sin(8 * a + ph[1]) + 0.4 * math.sin(13 * a + ph[2])) / 2.0
        P.append((cx + math.cos(a) * rx * k, cy + math.sin(a) * ry * k))
    return P


def _sa_round(sp, rnd, cx, cy, hw, hh, lt, md, sh, dens, kind):
    olive = kind == "olive"
    a_mass = (0.88 if not olive else 0.82) * (0.35 + 0.65 * dens)
    # the mass: slightly smaller than the envelope so the clumps make the edge
    P = _sa_lumpy(rnd, cx, cy + 0.04 * hh, hw * 0.86, hh * 0.84, amp=0.08)
    r = sa_poly_cov([P], 4)
    if r is not None:
        sp.over(r[0], r[1], r[2], _sa_mix(md, sh, 0.25), a_mass)
    m = min(hw, hh)
    rc = max(0.9, (0.22 if olive else 0.26) * m + 0.04 * max(hw, hh))
    area = math.pi * hw * hh
    n = int(max(8, min(90, 2.2 * area / (math.pi * rc * rc))))
    n = max(4, int(round(n * (0.35 + 0.65 * dens))))
    pts = []
    nr = int(n * 0.5)
    for k in range(n):
        if k < nr:                                          # the rim: a scalloped silhouette
            th = 2 * math.pi * (k + rnd.random() * 0.7) / max(1, nr)
            rr_ = 0.80 + 0.12 * rnd.random()
            sz = rnd.uniform(0.7, 1.0)
        else:
            th = rnd.uniform(0, 2 * math.pi)
            rr_ = math.sqrt(rnd.random()) * 0.75
            sz = rnd.uniform(0.85, 1.25)
        pts.append((cx + math.cos(th) * rr_ * (hw - rc * 0.5), cy + math.sin(th) * rr_ * (hh - rc * 0.5), sz))

    def light(p):
        return -((p[0] - cx) / max(hw, 1e-6)) * 0.55 - ((p[1] - cy) / max(hh, 1e-6)) * 0.85
    pts.sort(key=light)
    alpha = (0.9 if not olive else 0.86) * (0.5 + 0.5 * dens)
    for (x_, y_, sz) in pts:
        lv = max(0.0, min(1.0, 0.5 + 0.55 * light((x_, y_))))
        col = _sa_mix(sh, md, min(1.0, lv * 1.9)) if lv < 0.52 else _sa_mix(md, lt, (lv - 0.52) / 0.48)
        j = rnd.uniform(-0.03, 0.03)
        col = tuple(max(0.0, min(1.0, c_ + j)) for c_ in col)
        rk = rc * sz
        wob = [(rnd.uniform(0.06, 0.13), rnd.choice((5, 6, 7)), rnd.uniform(0, 6.3)),
               (rnd.uniform(0.03, 0.06), rnd.choice((9, 11, 13)), rnd.uniform(0, 6.3))]
        b = sa_blob_cov(x_, y_, rk, soft=0.85, wob=wob)
        if b is not None:
            sp.over(b[0], b[1], b[2], col, alpha)
    # a few bright touches on the lit side
    for k in range(max(2, n // 8)):
        th = rnd.uniform(math.pi * 1.05, math.pi * 1.6)
        rr_ = rnd.uniform(0.35, 0.7)
        b = sa_blob_cov(cx + math.cos(th) * rr_ * hw, cy + math.sin(th) * rr_ * hh, rc * rnd.uniform(0.45, 0.7), soft=0.9)
        if b is not None:
            sp.over(b[0], b[1], b[2], _sa_mix(lt, (1.0, 1.0, 1.0), 0.18), 0.55 * alpha)


def _sa_cypress(sp, rnd, px, yb, yt, hw, lt, md, sh):
    """A narrow needle-leaved crown (cypress-like flame) at its measured width and height, with a scalloped edge."""
    H = yb - yt
    n = max(12, int(H / 1.5))
    left, right = [], []
    ph = rnd.uniform(0, 6.3)
    for k in range(n + 1):
        t = k / float(n)                                    # 0 = top, 1 = crown base
        w = hw * (math.sin(min(1.0, t * 1.2) * math.pi * 0.5) ** 0.75) * (1.0 - 0.25 * max(0.0, t - 0.88) / 0.12)
        bump = 1.0 + 0.10 * math.sin(t * 23.0 + ph) + rnd.uniform(-0.05, 0.05)
        y = yt + t * H
        left.append((px - w * bump, y))
        right.append((px + w * (2.0 - bump) * 0.98, y))
    P = right + left[::-1]
    r = sa_poly_cov([P], 4)
    if r is not None:
        sp.over(r[0], r[1], r[2], md, 0.95)
    P2 = [(x * 0.5 + (px - 0.05 * hw) * 0.5, y) for x, y in left[1:-1]] + [(px - 0.05 * hw, yb - 0.08 * H), (px - 0.05 * hw, yt + 0.08 * H)]
    r = sa_poly_cov([P2], 4)
    if r is not None:
        sp.over(r[0], r[1], r[2], lt, 0.5)
    P3 = [(x * 0.55 + (px + 0.25 * hw) * 0.45, y) for x, y in right[2:-1]][::-1] + [(px + 0.25 * hw, yt + 0.15 * H), (px + 0.25 * hw, yb - 0.1 * H)]
    r = sa_poly_cov([P3], 4)
    if r is not None:
        sp.over(r[0], r[1], r[2], sh, 0.45)


def _sa_pine(sp, rnd, px, yb, yt, hw, hh, lt, md, sh):
    """A needle-leaved crown: flat tufts on bare limbs, the widest near the top, at its measured width and height."""
    H = yb - yt
    trunk = _sa_c(SA_TRUNK)
    pads = []
    # the canopy: a broad, lumpy top layer
    ntop = 3 + rnd.randint(0, 2)
    for k in range(ntop):
        tx = px + (k - (ntop - 1) / 2.0) / max(1.0, (ntop - 1) / 2.0) * hw * 0.55 + rnd.uniform(-0.08, 0.08) * hw
        ty = yt + H * rnd.uniform(0.16, 0.32)
        pads.append((tx, ty, hw * rnd.uniform(0.42, 0.58), H * rnd.uniform(0.15, 0.22)))
    # lower tufts, alternating sides, smaller downwards
    nlow = max(1, min(5, int(H / max(3.0, hw * 0.7))))
    for k in range(nlow):
        t = 0.42 + 0.5 * (k + 0.5) / nlow
        side = -1 if (k + rnd.randint(0, 1)) % 2 else 1
        sc = 1.0 - 0.45 * t
        tx = px + side * hw * rnd.uniform(0.25, 0.5) * sc
        ty = yt + t * H
        pads.append((tx, ty, hw * rnd.uniform(0.3, 0.45) * sc, H * rnd.uniform(0.09, 0.14)))
        rr = sa_line_cov([(px, ty + 0.12 * H), (tx, ty)], max(0.45, hw * 0.045), (10 ** 9, 10 ** 9))
        if rr is not None:
            sp.over(rr[0], rr[1], rr[2], trunk, 0.85)
    for k in range(ntop):
        tx, ty = pads[k][0], pads[k][1]
        rr = sa_line_cov([(px, yt + 0.55 * H), (tx, ty + 0.05 * H)], max(0.45, hw * 0.05), (10 ** 9, 10 ** 9))
        if rr is not None:
            sp.over(rr[0], rr[1], rr[2], trunk, 0.85)
    pads.sort(key=lambda p: -p[1])
    for tx, ty, rx, ry in pads:
        P = _sa_lumpy(rnd, tx, ty, rx, ry, n=24, amp=0.14)
        P = [(x, y if y < ty else ty + (y - ty) * 0.75) for x, y in P]          # flatter underside
        r = sa_poly_cov([P], 4)
        if r is not None:
            sp.over(r[0], r[1], r[2], _sa_mix(md, sh, 0.35), 0.93)
        P2 = _sa_lumpy(rnd, tx - rx * 0.12, ty - ry * 0.25, rx * 0.72, ry * 0.55, n=20, amp=0.12)
        r = sa_poly_cov([P2], 4)
        if r is not None:
            sp.over(r[0], r[1], r[2], _sa_mix(md, lt, 0.55), 0.75)


# ---- scale figures: simple silhouettes in metres (feet at 0, 0; y up), 1.75 m tall before scaling
SA_FIGS = [
    # standing
    [(-0.10, 0.0), (-0.06, 0.0), (-0.03, 0.82), (0.03, 0.82), (0.06, 0.0), (0.10, 0.0), (0.12, 0.85), (0.16, 1.38),
     (0.10, 1.47), (0.05, 1.50), (0.05, 1.53), (-0.05, 1.53), (-0.05, 1.50), (-0.10, 1.47), (-0.16, 1.38), (-0.12, 0.85)],
    # walking
    [(-0.30, 0.0), (-0.24, 0.0), (-0.02, 0.78), (0.18, 0.0), (0.25, 0.0), (0.11, 0.86), (0.18, 1.12), (0.12, 1.40),
     (0.06, 1.48), (0.05, 1.53), (-0.05, 1.53), (-0.07, 1.47), (-0.14, 1.38), (-0.20, 1.10), (-0.12, 0.86)],
    # in a dress / long coat
    [(-0.20, 0.0), (0.20, 0.0), (0.13, 0.62), (0.11, 1.08), (0.15, 1.36), (0.09, 1.45), (0.05, 1.49), (0.05, 1.52),
     (-0.05, 1.52), (-0.05, 1.49), (-0.09, 1.45), (-0.15, 1.36), (-0.11, 1.08), (-0.13, 0.62)],
    # with a bag
    [(-0.11, 0.0), (-0.06, 0.0), (-0.02, 0.80), (0.04, 0.80), (0.08, 0.0), (0.13, 0.0), (0.12, 0.86), (0.30, 0.86),
     (0.30, 0.55), (0.40, 0.55), (0.40, 0.95), (0.17, 1.38), (0.10, 1.47), (0.05, 1.51), (0.05, 1.53), (-0.05, 1.53),
     (-0.05, 1.50), (-0.10, 1.47), (-0.16, 1.38), (-0.13, 0.86)],
]
SA_HEAD = (0.0, 1.64, 0.105)


def sa_figure(kind, x, gz, scale, flip, ppm, x_px, y_px):
    """A figure's body and head in pixels: x along the line (m), gz ground level (m); x_px, y_px map (s, z) -> px."""
    body = SA_FIGS[kind % len(SA_FIGS)]
    sg = -1.0 if flip else 1.0
    P = [x_px(x + sg * bx * scale) for bx, by in body]
    P = [(x_px(x + sg * bx * scale), y_px(gz + by * scale)) for bx, by in body]
    hx, hy, hr = SA_HEAD
    return P, (x_px(x + sg * hx * scale), y_px(gz + hy * scale), hr * scale * ppm)


# ============================================================ SECTION ART: what a section sees beyond its cut
# Everything here is measured: the ground beyond (survey terrain), the buildings beyond (survey footprints at their
# heights), the trees (canopy height map: crown radius, height, leaf type). Only the scale figures are not data: they
# stand on the walkable ground of the cut to give the scale, as in any architectural section.
SA_DEPTH_B = 120.0          # m: buildings beyond the cut are drawn up to this distance
SA_DEPTH_T = 90.0           # m: trees beyond the cut
SA_BANDS = (5.0, 10.0, 16.0, 24.0, 34.0, 46.0, 60.0, 76.0, 95.0, 118.0)    # m: the ground beyond, seen at these depths


def sa_crowns(S):
    """Every crown of the canopy height map near the frame as (x, y, radius, height, kind), on a grid; crowns standing on
    a roof are misreadings and left out, as in the analyses."""
    g = getattr(S, "g_sacrown", None)
    if g is not None:
        return g
    E = (getattr(S, "env", None) or {}).get("E")
    if E is None and ENV_PATH:
        try:
            E, _ = load_env(ENV_PATH)
        except Exception:
            E = None
    fb = S.F.bb
    g = Grid(20.0)
    for row in (E or {}).get("trees", []):
        x, y, r, h = row[:4]
        if h < 3.0 or not (fb[0] - 150 <= x <= fb[2] + 150 and fb[1] - 150 <= y <= fb[3] + 150):
            continue
        if any(in_unit(x, y, u) for u in S.g_bld.query((x, y, x, y))):
            continue
        kind = LEAF_KIND.get(int(row[4]), "tree") if len(row) > 5 else "tree"
        g.add((x, y, r, h, kind), (x - r, y - r, x + r, y + r))
    S.g_sacrown = g
    return g


def sa_scene(S, a, b):
    """The view beyond the cut a -> b, looking to its left (as every section of this script): ground at SA_BANDS depths,
    buildings and crowns beyond, bridges, and where scale figures may stand on the cut. Absolute heights (m a.s.l.)."""
    memo = getattr(S, "_sa_memo", None)
    if memo is None:
        memo = S._sa_memo = {}
    mk = (tuple(a), tuple(b))
    if mk in memo:
        return memo[mk]
    (x0, y0), (x1, y1) = a, b
    L = math.hypot(x1 - x0, y1 - y0)
    ux, uy = (x1 - x0) / L, (y1 - y0) / L
    nx, ny = -uy, ux
    F = S.F
    # ---- the ground beyond: one profile per depth, cut where it leaves the surveyed terrain (frame + 40 m)
    ns = max(2, int(L / 1.5) + 1)
    ss_ = np.linspace(0.0, L, ns)
    bands = []
    for d in SA_BANDS:
        X = x0 + ux * ss_ + nx * d
        Y = y0 + uy * ss_ + ny * d
        Z = z_np(S, X, Y)
        lu = F._lc * (X - F.cx) - F._ls * (Y - F.cy)
        lv = F._ls * (X - F.cx) + F._lc * (Y - F.cy)
        ok = (lu >= F.u0 - 40.0) & (lu <= F.u1 + 40.0) & (lv >= F.v0 - 40.0) & (lv <= F.v1 + 40.0)
        bands.append((d, ss_.copy(), np.where(ok, Z, np.nan)))
    # ---- buildings beyond: the survey footprint seen from the cut, from its lowest ground to its roof
    band = (min(x0, x1, x0 + nx * SA_DEPTH_B, x1 + nx * SA_DEPTH_B) - 5.0,
            min(y0, y1, y0 + ny * SA_DEPTH_B, y1 + ny * SA_DEPTH_B) - 5.0,
            max(x0, x1, x0 + nx * SA_DEPTH_B, x1 + nx * SA_DEPTH_B) + 5.0,
            max(y0, y1, y0 + ny * SA_DEPTH_B, y1 + ny * SA_DEPTH_B) + 5.0)
    bld = []
    for u in S.g_bld.query(band):
        if u.get("h", 0.0) <= 0.0:
            continue
        pts = [p for P in u["parts"] for p in P]
        if not pts:
            continue
        dv = [(px - x0) * nx + (py - y0) * ny for px, py in pts]
        if min(dv) < 0.0 or min(dv) > SA_DEPTH_B:           # cut by the plane (drawn as cut) or behind the viewer
            continue
        sv = [(px - x0) * ux + (py - y0) * uy for px, py in pts]
        s0, s1 = max(0.0, min(sv)), min(L, max(sv))
        if s1 - s0 < 0.8:
            continue
        zc = S.z_at(u["cx"], u["cy"])
        zv = z_np(S, [p[0] for p in pts], [p[1] for p in pts])
        zb = float(min(zv.min(), zc))
        uf_ = unit_flags(u)
        bld.append(dict(s0=s0, s1=s1, zb=zb, base=zc, zt=zc + u["h"], d=min(dv), cat=u.get("cat", "residential"),
                        fabric=u.get("fabric", "regular"), floors=int(u.get("floors") or 1), annex=bool(u.get("annex")),
                        fsrc=u.get("floors_src", ""), mosque=uf_[0], ruin=uf_[2],
                        minaret=minaret_s(u, x0, y0, ux, uy, s0, s1) if u.get("fabric") == "sacred" else None))
    # ---- crowns: cut by the plane and beyond it (canopy height map)
    trees = []
    g = sa_crowns(S)
    tb = (band[0] - 10, band[1] - 10, band[2] + 10, band[3] + 10)
    for (tx, ty, tr, th, kind) in g.query(tb):
        d = (tx - x0) * nx + (ty - y0) * ny
        s = (tx - x0) * ux + (ty - y0) * uy
        if not (-tr < s < L + tr) or d < -0.5 * tr or d > SA_DEPTH_T:
            continue
        zg = S.z_at(tx, ty)
        trees.append(dict(s=s, zg=zg, lo=max(1.5, 0.35 * th), hi=th, r=tr, d=max(0.0, d), kind=kind,
                          seed=int(abs(tx * 7.31 + ty * 3.17) * 10) % 2147483647))
    # ---- bridges beyond (surveyed decks, at the level of the ground at their middle)
    bridges = []
    for P in getattr(S, "bridges", []) or []:
        if len(P) < 2:
            continue
        mx, my = sum(p[0] for p in P) / len(P), sum(p[1] for p in P) / len(P)
        d = (mx - x0) * nx + (my - y0) * ny
        if not 1.0 < d < SA_DEPTH_B:
            continue
        sv = [(px - x0) * ux + (py - y0) * uy for (px, py) in P]
        s0, s1 = max(0.0, min(sv)), min(L, max(sv))
        if s1 - s0 > 2.0:
            bridges.append(dict(s0=s0, s1=s1, z=S.z_at(mx, my), d=d))
    # ---- where scale figures may stand: walkable ground of the cut (streets, open ground, parks, parking)
    walk = []
    cur = None
    step = 1.0
    for k in range(int(L / step) + 1):
        s = k * step
        kd = classify_point(S, x0 + ux * s, y0 + uy * s)[0]
        ok = kd in ("road", "void", "green", "parking")
        if ok and cur is None:
            cur = [s, s, kd]
        elif ok:
            cur[1] = s
        elif cur is not None:
            walk.append(tuple(cur))
            cur = None
    if cur is not None:
        walk.append(tuple(cur))
    sc = dict(a=tuple(a), b=tuple(b), L=L, ux=ux, uy=uy, nx=nx, ny=ny, bands=bands, bld=bld, trees=trees,
              bridges=bridges, walk=walk)
    memo[mk] = sc
    return sc


def sa_people(sc, ground_at, seed):
    """Scale figures on the walkable ground of the cut: a few groups, never on slopes steeper than 1:4."""
    rnd = random.Random(seed)
    out = []
    for s0, s1, kd in sc["walk"]:
        if s1 - s0 < 3.0:
            continue
        s = s0 + rnd.uniform(1.0, min(14.0, s1 - s0))
        while s < s1 - 1.0:
            g0, g1 = ground_at(s - 1.0), ground_at(s + 1.0)
            if abs(g1 - g0) / 2.0 < 0.25:
                n = rnd.choice((1, 1, 2, 2, 3))
                x = s
                for q in range(n):
                    if x > s1 - 0.5:
                        break
                    child = rnd.random() < 0.1
                    out.append((x, rnd.randint(0, 3), (0.62 if child else rnd.uniform(0.95, 1.06)), rnd.random() < 0.5))
                    x += rnd.uniform(0.55, 1.1)
            s += rnd.uniform(26.0, 64.0)
    return out


# ============================================================ SECTION ART: the picture behind the cut
SA_STYLE_TECH = dict(bg=(255, 255, 255), ground=(232, 230, 226), ground_edge=(196, 192, 186), bld=(246, 246, 246),
                     bld_edge=(150, 150, 154), storey=(206, 206, 210), fade_to=(255, 255, 255), tree_alpha=0.78,
                     tree_wash=0.28, people=(118, 118, 124), bridge=(170, 170, 176), tint=None)


def sa_fade(d, dmax, lo=0.08, hi=0.8):
    return min(hi, lo + (hi - lo) * (max(0.0, d) / dmax) ** 0.8)


def sa_leaf(season):
    """Share of the season's days a deciduous crown is in leaf (leaf-out and leaf-fall measured over the site)."""
    if season in (None, "", "summer", "year", "lden", "board"):
        return 1.0 if season != "year" else float(np.mean(leaf_on_doy(np.arange(1, 366))))
    months = {"spring": (3, 4, 5), "autumn": (9, 10, 11), "winter": (12, 1, 2)}.get(season)
    if months is None:
        return 1.0
    md = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
    doys = []
    for m in months:
        start = sum(md[:m - 1])
        doys += list(range(start + 1, start + md[m - 1] + 1))
    return float(np.mean(leaf_on_doy(np.array(doys))))


def sa_leaf_day(month, day):
    md = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
    return 1.0 if bool(leaf_on_doy(np.array([sum(md[:month - 1]) + day]))[0]) else 0.0


# ============================================================ v16.4 · BUILDING TYPES IN SECTION
# Every building a section cuts or sees is drawn with the silhouette of its type, so its fabric type and its use read in
# the section as on the plan. v16.4 draws each type in its own material tone (v16.3 tinted every cut building by its use,
# so the old town and the planned low-rise houses, both mostly homes with pitched tile roofs, came out alike) and gives
# each type the features that tell it apart:
#   old town house (Ottoman type, as Bergama's Kale and Kurtulus quarters): a stone ground floor, a timber-framed upper
#     floor jutting out over it on brackets (cikma), close-set tall windows, a deep-eaved hipped roof of Turkish tile;
#   planned low-rise house (reinforced concrete frame): concrete floor bands, wide windows, a cantilevered balcony with a
#     rail, a low-pitched tile roof with short eaves, rendered walls;
#   apartment block: flat roof and parapet, balconies on every floor, window bands;
#   small irregular house / shack: low, a lean-to corrugated sheet roof, small windows;
#   civic and school hall: flat roof and cornice, tall window grid; industrial hall: sawtooth roof, high band windows;
#   mosque: a masonry hall with arched windows under a lead-grey dome on a drum; a minaret (shaft, balcony (serefe),
#     conical cap) where the survey's minaret symbol marks the mosque (at the symbol's place) or the name says cami;
#   monument: masonry in stone and brick bands, round-arched openings, a cornice; a ruin with a broken top;
#   under construction: a frame in scaffolding.
# Shops (commerce and mixed use) show a glazed shopfront and an awning on the ground floor; the use stays in the
# colour ribbon under each land-use section and in the tag of each cut building.
# WHAT IS MEASURED AND WHAT IS NOT: the footprint, the use, the fabric type, the floor count and the minaret symbol's
# place come from the survey and the data as before, and the eaves (the top of the walls) stay at floors x storey
# height. The roof forms, jetties, windows, balconies, shopfronts, domes and minaret heights are GENERIC drawings of the
# type (typical Turkish small-town building types, drawn to the proportions below), not surveyed: the legend of every
# section says so. The analyses keep using the measured prisms.
bergama_data("TYPO")
TYPO_ORDER = ["traditional", "regular", "block", "selfbuilt", "large", "industrial", "sacred", "monument", "construction"]
TYPO_SHOP = ("commercial", "mixed")
TYPO_ROOF_C = C("A86A55")           # tile roofs (mixed toward the page in the drawings)
TYPO_FLAT_C = C("8E8A82")           # flat roofs, parapets, corrugated sheet
TYPO_TIMBER_C = C("6E4F3A")         # the old town's timber frame and brackets
TYPO_STONE_C = C("A99A86")          # stone courses
MINARET_K = 2.6                     # generic minaret: 2.6 x the hall's wall height ...
MINARET_H = (14.0, 32.0)            # ... kept within 14-32 m above its ground (not surveyed)
MINARET_W = 2.2                     # m: shaft width


def typo_kind(fabric, cat):
    """The silhouette a building takes: its fabric type, industry split from the civic halls."""
    if fabric == "large" and cat == "industrial":
        return "industrial"
    return fabric if fabric in TYPO else "regular"


def typo_tone(fabric, cat):
    """The wall material's colour of a building's type in the sections (v16.4)."""
    return TYPO[typo_kind(fabric, cat)]["tone"]


def minaret_h(wall_h):
    """Generic minaret height above its ground for a mosque hall whose walls are wall_h high (not surveyed)."""
    return max(MINARET_H[0], min(MINARET_H[1], MINARET_K * max(1.0, wall_h)))


def typo_rise(fabric, cat, w, wall_h=None, minaret=False):
    """How far the generic roof of a building of width w (m, along the cut) rises above its eaves; with a minaret (a
    mosque whose walls are wall_h high) how far the minaret's cap does."""
    t = TYPO[typo_kind(fabric, cat)]
    r = 0.0
    if t["roof"] in ("hip", "gable"):
        r = min(t["rise"], math.tan(math.radians(t["pitch"])) * (w / 2.0 + t["eaves"]))
    elif t["roof"] == "shed":
        r = min(t["rise"], math.tan(math.radians(t["pitch"])) * (w + 2.0 * t["eaves"]))
    elif t["roof"] == "saw":
        r = t["rise"] if w >= 8.0 else 0.0
    elif t["roof"] == "dome":
        r = min(0.42 * w, 9.0) * 1.15 + 1.5
    if minaret and wall_h is not None:
        r = max(r, minaret_h(wall_h) - wall_h + 3.5)
    return r


def has_minaret(u):
    """(True, (x, y) or None) when a mosque has a minaret: the survey's minaret symbol marks it (at its place), or its
    name says cami (a congregational mosque; a mescit may have none and is drawn without)."""
    if u.get("minaret"):
        return True, u.get("minaret_xy")
    nm = " " + (u.get("name") or "").lower() + " "
    if "cami" in nm and u.get("fabric") == "sacred":
        return True, None
    return False, None


def minaret_s(u, x0, y0, ux, uy, s0, s1):
    """Where along a section a mosque's minaret stands: the minaret symbol's place projected on the line (kept on the
    building), else the end of the building nearer the line's end (generic); None without a minaret."""
    ok, xy = has_minaret(u)
    if not ok:
        return None
    if xy is not None:
        s = (xy[0] - x0) * ux + (xy[1] - y0) * uy
        return max(s0 + 0.5 * MINARET_W, min(s1 - 0.5 * MINARET_W, s))
    return s1 - 0.5 * MINARET_W - 0.4


def _arch(sa, za, sb, zt, n=8):
    """A round-headed opening from sa to sb, sill za, crown zt: its outline."""
    r = 0.5 * (sb - sa)
    zs = zt - r
    pts = [(sa, za), (sb, za), (sb, zs)]
    for q in range(1, n):
        an = math.pi * q / n
        pts.append(((sa + sb) / 2.0 + r * math.cos(an), zs + r * math.sin(an)))
    pts.append((sa, zs))
    return pts


def bld_profile(fabric, cat, s0, s1, zb, base, top, floors, published=False, seed=0, ruin=False, minaret=None):
    """The generic drawing of one building between s0 and s1 (m along the section), from its lowest ground zb, its own
    ground base, to its eaves top (m): dict(body=[(s, z)...] outline (with the old town's jetty), roof=[(s, z)...] or
    None, roof_c, tone, slabs=[z], wins=[(sa, za, sb, zb)] window and door openings in elevation, arches=[outline],
    shop=(sa, za, sb, zb) or None, awning=[[(s, z)..]], lines=[[(s, z)..]] (eaves, coping, corrugation, coursing,
    scaffold), timber=[[(s, z)..]] (old town frame and brackets), bands=[[(s, z)..]] (concrete floor bands, filled),
    balconies=[(s_from, s_to, z)], minaret=dict or None, kind, x0/x1 (outer extent))."""
    kind = typo_kind(fabric, cat)
    t = TYPO[kind]
    w = s1 - s0
    floors = max(1, int(floors or 1))
    st = (top - base) / float(floors) if top > base else 3.0
    out = dict(kind=kind, body=[(s0, zb), (s1, zb), (s1, top), (s0, top)], roof=None, slabs=[], wins=[], arches=[],
               shop=None, awning=[], lines=[], timber=[], bands=[], balconies=[], minaret=None, tone=t["tone"],
               roof_c=t["roof_c"], x0=s0, x1=s1)
    if not published:
        out["slabs"] = [base + f * st for f in range(1, floors) if base + f * st > zb + 0.3]
    # ---- the old town's jetty: the upper floors stand out over the stone ground floor on brackets (generic)
    jet = 0.0
    if kind == "traditional" and floors >= 2 and w >= 4.0 and not published:
        jet = min(t["jetty"], 0.12 * w)
        z1 = base + st
        out["body"] = [(s0, zb), (s1, zb), (s1, z1), (s1 + jet, z1 + 0.15), (s1 + jet, top), (s0 - jet, top),
                       (s0 - jet, z1 + 0.15), (s0, z1)]
        for sx, sg in ((s0, -1.0), (s1, 1.0)):                     # brackets under the jetty
            out["timber"].append([(sx, z1 - 0.55), (sx + sg * jet, z1 + 0.15)])
        out["x0"], out["x1"] = s0 - jet, s1 + jet
    s0r, s1r = s0 - jet, s1 + jet                                   # the walls the roof sits on
    wr = s1r - s0r
    rise = typo_rise(fabric, cat, wr)
    e = min(t["eaves"], 0.25 * w)
    if t["roof"] == "hip" or t["roof"] == "gable":
        sm = (s0r + s1r) / 2.0
        half = wr / 2.0 + e
        flat = max(0.0, half - rise / max(1e-6, math.tan(math.radians(t["pitch"]))))     # a long hip: a ridge
        out["roof"] = [(s0r - e, top), (s1r + e, top), (sm + flat, top + rise), (sm - flat, top + rise)]
        out["lines"].append([(s0r - e, top - 0.18), (s0r - e, top), (s1r + e, top), (s1r + e, top - 0.18)])   # fascia
        if kind == "traditional" and rise > 0.6:                    # Turkish tile courses on the hipped roof
            for q in range(1, 4):
                f_ = q / 4.0
                za_ = top + rise * f_
                ds = (half - flat) * f_
                out["lines"].append([(s0r - e + ds, za_), (s1r + e - ds, za_)])
        out["x0"], out["x1"] = min(out["x0"], s0r - e), max(out["x1"], s1r + e)
    elif t["roof"] == "shed":
        lo_ = top
        hi_ = top + rise
        if seed % 2:                                      # which way the lean-to falls: alternates, not surveyed
            a_, b_ = (s0 - e, hi_), (s1 + e, lo_)
        else:
            a_, b_ = (s0 - e, lo_), (s1 + e, hi_)
        za0 = a_[1] + (b_[1] - a_[1]) * e / (w + 2.0 * e)
        zb0 = a_[1] + (b_[1] - a_[1]) * (w + e) / (w + 2.0 * e)
        out["roof"] = [(s0, top), (s1, top), (s1, zb0), b_, a_, (s0, za0)]       # the wall's wedge under the sheet
        n_ = max(2, int(w / 0.35))
        zz = []                                           # corrugation of the sheet, drawn as a fine zigzag on top
        for q in range(n_ + 1):
            f_ = q / float(n_)
            zz.append((a_[0] + (b_[0] - a_[0]) * f_, a_[1] + (b_[1] - a_[1]) * f_ + (0.06 if q % 2 else 0.0)))
        out["lines"].append(zz)
    elif t["roof"] == "saw" and rise > 0.0:
        n_ = max(1, int(round(w / 6.0)))
        tw_ = w / n_
        R = [(s0, top)]
        for q in range(n_):
            a_ = s0 + q * tw_
            R += [(a_, top + rise), (a_ + tw_, top)]
        out["roof"] = R + [(s1, top)]
    elif t["roof"] == "dome":
        r_ = min(0.42 * w, 9.0)
        sm = (s0 + s1) / 2.0
        dr = 0.15 * r_                                     # the drum under the dome
        dome = [(sm + r_ * math.cos(math.pi * q / 24.0), top + dr + r_ * math.sin(math.pi * q / 24.0)) for q in range(25)]
        out["roof"] = [(sm + r_, top), (sm + r_, top + dr)] + dome[1:-1] + [(sm - r_, top + dr), (sm - r_, top)]
        out["lines"].append([(sm - r_ - 0.2, top + dr), (sm + r_ + 0.2, top + dr)])       # the drum's cornice
        if r_ > 2.0:                                      # the finial (alem)
            out["lines"].append([(sm, top + dr + r_), (sm, top + dr + r_ + min(1.5, 0.25 * r_))])
        if r_ > 3.0:                                      # windows round the drum
            for q in (-2, -1, 0, 1, 2):
                c_ = sm + q * 0.36 * r_
                out["wins"].append((c_ - 0.25, top + 0.25 * dr, c_ + 0.25, top + 0.8 * dr))
    if t.get("parapet"):
        p_ = min(t["parapet"], 0.4 * st)
        out["lines"].append([(s0 - 0.1, top - p_), (s1 + 0.1, top - p_)])                      # parapet coping band
        out["lines"].append([(s0 - 0.1, top), (s1 + 0.1, top)])
    if kind == "monument":                                # stone and brick bands, a cornice; a ruin's broken top
        hh = top - zb
        q = 1
        while q * 1.2 < hh - 0.3:
            zq = zb + q * 1.2
            out["lines"].append([(s0, zq), (s1, zq)])
            out["lines"].append([(s0, zq + 0.18), (s1, zq + 0.18)])
            q += 1
        if ruin:
            rnd = random.Random(seed)
            n_ = max(3, int(w / 1.5))
            brk = [(s1, top)]
            for k in range(1, n_):
                brk.append((s1 - w * k / n_, top - rnd.uniform(0.3, min(3.0, 0.35 * hh))))
            brk.append((s0, top - rnd.uniform(0.0, 0.25 * hh)))
            out["body"] = [(s0, zb), (s1, zb)] + brk
        else:
            out["lines"].append([(s0 - 0.25, top - 0.35), (s1 + 0.25, top - 0.35), (s1 + 0.25, top), (s0 - 0.25, top)])
        if hh >= 6.0 and w >= 4.0:                        # round-arched openings
            n_ = max(1, int(w / 4.5))
            pw = w / n_
            ah = min(0.55 * hh, 6.0)
            for k in range(n_):
                c_ = s0 + pw * (k + 0.5)
                aw = min(2.4, 0.5 * pw)
                out["arches"].append(_arch(c_ - aw / 2.0, base + 0.8, c_ + aw / 2.0, base + 0.8 + ah))
    if kind == "construction":                            # scaffold: posts and diagonals
        n_ = max(1, int(w / 3.0))
        for q in range(n_):
            a_, b_ = s0 + w * q / n_, s0 + w * (q + 1) / n_
            out["lines"].append([(a_, zb), (b_, top)])
            out["lines"].append([(a_, top), (b_, zb)])
    if t.get("base") and kind == "traditional":           # the stone ground floor: courses
        zt_ = base + (st if (floors >= 2 and not published) else t["base"])
        q = 1
        while zb + q * 0.5 < zt_ - 0.15:
            out["lines"].append([(s0, zb + q * 0.5), (s1, zb + q * 0.5)])
            q += 1
    if kind == "regular" and not published:               # concrete floor bands (beam and slab edge)
        for f in range(1, floors + 1):
            zf = base + f * st
            if zf > zb + 0.3:
                out["bands"].append([(s0 - 0.05, zf - t["band"]), (s1 + 0.05, zf - t["band"]), (s1 + 0.05, zf),
                                     (s0 - 0.05, zf)])
        if floors >= 2 and w >= 5.0:                      # one cantilevered balcony per upper floor, on one side
            side = s1 if seed % 2 == 0 else s0
            sg = 1.0 if seed % 2 == 0 else -1.0
            for f in range(1, floors):
                out["balconies"].append((side, side + sg * t["balcony"], base + f * st))
    if kind == "block" and floors >= 2 and w >= 6.0:
        for f in range(1, floors):
            zf = base + f * st
            bw = t["balcony"]
            out["balconies"].append((s0, s0 - bw, zf))
            out["balconies"].append((s1, s1 + bw, zf))
    # windows (elevation): per floor, evenly spaced; the ground floor of a shop is a glazed front with an awning
    if t["win"] and w >= 2.0:
        ww, wh, sill, sp = t["win"]
        shop = cat in TYPO_SHOP and kind not in ("monument", "sacred", "construction")
        for f in range(floors if not published else 1):
            zf = base + f * st
            if zf + sill + wh > top - 0.2:
                continue
            if f == 0 and shop and w >= 3.0:
                za, zt_ = base + 0.15, base + min(2.8, st - 0.3)
                out["shop"] = (s0 + 0.35, za, s1 - 0.35, zt_)
                aw = min(1.4, 0.3 * w)
                out["awning"] = [[(s0, zt_ + 0.15), (s0 - aw, zt_ - 0.35)], [(s1, zt_ + 0.15), (s1 + aw, zt_ - 0.35)]]
                continue
            ext = jet if f >= 1 else 0.0                  # the jettied floors are wider
            a0_, a1_ = s0 - ext, s1 + ext
            n_ = max(1, int((a1_ - a0_ - 0.8) / sp))
            pitch_ = (a1_ - a0_) / n_
            for q in range(n_):
                c_ = a0_ + pitch_ * (q + 0.5)
                if f == 0 and q == n_ // 2 and kind in ("traditional", "regular", "selfbuilt") and w >= 4.0:
                    out["wins"].append((c_ - 0.5, zf + 0.05, c_ + 0.5, zf + min(2.1, st - 0.4)))     # the door
                    continue
                if kind == "sacred":
                    out["arches"].append(_arch(c_ - ww / 2.0, zf + sill, c_ + ww / 2.0, zf + sill + wh))
                    continue
                out["wins"].append((c_ - ww / 2.0, zf + sill, c_ + ww / 2.0, zf + sill + wh))
            if kind == "traditional" and f >= 1:          # the timber frame of the upper floor: posts and braces
                n2 = max(2, int((a1_ - a0_) / 1.25))
                for q in range(n2 + 1):
                    sx = a0_ + (a1_ - a0_) * q / n2
                    out["timber"].append([(sx, zf + 0.15), (sx, min(top, zf + st))])
                for q in range(0, n2, 2):
                    sa_, sb_ = a0_ + (a1_ - a0_) * q / n2, a0_ + (a1_ - a0_) * (q + 1) / n2
                    out["timber"].append([(sa_, zf + 0.15), (sb_, min(top, zf + st) - 0.1)])
    # ---- the minaret: shaft, balcony and conical cap at its place along the section (generic height)
    if minaret is not None and kind == "sacred":
        H = minaret_h(top - base)
        sm = minaret
        hw = 0.5 * MINARET_W
        zs = base + 0.82 * H                              # the balcony (serefe)
        ztop = base + H
        out["minaret"] = dict(shaft=[(sm - hw, zb), (sm + hw, zb), (sm + hw * 0.85, ztop), (sm - hw * 0.85, ztop)],
                              balcony=[(sm - hw - 0.6, zs), (sm + hw + 0.6, zs), (sm + hw + 0.6, zs + 0.9),
                                       (sm - hw - 0.6, zs + 0.9)],
                              cap=[(sm - hw * 0.95, ztop), (sm + hw * 0.95, ztop), (sm, ztop + 3.5)],
                              alem=[(sm, ztop + 3.5), (sm, ztop + 4.3)], s=sm, top=ztop + 4.3)
        out["x0"], out["x1"] = min(out["x0"], sm - hw - 0.6), max(out["x1"], sm + hw + 0.6)
    return out


def bld_draw_cut(B, L, P, prof, fill, wall_c, ss, U, order=27, roof_c=None, pale=False, label=None, placed=None):
    """A cut building in vectors (v16.4): its interior in the tone of its type, the back wall seen through the cut with
    its windows, doors and arches, the generic roof of its type, the cut walls (heavier), a line at every floor slab,
    the old town's jetty and timber frame, the planned house's concrete floor bands and balcony, the shopfront and
    awning, the mosque's dome and minaret. P maps (s, z) to the page; ss = page units per metre (detail drops out when
    it would be too small to see). placed: the labels already on this section [(x0, x1, y)]; a label that would
    overlap one of them is left out."""
    body = [P(s, z) for s, z in prof["body"]]
    B.fill([body], fill, L, order)
    kind = prof["kind"]
    rc = roof_c
    if rc is None:
        rc = mix(prof["roof_c"], PAPER, 0.25)
    if prof["roof"]:
        R = [P(s, z) for s, z in prof["roof"]]
        if TYPO[kind]["roof"] == "shed":
            B.fill([R], fill, L, order)
        else:
            B.fill([R], rc, L, order)
        B.line(R + [R[0]], wall_c, L, order + 2, 0.1)
    small = ss * 1.0 <= 0.12 * U
    back = mix(fill, (255, 255, 255), 0.55)              # the far wall's openings, seen through the cut
    if not small:
        for a_, za, b_, zt_ in prof["wins"]:
            B.fill([[P(a_, za), P(b_, za), P(b_, zt_), P(a_, zt_)]], back, L, order + 1)
        for A_ in prof["arches"]:
            B.fill([[P(s, z) for s, z in A_]], back, L, order + 1)
    if prof["shop"] is not None and (prof["shop"][2] - prof["shop"][0]) * ss > 0.2 * U:
        a_, za, b_, zt_ = prof["shop"]
        B.fill([[P(a_, za), P(b_, za), P(b_, zt_), P(a_, zt_)]], mix(CAT["commercial"][1], (255, 255, 255), 0.35), L, order + 1)
    for Bd in prof["bands"]:
        B.fill([[P(s, z) for s, z in Bd]], mix(wall_c, fill, 0.55), L, order + 2)
    for z in prof["slabs"]:
        B.line([P(prof["body"][0][0], z), P(prof["body"][1][0], z)], wall_c, L, order + 2, 0.05)
    B.line(body + [body[0]], wall_c, L, order + 2, 0.18)            # the cut walls
    if not small:                                                    # window openings in the cut end walls
        s0, s1 = prof["body"][0][0], prof["body"][1][0]
        zs_ = sorted(set((round(za, 2), round(zt_, 2)) for (a_, za, b_, zt_) in prof["wins"]))
        for za, zt_ in zs_:
            for sx in (s0, s1):
                B.line([P(sx, za), P(sx, zt_)], (255, 255, 255), L, order + 3, 0.1)
    for ln in prof["lines"]:
        B.line([P(s, z) for s, z in ln], wall_c, L, order + 3, 0.05)
    if not small:
        for ln in prof["timber"]:
            B.line([P(s, z) for s, z in ln], mix(TYPO_TIMBER_C, fill, 0.15), L, order + 3, 0.06)
    for ln in prof["awning"]:
        B.line([P(s, z) for s, z in ln], mix(CAT["commercial"][1], INK, 0.3), L, order + 3, 0.12)
    for sa_, sb_, z in prof["balconies"]:                            # slab and rail
        B.line([P(sa_, z), P(sb_, z)], wall_c, L, order + 3, 0.12)
        B.line([P(sb_, z), P(sb_, z + 1.0), P(sa_, z + 1.0)], wall_c, L, order + 3, 0.04)
    mn = prof.get("minaret")
    if mn:
        for key in ("shaft", "balcony"):
            Q = [P(s, z) for s, z in mn[key]]
            B.fill([Q], fill, L, order + 1)
            B.line(Q + [Q[0]], wall_c, L, order + 2, 0.12)
        Q = [P(s, z) for s, z in mn["cap"]]
        B.fill([Q], rc, L, order + 1)
        B.line(Q + [Q[0]], wall_c, L, order + 2, 0.1)
        B.line([P(s, z) for s, z in mn["alem"]], wall_c, L, order + 2, 0.06)
    if label:
        top_ = max(z for s, z in (prof["roof"] or prof["body"]))
        sm = (prof["body"][0][0] + prof["body"][1][0]) / 2.0
        q = P(sm, top_)
        hw_ = 0.5 * tw(label, 0.17 * U) + 0.15 * U
        if placed is None or not any(x0_ < q[0] + hw_ and q[0] - hw_ < x1_ and abs(y_ - q[1]) < 0.3 * U
                                     for x0_, x1_, y_ in placed):
            B.text(label, q[0], q[1] + 0.12 * U, 0.17 * U, wall_c, L, order=order + 4, align="C")
            if placed is not None:
                placed.append((q[0] - hw_, q[0] + hw_, q[1]))


def bld_raster(art, prof, xp, yp, col, ecol, wcol, rcol, res, tcol=None):
    """A building beyond the cut in the picture (elevation): wall face in its type's tone, generic roof of its type,
    window openings and arches, the old town's timber frame, the planned house's floor bands and balconies, shopfront
    and awning, the mosque's minaret; detail below a pixel is left out."""
    body = [(xp(s), yp(z)) for s, z in prof["body"]]
    sa_fill(art, [body], col)
    if prof["roof"]:
        sa_fill(art, [[(xp(s), yp(z)) for s, z in prof["roof"]]], rcol)
        R = [(xp(s), yp(z)) for s, z in prof["roof"]]
        sa_stroke(art, R + [R[0]], 0.8, ecol, 0.9)
    if prof["shop"] is not None:
        a_, za, b_, zt_ = prof["shop"]
        sa_fill(art, [[(xp(a_), yp(za)), (xp(b_), yp(za)), (xp(b_), yp(zt_)), (xp(a_), yp(zt_))]], wcol, 0.9)
    for Bd in prof["bands"]:
        sa_fill(art, [[(xp(s), yp(z)) for s, z in Bd]], sa_mix(ecol, col, 0.55), 0.9)
    if 0.7 / res >= 1.2:                                   # windows only where they are at least ~1 px wide
        for a_, za, b_, zt_ in prof["wins"]:
            sa_fill(art, [[(xp(a_), yp(za)), (xp(b_), yp(za)), (xp(b_), yp(zt_)), (xp(a_), yp(zt_))]], wcol, 0.85)
        for A_ in prof["arches"]:
            sa_fill(art, [[(xp(s), yp(z)) for s, z in A_]], wcol, 0.85)
        for ln in prof["timber"]:
            sa_stroke(art, [(xp(s), yp(z)) for s, z in ln], 0.8, tcol or ecol, 0.75)
    for ln in prof["lines"]:
        sa_stroke(art, [(xp(s), yp(z)) for s, z in ln], 0.7, ecol, 0.8)
    for ln in prof["awning"]:
        sa_stroke(art, [(xp(s), yp(z)) for s, z in ln], 1.2, ecol, 0.9)
    for sa_, sb_, z in prof["balconies"]:
        sa_stroke(art, [(xp(sa_), yp(z)), (xp(sb_), yp(z))], 1.1, ecol, 0.85)
        sa_stroke(art, [(xp(sb_), yp(z)), (xp(sb_), yp(z + 1.0)), (xp(sa_), yp(z + 1.0))], 0.7, ecol, 0.7)
    sa_stroke(art, body + [body[0]], 1.0, ecol, 0.95)
    mn = prof.get("minaret")
    if mn:
        for key in ("shaft", "balcony"):
            Q = [(xp(s), yp(z)) for s, z in mn[key]]
            sa_fill(art, [Q], col)
            sa_stroke(art, Q + [Q[0]], 0.9, ecol, 0.9)
        Q = [(xp(s), yp(z)) for s, z in mn["cap"]]
        sa_fill(art, [Q], rcol)
        sa_stroke(art, Q + [Q[0]], 0.8, ecol, 0.9)
        sa_stroke(art, [(xp(s), yp(z)) for s, z in mn["alem"]], 0.8, ecol, 0.9)


def typo_label(fabric, cat, floors, mosque=False, name=""):
    """The short tag of a cut building: its fabric type (a mosque by name where the survey says so), a shop where it
    has one, its floors. v16.7: a building with its own name (label_name) is tagged with that name alone."""
    if name:
        return name
    k = typo_kind(fabric, cat)
    nm = {"traditional": "old town", "regular": "planned low-rise", "block": "apartment block", "selfbuilt": "small irregular",
          "large": "civic hall", "industrial": "industry", "sacred": "mosque" if mosque else "sacred",
          "monument": "monument", "construction": "in construction"}[k]
    if cat == "commercial" and k not in ("monument", "sacred"):
        nm += " · shop"
    elif cat == "mixed" and k not in ("monument", "sacred"):
        nm += " · shop + home"
    return "{} · {} fl".format(nm, int(floors or 1)) if k not in ("monument",) else nm


def sa_render(S, sc, s0, s1, zlo, zhi, res, style, leaf=1.0, season="", ground=None, people=True, bld_col=None,
              max_px=6000):
    """The soft picture of a section between s0 and s1 (m along the line) and zlo..zhi (m a.s.l.): the ground beyond in
    bands, buildings beyond (faded with distance), crowns at their measured size and leaf state, bridges, scale
    figures on the cut. ground: the cut's ground [(s, z)] (figures stand on it). Returns (SArt, res)."""
    W = int(math.ceil((s1 - s0) / res))
    if W > max_px:
        res = (s1 - s0) / max_px
        W = max_px
    H = max(2, int(math.ceil((zhi - zlo) / res)))
    bg = _sa_c(style["bg"])
    art = SArt(W, H, bg)
    fade_to = _sa_c(style["fade_to"])

    def xp(s):
        return (s - s0) / res

    def yp(z):
        return (zhi - z) / res
    items = []
    for d, ss_, zs in sc["bands"]:
        items.append((d, 0, ("band", ss_, zs)))
    for bo in sc["bld"]:
        if bo["s1"] < s0 or bo["s0"] > s1:
            continue
        items.append((bo["d"], 1, ("bld", bo)))
    for t in sc["trees"]:
        if t["s"] + t["r"] < s0 or t["s"] - t["r"] > s1:
            continue
        items.append((t["d"], 2, ("tree", t)))
    for br in sc["bridges"]:
        items.append((br["d"], 1, ("bridge", br)))
    items.sort(key=lambda it: (-it[0], it[1]))
    gcol, gedge = _sa_c(style["ground"]), _sa_c(style["ground_edge"])
    for d, _, it in items:
        kind = it[0]
        if kind == "band":
            _, ss_, zs = it
            f = sa_fade(d, SA_BANDS[-1], 0.35, 0.86)
            col = sa_mix(gcol, fade_to, f)
            ecol = sa_mix(gedge, fade_to, f)
            # one polygon per run of known heights
            ok = np.isfinite(zs)
            k = 0
            n = len(ss_)
            while k < n:
                if not ok[k]:
                    k += 1
                    continue
                k0 = k
                while k < n and ok[k]:
                    k += 1
                if k - k0 < 2:
                    continue
                top = [(xp(ss_[q]), yp(zs[q])) for q in range(k0, k)]
                sa_fill(art, [top + [(top[-1][0], H + 2), (top[0][0], H + 2)]], col)
                sa_stroke(art, top, 1.0, ecol, 0.8)
        elif kind == "bld":
            bo = it[1]
            f = sa_fade(d, SA_DEPTH_B, 0.12, 0.82)
            base = _sa_c(bld_col(bo) if bld_col else mix(typo_tone(bo.get("fabric", "regular"), bo.get("cat", "residential")),
                                                         (255, 255, 255), style.get("tone_mix", 0.5)))
            col = sa_mix(base, fade_to, f)
            ecol = sa_mix(_sa_c(style["bld_edge"]), fade_to, f)
            scol = sa_mix(_sa_c(style["storey"]), fade_to, f)
            # v16.3: the building's type as a silhouette (generic roof, windows, shopfront), not a plain box
            prof = bld_profile(bo.get("fabric", "regular"), bo.get("cat", "residential"), bo["s0"], bo["s1"], bo["zb"],
                               bo["base"], bo["zt"], bo["floors"], bo["fsrc"] == "published",
                               seed=int(abs(bo["s0"] * 7.0 + bo["d"] * 3.0)), ruin=bo.get("ruin", False),
                               minaret=bo.get("minaret"))
            wcol = sa_mix(ecol, col, 0.45)
            rbase = _sa_c(mix(prof["roof_c"], (255, 255, 255), style.get("roof_mix", 0.45)))
            rcol = col if TYPO[prof["kind"]]["roof"] == "shed" else sa_mix(rbase, fade_to, f)
            tcol = sa_mix(_sa_c(mix(TYPO_TIMBER_C, (255, 255, 255), 0.3)), fade_to, f)
            bld_raster(art, prof, xp, yp, col, ecol, wcol, rcol, res, tcol=tcol)
        elif kind == "bridge":
            br = it[1]
            f = sa_fade(d, SA_DEPTH_B, 0.15, 0.8)
            col = sa_mix(_sa_c(style["bridge"]), fade_to, f)
            xa, xb = xp(br["s0"]), xp(br["s1"])
            sa_fill(art, [[(xa, yp(br["z"] + 0.15)), (xb, yp(br["z"] + 0.15)), (xb, yp(br["z"] - 0.6)), (xa, yp(br["z"] - 0.6))]],
                 col)
            sa_stroke(art, [(xa, yp(br["z"] + 1.1)), (xb, yp(br["z"] + 1.1))], 0.8, col, 0.8)
        else:
            t = it[1]
            f = sa_fade(d, SA_DEPTH_T, style.get("tree_fade0", 0.06), 0.82)
            lf = leaf if t["kind"] == "tree" else 1.0
            sp = sa_tree(t["kind"], xp(t["s"]), yp(t["zg"]), yp(t["zg"] + t["lo"]), yp(t["zg"] + t["hi"]),
                             t["r"] / res, t["seed"], leaf=lf, season=season)
            if sp is not None:
                wash = style.get("tree_wash", 0.0)
                sp.onto(art, alpha=style["tree_alpha"] * (1.0 - 0.45 * f), toward=fade_to, fade=min(0.92, wash + f))
    if people and ground is not None:
        gs = [p[0] for p in ground]

        def g_at(s):
            k = max(0, min(len(ground) - 1, _bisect_right(gs, s) - 1))
            k1 = min(len(ground) - 1, k + 1)
            (sa_, za), (sb_, zb) = ground[k], ground[k1]
            return za if sb_ <= sa_ else za + (zb - za) * (s - sa_) / (sb_ - sa_)
        pcol = _sa_c(style["people"])
        for s, kind, scale, flip in sa_people(sc, g_at, int(abs(sc["a"][0] * 13 + sc["a"][1] * 7)) % 99991):
            if not (s0 <= s <= s1):
                continue
            P, (hx, hy, hr) = sa_figure(kind, s, g_at(s), scale, flip, 1.0 / res, xp, yp)
            sa_fill(art, [P], pcol, 0.82)
            sa_blob(art, hx, hy, max(0.5, hr), pcol, 0.82, soft=0.6)
    return art, res


# ============================================================ TECHNICAL SECTIONS · the seven analyses cut vertically
# Every technical analysis can also be cut along lines of its own (inputs sound_sections, heat_sections, shade_sections,
# solar_sections, wind_sections, air_sections, felt_sections). A section shows the analysis in the vertical plane of its
# line at true scale, from the ground and the stream bed up above the roofs, with the cut buildings (the same prisms the
# analyses use), the cut tree crowns, the terrain and the water; one sheet per line with four strips: the four seasons
# (sound: Lden and the day, evening and night levels), on the colour scales of the plan sheets. The plan models are
# evaluated at every height of the plane:
#   sound   NoiseModel (the plan's model, receivers every 1 m up each column)
#   heat    Landsat surface temperature along the ground and the roofs under the line
#   shade   hours out of the sun on the key day, 15-minute steps, exact 3D shadows of every building prism (absolute
#           heights), tree crown and the terrain horizon at every point of the plane
#   solar   kWh/m2 over the season on the ground (the plan's ground model), the cut roofs and the cut facades (the plan's
#           roof and facade model)
#   wind    the plan's wind at 1.5 m brought to every height with the log law, and the windbreak shelter of the
#           buildings and crowns upwind taken from their height above that point
#   air     dry bulb with the standard lapse rate at every height
#   felt    UTCI at every point of the plane: air, local wind, sun or shade and the sky that point sees
# Everything is kept between runs (selinus_cache): the line's geometry, every field, and the sky seen from the line
# (shared by the felt temperature and solar sections of the same line), the wind shelter (shared by wind and felt).
TSEC_DEF = [("sound_sections", "T1", "SOUND"), ("heat_sections", "T2", "SURFACE HEAT"), ("shade_sections", "T3", "SHADE"),
            ("solar_sections", "T4", "SOLAR RADIATION"), ("wind_sections", "T5", "WIND"),
            ("air_sections", "T6", "AIR TEMPERATURE"), ("felt_sections", "T7", "FELT TEMPERATURE")]
TSEC_DS = 0.5            # m between the columns of the sky, wind, air and felt fields (plus one outside every cut wall;
#                          v16.6: 1.0 -> 0.5)
TSEC_DZ = 0.5            # m between their heights
TSEC_DS_SHADE = 0.25     # v16.6: m between the columns of the shade field (v16.5: 1.0, as the other fields)
TSEC_DZ_SHADE = 0.25     # v16.6: m between its heights (v16.5: 0.5)
TSEC_DS_SOLAR = 0.25     # v16.6: m between the solar points on the ground and on the cut roofs (v16.5: ground every
#                          1.0 m plus one 0.25 m outside every cut wall, roofs every 1.5 m)
TSEC_DZ_SOLAR = 0.5      # v16.6: m: the cut facades in bands of at most this height (v16.5: 1.5)
TSEC_DS_SOUND = 2.5      # m between sound columns (plus one outside every cut wall)
TSEC_DZ_SOUND = 1.0      # m between the sound receivers of a column
TSEC_HEAD = 8.0          # m of air shown above the highest cut roof, crown or ground
TSEC_FETCH = 300.0       # m searched upwind for shelter, as on the plan
TSEC_LN10 = math.log(10.0 / 0.1)
TSEC_LN15 = math.log(1.5 / 0.1)


def tsec_lines(S):
    """The lines of every technical section input, trimmed to the frame (the analyses stop at it). Computed once per
    bake; skipped and trimmed lines are reported by their number in their input."""
    memo = env_memo(S)
    r = memo.get(("tsec_lines", repr(TSEC)))
    if r is not None:
        return r
    out = {}
    trimmed = []
    for key, num, title in TSEC_DEF:
        lst = []
        tr = []
        for k, (a, b) in enumerate(TSEC.get(key) or []):
            runs = S.F.clip_line([a, b])
            if not runs:
                LOG.append("{} line {} lies outside the frame and was skipped.".format(key, k + 1))
                continue
            p, q = tuple(runs[0][0]), tuple(runs[0][-1])
            if math.hypot(q[0] - p[0], q[1] - p[1]) < 10.0:
                LOG.append("{} line {} is shorter than 10 m inside the frame and was skipped.".format(key, k + 1))
                continue
            if math.hypot(p[0] - a[0], p[1] - a[1]) + math.hypot(q[0] - b[0], q[1] - b[1]) > 1.0:
                tr.append(str(k + 1))
            lst.append((k, p, q))                         # k: the line's place in its input (its number)
        if tr:
            trimmed.append("{} {}".format(key, ", ".join(tr)))
        out[key] = lst
    if trimmed:
        LOG.append("Technical section lines trimmed to the frame: " + "; ".join(trimmed) + ".")
    memo[("tsec_lines", repr(TSEC))] = out
    return out


def line_poly_cross(P, ox, oy, ux, uy):
    """Where the infinite line o + s u crosses polygon P: [(s, outward normal of the crossed edge)], sorted. Each
    vertex belongs to one side only, so the crossings pair up into the inside intervals."""
    out = []
    P = ccw(P)                                           # outward normals need a counter-clockwise ring
    n = len(P)
    for q in range(n):
        ax, ay = P[q]
        bx, by = P[(q + 1) % n]
        sa = ux * (ay - oy) - uy * (ax - ox)
        sb = ux * (by - oy) - uy * (bx - ox)
        if (sa > 0) != (sb > 0):
            ex, ey = bx - ax, by - ay
            le = math.hypot(ex, ey)
            out.append((((ax - ox) * ey - (ay - oy) * ex) / (ux * ey - uy * ex), (ey / le, -ex / le)))
    out.sort()
    return out


def tsec_geom_make(S, a, b):
    """Ground (stream bed carved as on the land-use sections), water, cut buildings and cut crowns along one line."""
    (x0, y0), (x1, y1) = a, b
    L = math.hypot(x1 - x0, y1 - y0)
    ux, uy = (x1 - x0) / L, (y1 - y0) / L
    step = 0.5
    smp = []
    for k in range(int(L / step) + 1):
        s = k * step
        px, py = x0 + ux * s, y0 + uy * s
        z_ = S.z_at(px, py)
        smp.append([s, classify_point(S, px, py)[0] == "water", z_, z_])
    if smp[-1][0] < L - 1e-6:
        z_ = S.z_at(x1, y1)
        smp.append([L, classify_point(S, x1, y1)[0] == "water", z_, z_])
    water = []
    k = 0
    while k < len(smp):
        if not smp[k][1]:
            k += 1
            continue
        k0 = k
        while k < len(smp) and smp[k][1]:
            k += 1
        za = smp[max(0, k0 - 2)][2]
        zb = smp[min(len(smp) - 1, k)][2]
        bank = min(za, zb)
        bed = min(r[2] for r in smp[k0:k])
        if bank - bed < 1.0:
            sm = (smp[k0][0] + smp[k - 1][0]) / 2.0
            dd_ = bed_depth(S, x0 + ux * sm, y0 + uy * sm)
            if dd_ is not None:
                bed = bank - dd_
        for r in smp[k0:k]:
            r[2] = bed
        sm_ = (smp[k0][0] + smp[k - 1][0]) / 2.0
        water.append((smp[k0][0], min(L, smp[k - 1][0] + step), bed, water_level(S, x0 + ux * sm_, y0 + uy * sm_, bed, bank)[0]))
    ground = [(r[0], r[2]) for r in smp]
    terrain = [(r[0], r[3]) for r in smp]                # before the stream bed was carved
    bl, gB, trees = S.env["solids"]
    bidx = S.env["bindex"]
    box = (min(x0, x1) - 1.0, min(y0, y1) - 1.0, max(x0, x1) + 1.0, max(y0, y1) + 1.0)
    cut = []
    for bo in gB.query(box):
        cr = line_poly_cross(bo["P"], x0, y0, ux, uy)
        u = bo.get("u") or {}
        for q in range(0, len(cr) - 1, 2):
            (s0, n0), (s1, n1) = cr[q], cr[q + 1]
            s0, s1 = max(0.0, s0), min(L, s1)
            if s1 - s0 > 0.02:
                cut.append((s0, s1, bo["base"], bo["top"], bidx[id(bo)], u.get("fabric", "regular"),
                            u.get("cat", "residential"), bool(u.get("annex")), n0, n1))
    cut.sort()
    crowns = []
    for ti, t in enumerate(trees):
        r = t["r"]
        if not (box[0] - r <= t["x"] <= box[2] + r and box[1] - r <= t["y"] <= box[3] + r):
            continue
        d = -(t["x"] - x0) * uy + (t["y"] - y0) * ux
        if abs(d) >= r:
            continue
        sc_ = (t["x"] - x0) * ux + (t["y"] - y0) * uy
        hw = math.sqrt(r * r - d * d)
        if sc_ + hw <= 0.0 or sc_ - hw >= L:
            continue
        crowns.append((sc_, hw, t["base"] + t["lo"], t["base"] + t["hi"], t["kind"], ti))
    zg = [z for s, z in ground]
    tops = [c[3] + typo_rise(c[5], c[6], c[1] - c[0], c[3] - c[2],
                             c[5] == "sacred" and has_minaret(bl[c[4]].get("u") or {})[0]) + 1.0 for c in cut] + \
        [c[3] for c in crowns]
    zlo = math.floor(min(zg)) - 1.0
    zhi = math.ceil(max([max(zg)] + tops)) + TSEC_HEAD
    return dict(a=tuple(a), b=tuple(b), L=L, ux=ux, uy=uy, ground=ground, terrain=terrain, water=water, cut=cut,
                crowns=crowns, zlo=zlo, zhi=zhi)


def tsec_geom(S, a, b):
    """The geometry of one line, kept between runs (the same line in several inputs is built once)."""
    memo = env_memo(S)
    mk = ("tsec_geom", a, b)
    G = memo.get(mk)
    if G is not None:
        return G
    pr = site_prints(S)
    C = getattr(S, "chan", None) or {}
    key = fp("sec_geom", MV["sec_geom"], S.env["keys"]["solids"], pr["terrain"], pr["water"], pr["bld"], CH_DEPTH,
             water_key(S), TSEC_HEAD, a, b, C.get("ch"), C.get("d"))
    ST = S.store
    G = ST.get("sec_geom", key)
    if G is None:
        G = ST.put("sec_geom", key, tsec_geom_make(S, a, b))
    G = dict(G, key=key)
    memo[mk] = G
    return G


def tsec_zg(G, s, key="ground"):
    """Ground (or stream bed) height at s, linear between the 0.5 m samples (key="terrain": before the carving)."""
    g = G[key]
    k = int(s / 0.5)
    if k <= 0:
        k = 0
    if k >= len(g) - 1:
        return g[-1][1]
    s0, z0 = g[k]
    s1, z1 = g[k + 1]
    return z0 + (z1 - z0) * ((s - s0) / (s1 - s0) if s1 > s0 else 0.0)


def tsec_cols(S, G, ds):
    """Columns of a field: every ds along the line and one 0.25 m (half a column if less) outside every cut wall.
    Each column: (s, x, y, ground, surface (ground or water level), roof of the cut building it stands in or None,
    roof of the cut building whose wall it faces or None, terrain before the stream bed was carved)."""
    memo = env_memo(S)
    mk = ("tsec_cols", G["key"], ds)
    r = memo.get(mk)
    if r is not None:
        return r
    L = G["L"]
    cut = G["cut"]

    def inside(s):
        for c in cut:
            if c[0] <= s <= c[1]:
                return c
        return None
    vals = [((i + 0.5) * ds, False) for i in range(int(L / ds))]
    walls = {}
    wo = min(0.25, 0.5 * ds)                              # v16.6: half a column at most (0.25 m as before for 0.5 m+)
    for c in cut:
        for s in (c[0] - wo, c[1] + wo):
            if 0.0 < s < L and inside(s) is None:
                vals.append((s, True))
                walls[s] = max(walls.get(s, -1e30), c[3])
    vals.sort()
    keep = []
    for s, isw in vals:                                   # columns closer than 5 cm: one kept, a wall's own first
        if keep and s - keep[-1][0] < 0.05:
            if isw and not keep[-1][1]:
                keep[-1] = (s, True)
            continue
        keep.append((s, isw))
    vals = [s for s, isw in keep]
    out = []
    for s in vals:
        zg = tsec_zg(G, s)
        zs = zg
        for w0, w1, bed, lvl in G["water"]:
            if w0 <= s <= w1:
                zs = max(zg, lvl)
        c = inside(s)
        out.append((s, G["a"][0] + G["ux"] * s, G["a"][1] + G["uy"] * s, zg, zs, c[3] if c else None, walls.get(s),
                    tsec_zg(G, s, "terrain")))
    memo[mk] = out
    return out


def tsec_k0(c, zlo, dz, hmin):
    """First height index of a column in open air: hmin above the ground or water, above the roof inside a building."""
    lim = c[4] + hmin if c[5] is None else max(c[4] + hmin, c[5] + 1e-6)
    return max(0, int(math.ceil((lim - zlo) / dz - 0.5)))


def tsec_nz(G, dz):
    return int(math.ceil((G["zhi"] - G["zlo"]) / dz))


def casters_frame(S, reach=ENV_REACH):
    """The casters of the frame (walls, crowns, horizons), built once per bake and shared by every section line."""
    memo = env_memo(S)
    C = memo.get(("casters16", reach))
    if C is None:
        C = memo[("casters16", reach)] = Casters16(S, S.env["E"], S.env["solids"], S.F, reach)
    return C


def slope_normals(S, X, Y, h=6.0):
    """The plan's ground normal at points (slope over 6 m, capped at 35 degrees): world x, y and up."""
    X = np.asarray(X, float)
    Y = np.asarray(Y, float)
    zx = (z_np(S, X + h, Y) - z_np(S, X - h, Y)) / (2.0 * h)
    zy = (z_np(S, X, Y + h) - z_np(S, X, Y - h)) / (2.0 * h)
    sl = np.hypot(zx, zy)
    f = np.where(sl > 0.7, 0.7 / np.where(sl > 0, sl, 1.0), 1.0)
    zx, zy = zx * f, zy * f
    n_ = np.sqrt(zx * zx + zy * zy + 1.0)
    return -zx / n_, -zy / n_, 1.0 / n_


def tsec_plane(S, G, ds=None, dz=None):
    """The receivers of a line's plane: per column (every ds along the line and one outside every cut wall) the
    heights every dz from 0.25 m above the ground or water (above the roof inside a cut building) to the top, as
    point receivers with the ground's slope under them. Built once per line, spacing and bake (v16.6: the shade has
    its own, finer plane: TSEC_DS_SHADE, TSEC_DZ_SHADE)."""
    ds = TSEC_DS if ds is None else ds
    dz = TSEC_DZ if dz is None else dz
    memo = env_memo(S)
    mk = ("tsec_plane", G["key"], ds, dz)
    r = memo.get(mk)
    if r is not None:
        return r
    cols = tsec_cols(S, G, ds)
    zlo = G["zlo"]
    nz = tsec_nz(G, dz)
    k0 = np.array([tsec_k0(c, zlo, dz, 0.25) for c in cols], np.int64)
    cnt = np.maximum(nz - k0, 0)
    pid = np.repeat(np.arange(len(cols)), cnt)
    kz = np.repeat(k0, cnt) + (np.arange(int(cnt.sum())) - np.repeat(np.cumsum(cnt) - cnt, cnt))
    Z = zlo + (kz + 0.5) * dz
    X = np.array([c[1] for c in cols])
    Y = np.array([c[2] for c in cols])
    terr = np.array([c[7] for c in cols])
    nwx, nwy, nzz = slope_normals(S, X, Y)
    hg = np.maximum(0.0, Z - terr[pid])                       # height above the ground: the slope's plane falls away
    hgl = np.maximum(0.25, Z - terr[pid])
    C = casters_frame(S)
    P = Points16(C, X, Y, pid, Z, nrm=(nwx[pid], nwy[pid], nzz[pid]), hg=hg, zair=Z - 2.0,
                 wf=np.log(hgl / 0.1) / TSEC_LN15)
    tab = hz_fall_table(S, C, X, Y, terr)
    if tab is not None:
        P.hzf = HzFall(tab, C.step, pid, hg)
    r = memo[mk] = dict(P=P, cols=cols, pid=pid, kz=kz, nz=nz, zlo=zlo, dz=dz, hgl=hgl)
    return r


def tsec_vals(pl, v):
    """Receiver values back to the columns of the plane (None below a column's first height)."""
    out = [[None] * pl["nz"] for _ in pl["cols"]]
    for p, k, x in zip(pl["pid"].tolist(), pl["kz"].tolist(), np.asarray(v, float).tolist()):
        out[p][k] = (None if x != x else x)
    return out


def tsec_shade(S, G):
    """Hours out of the sun at every point of the plane: the four key days and the mean day of the year, every minute
    the sun is up, through the exact 3D obstruction of every point (as on the plan, T3). v16.6: on its own plane every
    TSEC_DS_SHADE along the line and TSEC_DZ_SHADE in height (v16.5: 1.0 m x 0.5 m)."""
    keys = S.env["keys"]
    key = fp("sec_shade", MV["sec_field"], G["key"], keys["solids"], TSEC_DS_SHADE, TSEC_DZ_SHADE, SUN_BINS)
    res = S.store.get("sec_shade", key)
    if res is not None:
        return res
    pl = tsec_plane(S, G, TSEC_DS_SHADE, TSEC_DZ_SHADE)
    P = pl["P"]
    memo = env_memo(S)
    MS = memo.get("minute_sun")
    if MS is None:
        MS = memo["minute_sun"] = minute_sun(S.env["E"])
    SJ = ShadeJob(P, MS)
    sun_pass(P, casters_frame(S), [SJ])
    out = dict(zlo=pl["zlo"], dz=pl["dz"], nz=pl["nz"], s=[c[0] for c in pl["cols"]], days={})
    for k, sd in enumerate(SEASONS):
        out["days"][sd["key"]] = dict(SJ.days[k], vals=tsec_vals(pl, SJ.acc[2 + k] / 60.0))
    out["year"] = dict(daylight=SJ.year_daylight, vals=tsec_vals(pl, (SJ.acc[0] + SJ.acc[1]) / 60.0 / 365.0))
    return S.store.put("sec_shade", key, out)


def tsec_sky(S, G):
    """The sky view of every point of the plane (solid angle, crowns in and out of leaf), kept per line."""
    memo = env_memo(S)
    mk = ("tsec_sky", G["key"])
    r = memo.get(mk)
    if r is None:
        key = fp("sec_sky", MV["sec_field"], G["key"], S.env["keys"]["solids"], TSEC_DS, TSEC_DZ, SKY_BINS)
        r = S.store.get("sec_sky", key)
        if r is None:
            pl = tsec_plane(S, G)
            r = S.store.put("sec_sky", key, sky_pass(pl["P"], casters_frame(S))["svf"])
        memo[mk] = r
    return r


def tsec_shelter(S, G):
    """Share of the open-ground wind left at every point of the plane for every wind sector, crowns in and out of
    leaf: each building and crown upwind within the fetch (exact distance along the wind) counts with its height above
    that point's level (height above ground - 1.5 m) through the plan's windbreak wake curves; at 1.5 m above ground
    this is the plan's shelter. (sectors, leaf, receivers)"""
    memo = env_memo(S)
    mk = ("tsec_shelter", G["key"])
    r = memo.get(mk)
    if r is not None:
        return r
    pl = tsec_plane(S, G)
    P = pl["P"]
    Cw = casters_frame(S, TSEC_FETCH)
    R = TSEC_FETCH
    n = P.n
    ok_e = ((np.maximum(Cw.AX, Cw.BX) >= P.pu.min() - R) & (np.minimum(Cw.AX, Cw.BX) <= P.pu.max() + R) &
            (np.maximum(Cw.AY, Cw.BY) >= P.pv.min() - R) & (np.minimum(Cw.AY, Cw.BY) <= P.pv.max() + R))
    AX, AY, BX, BY, own, Hb = Cw.AX[ok_e], Cw.AY[ok_e], Cw.BX[ok_e], Cw.BY[ok_e], Cw.own[ok_e], Cw.HB[ok_e]
    ok_c = ((Cw.CU + Cw.CR >= P.pu.min() - R) & (Cw.CU - Cw.CR <= P.pu.max() + R) &
            (Cw.CV + Cw.CR >= P.pv.min() - R) & (Cw.CV - Cw.CR <= P.pv.max() + R))
    CU, CV, CR, CHR, CK = Cw.CU[ok_c], Cw.CV[ok_c], Cw.CR[ok_c], Cw.CHR[ok_c], Cw.CK[ok_c]
    cgrp = np.where(CK == 2, 2, 1)                        # 1 evergreen (pine, olive), 2 deciduous
    cc = pl["hgl"] - 1.5                                  # each receiver's level: height above the ground - 1.5 m
    out = np.ones((WIND_BINS, 2, n), np.float32)
    BIG = 1 << 40
    for k in range(WIND_BINS):
        d = Cw.dir_local(k * 360.0 / WIND_BINS)           # toward where the wind comes from
        dx, dy = d
        obs_p, obs_x, obs_h, obs_g = [], [], [], []
        if AX.size:
            aA, bA = AX * dx + AY * dy, -AX * dy + AY * dx
            aB, bB = BX * dx + BY * dy, -BX * dy + BY * dx
            okb = bA != bB
            e, p, bp = P._pairs(d, np.where(okb, np.minimum(bA, bB), np.inf), np.where(okb, np.maximum(bA, bB), -np.inf))
            if e.size:
                ap = P.pu[p] * dx + P.pv[p] * dy
                t = aA[e] + (bp[p] - bA[e]) * (aB[e] - aA[e]) / (bB[e] - bA[e]) - ap
                m = t > 0.0
                e, p, t = e[m], p[m], t[m]
                kb = p.astype(np.int64) * BIG + own[e]
                o = np.lexsort((t, kb))
                kb, t, e = kb[o], t[o], e[o]
                first = np.flatnonzero(np.r_[True, kb[1:] != kb[:-1]])
                cnt_ = np.diff(np.r_[first, kb.size])
                use = (cnt_ % 2 == 0) & (t[first] <= R)    # an odd count: the point stands in that building
                obs_p.append((kb[first] // BIG)[use])
                obs_x.append(t[first][use])
                obs_h.append(Hb[e[first]][use])
                obs_g.append(np.zeros(int(use.sum()), np.int64))
        if CU.size:
            ac, bc = CU * dx + CV * dy, -CU * dy + CV * dx
            e, p, bp = P._pairs(d, bc - CR, bc + CR)
            if e.size:
                perp = bp[p] - bc[e]
                m = np.abs(perp) < CR[e]
                e, p, perp = e[m], p[m], perp[m]
                hw = np.sqrt(CR[e] ** 2 - perp ** 2)
                along = ac[e] - (P.pu[p] * dx + P.pv[p] * dy)
                m = (along + hw > 0.0) & (along - hw <= R)
                e, p, along, hw = e[m], p[m], along[m], hw[m]
                obs_p.append(p)
                obs_x.append(np.maximum(0.0, along - hw))
                obs_h.append(CHR[e])
                obs_g.append(cgrp[e])
        if not obs_p:
            continue
        op, ox, oh, og = (np.concatenate(q) for q in (obs_p, obs_x, obs_h, obs_g))
        k0, cntr = P.r0[op], P.r1[op] - P.r0[op]
        tot = int(cntr.sum())
        if tot == 0:
            continue
        q = np.repeat(np.arange(op.size), cntr)
        r = np.repeat(k0, cntr) + (np.arange(tot) - np.repeat(np.cumsum(cntr) - cntr, cntr))
        he = oh[q] - cc[r]
        m = he > 0.0
        q, r, he = q[m], r[m], he[m]
        Q = np.full((3, n), np.inf)
        np.minimum.at(Q, (og[q], r), ox[q] / he)
        fB = wake_np(WAKE_SOLID, Q[0])
        fE = wake_np(WAKE_LEAFY, Q[1])
        base = np.minimum(fB, fE)
        out[k, 0] = np.minimum(base, wake_np(WAKE_LEAFY, Q[2]))
        out[k, 1] = np.minimum(base, wake_np(WAKE_BARE, Q[2]))
    memo[mk] = out
    return out


def tsec_comfort(S, G):
    """Per season, the means over the window hours at every point of the plane: felt temperature (UTCI) every hour
    with that point's sun or shade, sky view and wind; the wind at that height; the air temperature."""
    keys = S.env["keys"]
    key = fp("sec_comfort", MV["sec_field"], G["key"], keys["solids"], keys["comfort"], TSEC_DS, TSEC_DZ)
    res = S.store.get("sec_comfort", key)
    if res is not None:
        return res
    pl = tsec_plane(S, G)
    P = pl["P"]
    TT = S.env["TT"]
    win = window_mask(TT)
    svf = tsec_sky(S, G)
    shel = tsec_shelter(S, G)
    CJ = ComfortJob(P, TT, win, svf, shel)
    sun_pass(P, casters_frame(S), [CJ])
    CJ.finish()
    lnw = np.log(pl["hgl"] / 0.1) / TSEC_LN10             # the log law from 10 m to each height
    out = dict(zlo=pl["zlo"], dz=pl["dz"], nz=pl["nz"], s=[c[0] for c in pl["cols"]], seasons={})
    for si, sd in enumerate(SEASONS):
        hs = np.flatnonzero(win & (TT["si"] == si))
        N = max(1, hs.size)
        W = np.zeros((WIND_BINS, 2))
        np.add.at(W, (wind_bin(TT["wd10"][hs]), np.where(TT["leaf"][hs], 0, 1)), TT["ws10"][hs])
        wind = np.zeros(P.n)
        for kk, ll in zip(*np.nonzero(W)):
            wind += W[kk, ll] * shel[kk, ll]
        wind *= lnw / N
        sun_h = int(((TT["el"][hs] >= 2.0) & (TT["dni"][hs] > 0.0)).sum())
        out["seasons"][sd["key"]] = dict(
            hours=int(hs.size), utci=tsec_vals(pl, CJ.su[si] / N), sun=tsec_vals(pl, CJ.sT[si] / max(1, sun_h)),
            ta=tsec_vals(pl, float(TT["t2m"][hs].mean()) + CJ.dl), wind=tsec_vals(pl, wind),
            ta_mean=float(TT["t2m"][hs].mean()) if hs.size else None, u10_mean=float(TT["ws10"][hs].mean()) if hs.size else None,
            rh_mean=float(TT["rh"][hs].mean()) if hs.size else None)
    return S.store.put("sec_comfort", key, out)


def tsec_solar(S, G):
    """Mean kWh/m2 per day of each season on the ground under the line, on the cut roofs and on the cut facades: the
    plan's model (T4) at each of these points, every hour of the typical year, each with its own exact 3D
    obstruction, cosine-weighted sky and own plane.
    v16.6: the ground and the roofs evenly every TSEC_DS_SOLAR (0.25 m), each point standing for the strip of that
    width around it; the facades in bands of at most TSEC_DZ_SOLAR. v16.5 sampled the ground every 1.0 m plus one extra
    point 0.25 m outside every cut wall, and the roofs every 1.5 m: the extra wall-foot points (the darkest ground of
    an alley) stood for 0.25 m but were joined by straight lines to points 1 m away, so every cut wall drew a sharp V
    in the graph; the more buildings a section cuts, the more V's. Ground: (s0, s1, z, values)."""
    keys = S.env["keys"]
    key = fp("sec_solar", MV["sec_field"], G["key"], keys["solids"], TSEC_DS_SOLAR, TSEC_DZ_SOLAR, SUN_BINS, SKY_BINS)
    res = S.store.get("sec_solar", key)
    if res is not None:
        return res
    (x0, y0), ux, uy = G["a"], G["ux"], G["uy"]
    pts = []                                              # (kind, x, y, z, nx, ny, nz, info)
    cut = G["cut"]
    ds = TSEC_DS_SOLAR
    sp_ = sorted((c[0], c[1]) for c in cut)
    opn, a_ = [], 0.0                                     # the open stretches of the line, between the cut buildings
    for c0, c1 in sp_:
        if c0 > a_:
            opn.append((a_, min(c0, G["L"])))
        a_ = max(a_, c1)
    if a_ < G["L"]:
        opn.append((a_, G["L"]))
    gs = []
    for o0, o1 in opn:                                    # strips of at most ds, ending at the walls
        n = int(math.ceil((o1 - o0) / ds - 1e-9))
        for q in range(n):
            gs.append((o0 + (o1 - o0) * q / n, o0 + (o1 - o0) * (q + 1) / n))
    if gs:
        sm = np.array([0.5 * (p[0] + p[1]) for p in gs])
        gx, gy = x0 + ux * sm, y0 + uy * sm
        nwx, nwy, nzz = slope_normals(S, gx, gy)
        for q, (p0, p1) in enumerate(gs):
            s_ = float(sm[q])
            zg = tsec_zg(G, s_)
            zs = zg
            for w0, w1, bed, lvl in G["water"]:
                if w0 <= s_ <= w1:
                    zs = max(zg, lvl)
            pts.append(("g", float(gx[q]), float(gy[q]), zs + 0.05, nwx[q], nwy[q], nzz[q], (p0, p1, zs)))
    for ci, c in enumerate(cut):
        s0, s1, base, top, bi = c[:5]
        n = max(1, int(math.ceil((s1 - s0) / ds - 1e-9)))
        for q in range(n):
            a_, b_ = s0 + (s1 - s0) * q / n, s0 + (s1 - s0) * (q + 1) / n
            sm = (a_ + b_) / 2.0
            pts.append(("r", x0 + ux * sm, y0 + uy * sm, top + 0.05, 0.0, 0.0, 1.0, (a_, b_, top)))
        for s_w, nrm, outer in ((s0, c[8], s0 - 0.3), (s1, c[9], s1 + 0.3)):
            if not (0.0 < s_w < G["L"]):
                continue                                  # the wall is the end of the line, not a cut facade
            lo = tsec_zg(G, min(max(outer, 0.0), G["L"]))
            for c2 in cut:
                if c2 is not c and c2[0] - 0.3 <= outer <= c2[1] + 0.3:
                    lo = max(lo, c2[3])                   # a lower neighbour: only the wall above its roof is exposed
            if top - lo < 0.5:
                continue
            nb_ = max(1, min(120, int(math.ceil((top - lo) / TSEC_DZ_SOLAR - 1e-9))))
            px, py = x0 + ux * s_w + nrm[0] * 0.05, y0 + uy * s_w + nrm[1] * 0.05
            for q in range(nb_):
                z0, z1 = lo + (top - lo) * q / nb_, lo + (top - lo) * (q + 1) / nb_
                pts.append(("w", px, py, (z0 + z1) / 2.0, nrm[0], nrm[1], 0.0, (s_w, z0, z1, 1 if outer > s_w else -1, nrm)))
    out = dict(ground=[], roofs=[], walls=[])
    if not pts:
        return S.store.put("sec_solar", key, out)
    E = S.env["E"]
    C = casters_frame(S)
    n = len(pts)
    P = Points16(C, [p[1] for p in pts], [p[2] for p in pts], np.arange(n), [p[3] for p in pts],
                 nrm=(np.array([p[4] for p in pts]), np.array([p[5] for p in pts]), np.array([p[6] for p in pts])))
    PX, PY = np.array([p[1] for p in pts]), np.array([p[2] for p in pts])
    PG = z_np(S, PX, PY)
    tab = hz_fall_table(S, C, PX, PY, PG)
    if tab is not None:
        P.hzf = HzFall(tab, C.step, np.arange(n), np.array([p[3] for p in pts]) - PG)
    TT = S.env["TT"]
    sky = sky_pass(P, C, want_k=True)
    RJ = RadJob(P, TT, C.CP)
    sun_pass(P, C, [RJ])
    vals = rad_totals(P, TT, sky, RJ)
    for k, p in enumerate(pts):
        v = dict((sd["key"], float(vals[sd["key"]][k])) for sd in SEASONS)
        if p[0] == "g":
            out["ground"].append(p[7] + (v,))
        elif p[0] == "r":
            out["roofs"].append(p[7] + (v,))
        else:
            out["walls"].append(p[7] + (v,))
    return S.store.put("sec_solar", key, out)


def tsec_noise_key(S, G):
    return fp("sec_noise", MV["sec_field"], G["key"], S.env["keys"]["noise_raw"], TSEC_DS_SOUND, TSEC_DZ_SOUND)


def tsec_noise_prep(S, G):
    cols = tsec_cols(S, G, TSEC_DS_SOUND)
    zlo, dz = G["zlo"], TSEC_DZ_SOUND
    nz = tsec_nz(G, dz)
    k0s, tasks = [], []
    for c in cols:
        k0 = tsec_k0(c, zlo, dz, 0.5)
        zrs = [zlo + (kz + 0.5) * dz for kz in range(k0, nz)]
        k0s.append(k0)
        if zrs:
            tasks.append((c[1], c[2], c[4], zrs))
    return cols, k0s, tasks, zlo, dz, nz


def tsec_noise_start(S):
    """v17: the receivers of every sound section not in the store, all lines in one batch, handed to the worker
    processes before the plan sheets are drawn: they run while Rhino draws and computes the other analyses."""
    lines = tsec_lines(S).get("sound_sections") or []
    pre, tasks = {}, []
    job = dict()
    for k, a, b in lines:
        G = tsec_geom(S, a, b)
        key = tsec_noise_key(S, G)
        if key in pre or S.store.get("sec_noise", key) is not None:
            continue
        prep = tsec_noise_prep(S, G)
        pre[key] = dict(prep=prep, job=job, at=len(tasks))
        tasks += prep[2]
    if tasks:
        job["h"] = noise_par_start(noise_model(S), tasks, "multi", "sections")
    S.env["tsec_noise_pre"] = pre


def tsec_noise(S, G):
    """Road traffic noise at every receiver of the plane (the plan's model), day, evening, night and Lden; the plan's
    calibration offset is added on use."""
    key = tsec_noise_key(S, G)
    res = S.store.get("sec_noise", key)
    if res is None:
        pre = (S.env.get("tsec_noise_pre") or {}).pop(key, None)       # v17: started early with every other line
        cols, k0s, tasks, zlo, dz, nz = pre["prep"] if pre else tsec_noise_prep(S, G)
        vals = dict(day=[], evening=[], night=[], lden=[])
        if pre:
            job = pre["job"]
            if "out" not in job:
                job["out"] = noise_par_collect(job["h"])
            got = job["out"][pre["at"]:pre["at"] + len(tasks)]
        else:
            got = noise_par(noise_model(S), tasks, "multi", "section")      # v17: on every core
        rs_ = iter(got)
        for c, k0 in zip(cols, k0s):
            r = next(rs_) if k0 < nz else []
            for p, nm_ in enumerate(("day", "evening", "night", "lden")):
                vals[nm_].append([None] * k0 + [(q[p] if q else None) for q in r])
        res = S.store.put("sec_noise", key, dict(zlo=zlo, dz=dz, nz=nz, s=[c[0] for c in cols], vals=vals))
    off = S.env["noise"].get("offset", 0.0)
    if off:
        res = dict(res, vals=dict((k, [[(v + off if v is not None else None) for v in col] for col in cols_])
                                  for k, cols_ in res["vals"].items()))
    return res


def tsec_heat(S, G, season):
    """Landsat surface temperature along the line every metre, on the roof where it crosses a building, else on the
    ground or water (bilinear in the scene's 30 m grid, as the plan samples it)."""
    L_ = S.env["lst"].get(season)
    if not L_:
        return None
    out = []
    n = int(G["L"])
    for i in range(n):
        s = i + 0.5
        x, y = G["a"][0] + G["ux"] * s, G["a"][1] + G["uy"] * s
        top = None
        for c in G["cut"]:
            if c[0] <= s <= c[1]:
                top = c[3]
        z = top if top is not None else tsec_zg(G, s)
        out.append((s, z, lst_sample(L_, x, y), top is not None))
    return out


# ------------------------------------------------------------ technical sections: pictures, drawing, sheets


def bands_key(bands):
    return fp([(round(a, 6), round(b, 6), round(c, 6), round(d, 6), v) for a, b, c, d, v in bands])


def tsec_keyplan_png(S, d):
    """The key plan's base as one picture (buildings, water, open ground at 2 m), shared by every section sheet."""
    memo = env_memo(S)
    r = memo.get("tsec_keyplan")
    if r is not None:
        return r
    path = os.path.join(d, "key_plan.png")
    TB = tech_core(S, S.F, 2.0)
    w, h = TB["cv"].w, TB["cv"].h
    full = fp("keyplan", MV["render"], core_key(S, S.F, 2.0))
    e_ = maps_index(S, d).get("key_plan.png")
    try:
        if e_ and e_.get("key") == full and os.path.getsize(path) == e_.get("size"):
            memo["tsec_keyplan"] = path
            return path
    except Exception:
        pass
    bid, water = TB["bid"], TB["water"]
    pal = (bytes((244, 244, 246)), bytes((198, 198, 204)), bytes((168, 198, 222)))
    rows = []
    for py in range(h):
        o = py * w
        rows.append(b"".join(pal[1] if bid[i] else (pal[2] if water[i] else pal[0]) for i in range(o, o + w)))
    png_write(path, w, h, b"".join(rows))
    try:
        maps_index(S, d)[os.path.basename(path)] = dict(key=full, size=os.path.getsize(path), w=w, h=h)
        maps_index_save(S, d)
    except Exception:
        pass
    memo["tsec_keyplan"] = path
    return path


def tsec_key_plan(S, B, x, ytop, w, G, lab, U, L, d):
    """Where the line runs: buildings and water (one shared picture), the frame, and the line with its ends."""
    V, mw, mh = view_fit(S.F, x, ytop, w, w * S.F.h / S.F.w)
    B.image(tsec_keyplan_png(S, d), V.X0, ytop - mh, V.X0 + mw, ytop, L, 3)
    B.line(V.P(S.F.P + [S.F.P[0]]), T_RULE, L, 6, 0.06)
    a, b = V.p(*G["a"]), V.p(*G["b"])
    B.line([a, b], (200, 30, 30), L, 7, 0.2)
    for q, t in ((a, lab), (b, lab + "'")):
        ring = circle_pts(q[0], q[1], 0.32 * U, 16)
        B.fill([ring], (255, 255, 255), L, 8)
        B.line(ring + [ring[0]], (200, 30, 30), L, 9, 0.05)
        B.text(t, q[0], q[1], 0.26 * U, T_INK, L, order=10, font=FONT_TITLE, bold=True, align="MC")
    draw_north_small(B, V, mw, mh, U, L, size=0.45)
    return ytop - mh


TSEC_GRAPH_END = 1.25    # m: v16.4: the first and last column's value reaches the section's ends (half a column at most)
TSEC_GRAPH_GAP = 6.0     # m: v16.4: a graph line runs on across a gap in its points up to this long (columns are 1-2.5 m
#                          apart, plus one just outside every cut wall); only a longer stretch with no value breaks it


def graph_runs(pts, gap=TSEC_GRAPH_GAP):
    """v16.4: the points of a graph [(s, v) or (s, v, on_roof)] as continuous runs [(points [(s, v)], on_roof)].
    Where the line passes from the open ground onto a cut building's roof (or back), the two runs meet at the middle
    of the step between their last and first points: the value steps there, with no white gap (v16.3 left a gap at
    every wall). A run breaks only where a value is missing or the points are more than `gap` metres apart."""
    out = []
    run, rf0, prev = [], False, None
    for p_ in sorted((p for p in pts if p[0] is not None), key=lambda p: p[0]):
        s_, v_ = p_[0], p_[1]
        rf = bool(p_[2]) if len(p_) > 2 else False
        if v_ is None:
            if run:
                out.append((run, rf0))
            run, prev = [], None
            continue
        if prev is not None and s_ - prev[0] > gap:
            out.append((run, rf0))
            run = []
        elif prev is not None and rf != rf0:
            m_ = 0.5 * (prev[0] + s_)                     # the step between ground and roof, at the wall
            run.append((m_, prev[1]))
            out.append((run, rf0))
            run = [(m_, v_)]
            rf0 = rf
        if not run:
            rf0 = rf
        run.append((s_, v_))
        prev = (s_, v_)
    if run:
        out.append((run, rf0))
    return out


TSEC_TREND = 10.0        # v16.6: m, the window of the running mean drawn over the solar and shade graphs
TSEC_TREND_C = (28, 58, 108)


def graph_trend(pts, win=TSEC_TREND, step=0.25, gap=TSEC_GRAPH_GAP):
    """v16.6: the running mean of a graph's values over `win` metres of line (each point the average of the line
    `win` long centred on it, the values taken every `step` m between the points), as runs [(s, v)]; it breaks where
    the graph breaks (a stretch longer than `gap` with no value). Drawn OVER the full-detail graph, never instead of
    it: the detail stays, the mean shows the trend through the walls of a densely built stretch."""
    q = sorted((p_[0], p_[1]) for p_ in pts if p_[0] is not None and p_[1] is not None)
    if len(q) < 2:
        return []
    S_ = np.array([a for a, b in q], float)
    V_ = np.array([b for a, b in q], float)
    g = np.arange(S_[0], S_[-1] + 1e-9, step)
    v = np.interp(g, S_, V_)
    k = np.searchsorted(S_, g)
    dl = np.abs(g - S_[np.clip(k - 1, 0, S_.size - 1)])
    dr = np.abs(S_[np.clip(k, 0, S_.size - 1)] - g)
    ok = (np.minimum(dl, dr) <= 0.5 * gap) | (np.maximum(dl, dr) <= gap)
    out = []
    i = 0
    n = g.size
    h = max(1, int(round(0.5 * win / step)))
    while i < n:
        if not ok[i]:
            i += 1
            continue
        j = i
        while j + 1 < n and ok[j + 1]:
            j += 1
        vv = v[i:j + 1]
        c = np.concatenate([[0.0], np.cumsum(vv)])
        idx = np.arange(vv.size)
        a = np.clip(idx - h, 0, vv.size)
        b = np.clip(idx + h + 1, 0, vv.size)
        m = (c[b] - c[a]) / (b - a)
        out.append(list(zip(g[i:j + 1].tolist(), m.tolist())))
        i = j + 1
    return out


def tsec_graph(B, x, ytop, w, h, Lm, series, lo, hi, U, L, unit, colour=None, dec=VAL_DEC, trend=None):
    """Values along the line under a section: series = [(points [(s, v)] or [(s, v, on_roof)], colour, weight)];
    a coloured ribbon under the first series when colour is given. v16.4: one continuous line along the whole section
    (graph_runs): the roof stretches (the value at the same height above the cut building's roof, as the plan shows a
    building) are dashed over a paler ribbon with a roof mark below, and join the ground stretches at the walls."""
    X_ = lambda s_: x + w * max(0.0, min(Lm, s_)) / Lm
    Y_ = lambda v_: ytop - h + h * (max(lo, min(hi, v_)) - lo) / (hi - lo)
    B.fill([rect(x, ytop - h, x + w, ytop)], (250, 250, 251), L, 20)
    step = nice_step(hi - lo, 3)
    v = math.ceil(lo / step) * step
    f_ = tick_fmt(step, dec)                          # v16.3: decimals when the range is narrow (v16.6: at least dec)
    while v <= hi + 1e-9:
        B.line([(x, Y_(v)), (x + w, Y_(v))], (218, 218, 224), L, 21, 0.02)
        B.text((f_ % v) + unit, x - 0.2 * U, Y_(v) - 0.09 * U, 0.2 * U, T_GREY, L, align="R")
        v += step
    yb_ = ytop - h
    seam = 0.015 * U                                  # each ribbon piece reaches a hair into the next: no white seams
    for si, (pts, col, lw) in enumerate(series):
        runs_ = graph_runs(pts)
        if runs_:                                     # the end columns stand for half a column each: reach the frame
            r0, rl = runs_[0][0], runs_[-1][0]
            if 0.0 < r0[0][0] <= TSEC_GRAPH_END:
                r0.insert(0, (0.0, r0[0][1]))
            if 0.0 < Lm - rl[-1][0] <= TSEC_GRAPH_END:
                rl.append((Lm, rl[-1][1]))
        for run, roof_run in runs_:
            if len(run) == 1:                             # a single point: half a column either side
                s_, v_ = run[0]
                run = [(s_ - 0.5, v_), (s_ + 0.5, v_)]
            if si == 0 and colour is not None:            # one ribbon piece per stretch of the same colour
                k0 = 0
                c0 = colour((run[0][1] + run[1][1]) / 2.0)
                for k in range(1, len(run)):
                    ck = colour((run[k][1] + run[k + 1][1]) / 2.0) if k < len(run) - 1 else None
                    if ck != c0:
                        top_ = [(X_(a_), Y_(b_)) for a_, b_ in run[k0:k + 1]]
                        cf_ = mix(c0, (255, 255, 255), 0.45) if roof_run else c0
                        xr_ = min(x + w, top_[-1][0] + seam)
                        B.fill([[(top_[0][0], yb_), (xr_, yb_), (xr_, top_[-1][1])] + top_[::-1]], cf_, L, 22)
                        k0, c0 = k, ck
            ln_ = [(X_(a_), Y_(b_)) for a_, b_ in run]
            if roof_run:
                for dd in dashes(ln_, 0.12 * U, 0.08 * U):
                    B.line(dd, col, L, 23, lw)
                x0r, x1r = X_(run[0][0]), X_(run[-1][0])
                B.fill([[(x0r, yb_), (x1r, yb_), (x1r, yb_ + 0.1 * U), (x0r, yb_ + 0.1 * U)]], (120, 120, 128), L, 24)
            else:
                B.line(ln_, col, L, 23, lw)
        # the steps at the walls: a thin vertical joining the two values, so the line reads as one
        for (ra, fa), (rb, fb) in zip(runs_, runs_[1:]):
            if fa != fb and abs(ra[-1][0] - rb[0][0]) < 1e-6:
                xs_ = X_(ra[-1][0])
                B.line([(xs_, Y_(ra[-1][1])), (xs_, Y_(rb[0][1]))], col, L, 23, lw * 0.6)
    if trend and series:                                  # v16.6: the running mean over the detail
        for run in graph_trend(series[0][0], trend):
            if len(run) >= 2:
                B.line([(X_(a_), Y_(b_)) for a_, b_ in run], (255, 255, 255), L, 25, 0.22)
                B.line([(X_(a_), Y_(b_)) for a_, b_ in run], TSEC_TREND_C, L, 26, 0.12)
    B.line(rect(x, ytop - h, x + w, ytop) + [(x, ytop - h)], T_RULE, L, 24, 0.04)
    return ytop - h


def tsec_at(fld, i, z):
    """Value of field column i at height z (linear between its heights), or None."""
    col = fld["vals"][i]
    fk = (z - fld["zlo"]) / fld["dz"] - 0.5
    k0 = int(math.floor(fk))
    if k0 < 0 or k0 >= fld["nz"] - 1:
        return None
    a, b = col[k0], col[k0 + 1]
    if a is None or b is None:
        return a if b is None else b
    return a + (b - a) * (fk - k0)


TSEC_NAMES16 = ("N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW")


# ============================================================ TECHNICAL SECTIONS v16.2: lively base + analysis wash
# Every row of a technical section is one picture: the view beyond the cut (ground, buildings, crowns at their measured
# size and leaf state, scale figures) under the analysis as a translucent wash, the surface bands on the surfaces; the
# cut itself (ground, water, cut buildings), contours, arrows and text are drawn as vectors over it.
TSEC_WASH = 0.95            # strength of the analysis colours, multiplied over the drawing
TSEC_DPI = 450.0            # pictures are made for this print resolution at the sheet's printed size (sheet_mm; v16.6: 300 -> 450)
SA_VERSION = 3              # v16.4: building types in their own tones, jetties, minarets; trees whole


def tsec_px_res(G, ss):
    """Metres per pixel for a drawing printed at ss (page units per metre): TSEC_DPI at the printed size, kept between
    0.08 and 0.6 m and at most 9000 pixels along the line (v16.6: 5000)."""
    mm_per_m = ss * MMU
    res = 25.4 / (TSEC_DPI * max(1e-6, mm_per_m))
    res = max(0.08, min(0.6, res))
    res = max(res, G["L"] / 9000.0)                   # v16.6: up to 9000 pixels along the line (v16.5: 5000)
    return round(res, 4)


def _pool_sa_base(sc, L, zlo, zhi, res, leaf, pal, ground):
    """v18: tsec_base's drawing, on a worker (the same call; sa_render does not read the site object)."""
    art, r_ = sa_render(None, sc, 0.0, L, zlo, zhi, res, SA_STYLE_TECH, leaf=leaf, season=pal, ground=ground)
    return art.to_bytes()


TSEC_PLAN = (("sound_sections", 4, 0.0), ("heat_sections", 4, 2.0), ("shade_sections", 5, 0.0),
             ("solar_sections", 4, 2.0), ("wind_sections", 4, 0.0), ("air_sections", 4, 0.0), ("felt_sections", 4, 0.0))


def tsec_seasons(S, key):
    """The leaf states (season arguments) the rows of a section sheet draw with, as the tsec_sheet_* functions pass
    them to tsec_compose."""
    if key == "sound_sections":
        return ["year"]
    if key == "shade_sections":
        return [sd["day"] for sd in SEASONS] + ["year"]
    if key == "heat_sections":
        out = []
        for sd in SEASONS:
            when = S.env["lst"].get(sd["key"], {}).get("datetime_utc", "")
            try:
                out.append((int(when[5:7]), int(when[8:10])))
            except Exception:
                out.append(sd["key"])
        return out
    return [sd["key"] for sd in SEASONS]


def tsec_prefetch(S, U):
    """v18: the drawings behind every technical section row (one per line, picture resolution and leaf state), started
    on the worker processes before the sheets are made; tsec_base takes them from there. These are the very calls
    tsec_base makes, with the same arguments; one not asked for later is only work done in vain."""
    S.env["sa_pre"] = {}
    if not pool_live():
        return 0
    lines = tsec_lines(S)
    ST = S.store
    todo = {}
    for key, nrows, gh in TSEC_PLAN:
        if key in ("wind_sections", "air_sections", "felt_sections") and not S.env.get("comfort"):
            continue
        for k, a, b in lines.get(key, []):
            G = tsec_geom(S, a, b)
            lay = tsec_layout(S, G, U, nrows, graph_h=gh * U) if gh else tsec_layout(S, G, U, nrows)
            res = tsec_px_res(G, lay["ss"])
            for season in tsec_seasons(S, key):
                leaf, tag, pal = tsec_season_tag(season)
                fk = fp("sa_base", SA_VERSION, G["key"], round(res, 4), round(leaf, 3), pal)
                if fk in todo or (ST is not None and ST.has("sa_base", fk)):
                    continue
                todo[fk] = (sa_scene(S, G["a"], G["b"]), G["L"], G["zlo"], G["zhi"], res, leaf, pal, G["ground"])
    if todo:
        job = pool_submit("_pool_sa_base", list(todo.values()), prio=8, label="section drawings")
        pre = S.env.setdefault("sa_pre", {})
        for i, fk in enumerate(todo):
            pre[fk] = (job, i)
    return len(todo)


def tsec_base(S, G, res, season):
    """The drawing behind the cut of one line for one leaf state (shared by every row and analysis using it)."""
    leaf, tag, pal = tsec_season_tag(season)
    key = fp("sa_base", SA_VERSION, G["key"], round(res, 4), round(leaf, 3), pal)
    ST = S.store
    v = ST.get("sa_base", key) if ST is not None else None
    if v is not None:
        return v
    pre = (S.env.get("sa_pre") or {}).pop(key, None)
    if pre is not None:                                  # v18: made on the worker processes (tsec_prefetch)
        v = pool_result(pre[0])[pre[1]]
    else:
        sc = sa_scene(S, G["a"], G["b"])
        art, r_ = sa_render(S, sc, 0.0, G["L"], G["zlo"], G["zhi"], res, SA_STYLE_TECH, leaf=leaf, season=pal,
                            ground=G["ground"])
        v = art.to_bytes()
    if ST is not None:
        ST.put("sa_base", key, v)
    return v


def tsec_tree_layer(S, G, res, season):
    """v16.4: the trees standing on the line, whole, as a layer (v16.6: laid UNDER the analysis colours; v16.4-v16.5 over them): the line does not cut
    them (v16.3 outlined the cut crowns with a dashed box and washed them with the field). Each tree is the same
    picture as in the base drawing (its measured height and crown, leaf type, leaf state of the row's season).
    Returns (colour premultiplied (h, w, 3) uint8, alpha (h, w) uint8) or None."""
    if not G.get("crowns"):
        return None
    leaf, tag, pal = tsec_season_tag(season)
    key = fp("sa_trees", SA_VERSION, G["key"], round(res, 4), round(leaf, 3), pal)
    ST = S.store
    v = ST.get("sa_trees", key) if ST is not None else None
    if v is not None:
        return v
    W = int(math.ceil(G["L"] / res))
    H = int(math.ceil((G["zhi"] - G["zlo"]) / res))
    Lc = np.zeros((H, W, 3), np.float32)
    La = np.zeros((H, W), np.float32)
    trees = S.env["solids"][2]
    zhi = G["zhi"]
    for sc_, hw, z0, z1, kind, ti in G["crowns"]:
        t = trees[ti]
        zg = S.z_at(t["x"], t["y"])
        sp = sa_tree(kind, sc_ / res, (zhi - zg) / res, (zhi - (zg + t["lo"])) / res, (zhi - (zg + t["hi"])) / res,
                     t["r"] / res, int(abs(t["x"] * 7.31 + t["y"] * 3.17) * 10) % 2147483647,
                     leaf=leaf if kind == "tree" else 1.0, season=pal)
        if sp is None:
            continue
        xa, ya = max(0, sp.x0), max(0, sp.y0)
        xb, yb = min(W, sp.x0 + sp.w), min(H, sp.y0 + sp.h)
        if xb <= xa or yb <= ya:
            continue
        c = sp.c[ya - sp.y0:yb - sp.y0, xa - sp.x0:xb - sp.x0] * 0.92
        a = sp.a[ya - sp.y0:yb - sp.y0, xa - sp.x0:xb - sp.x0] * 0.92
        Lc[ya:yb, xa:xb] = Lc[ya:yb, xa:xb] * (1.0 - a)[..., None] + c
        La[ya:yb, xa:xb] = La[ya:yb, xa:xb] * (1.0 - a) + a
    v = ((np.clip(Lc, 0, 1) * 255 + 0.5).astype(np.uint8), (np.clip(La, 0, 1) * 255 + 0.5).astype(np.uint8))
    if ST is not None:
        ST.put("sa_trees", key, v)
    return v


def _tsec_grid(fld, cut=None):
    """The field as an array (columns x heights, NaN where not computed) with every column's lowest value carried down
    to the ground; empty columns (not computed at all) are flagged. v16.6: with cut (G["cut"]) a column standing in a
    cut building is not carried down below its roof: the colours at a wall's foot come from the open side alone
    (v16.5 blended them with the roof's value across the wall, which drew dark or pale wedges at the feet of walls)."""
    cols = fld["vals"]
    V = np.array([[np.nan if v is None else v for v in col] for col in cols], float)
    empty = np.all(~np.isfinite(V), axis=1)
    F_ = V.copy()
    inb = np.zeros(F_.shape[0], bool)
    if cut:
        cs = np.asarray(fld["s"], float)
        for c in cut:
            inb |= (cs > c[0]) & (cs < c[1])
    for j in range(F_.shape[0]):
        if inb[j]:
            continue
        row = F_[j]
        ok = np.isfinite(row)
        if ok.any():
            k0 = int(np.argmax(ok))
            row[:k0] = row[k0]
    return V, F_, empty


def _tsec_sample(fld, F_, s_px, z_px):
    """Bilinear values of the field at pixel centres (s along the line, z height); a missing neighbour is left out."""
    cs = np.asarray(fld["s"], float)
    nc = cs.size
    j = np.searchsorted(cs, s_px)
    j0 = np.clip(j - 1, 0, nc - 1)
    j1 = np.clip(j, 0, nc - 1)
    den = np.where(j1 > j0, cs[j1] - cs[j0], 1.0)
    t = np.where(j1 > j0, np.clip((s_px - cs[j0]) / den, 0.0, 1.0), 0.0)
    fk = (z_px - fld["zlo"]) / fld["dz"] - 0.5
    k0 = np.floor(fk).astype(np.int64)
    w = fk - k0
    nz = fld["nz"]
    k0c = np.clip(k0, 0, nz - 1)
    k1c = np.clip(k0 + 1, 0, nz - 1)
    w = np.where(k0 < 0, 0.0, np.where(k0 >= nz - 1, 1.0, w))
    out = np.zeros((z_px.size, s_px.size))
    wsum = np.zeros_like(out)
    for jj, wj in ((j0, 1.0 - t), (j1, t)):
        for kk, wk in ((k0c, 1.0 - w), (k1c, w)):
            v = F_[jj[None, :], kk[:, None]]
            ww = wj[None, :] * wk[:, None]
            ok = np.isfinite(v) & (ww > 0)
            out += np.where(ok, v * ww, 0.0)
            wsum += np.where(ok, ww, 0.0)
    return np.where(wsum > 1e-9, out / np.maximum(wsum, 1e-9), np.nan)


def _lut_apply(colour, V):
    """Colours (0..1) of values through a colour table made by lut_ramp, lut_classes or stops_table."""
    lut = colour._lut
    if lut[0] == "ramp":
        _, vmin, span, n, table = lut
        q = np.clip((np.nan_to_num((V - vmin) / span, nan=0.0, posinf=1.0, neginf=0.0) * (n - 1)).astype(np.int64), 0, n - 1)
        tab = np.asarray(table, float) / 255.0
    else:
        _, edges, cols = lut
        q = np.clip(np.searchsorted(np.asarray(edges, float), V, side="right"), 0, len(cols) - 1)
        tab = np.asarray(cols, float) / 255.0
    return tab[np.where(np.isfinite(V), q, 0)]


def _ground_np(G, s_px):
    gs = np.array([p[0] for p in G["ground"]], float)
    gz = np.array([p[1] for p in G["ground"]], float)
    return np.interp(s_px, gs, gz)


def tsec_compose(path, S, G, res, season, fld=None, colour=None, bands=None, rkey=None):
    """One row's picture: the base drawing, the field as a wash over the air (hatched where it was not computed), the
    surface bands. Kept when nothing it is made from changed. Returns (path, width m, height m)."""
    W = int(math.ceil(G["L"] / res))
    H = int(math.ceil((G["zhi"] - G["zlo"]) / res))
    out = (path, W * res, H * res)
    full = None
    if rkey is not None:
        full = fp("tsec_row", SA_VERSION, "trees under, v16.6", MV["render"], MV["sec_field"], rkey, colour._lut if colour else None, res, W, H,
                  G["key"], repr(season), bands_key(bands) if bands else None, TSEC_WASH)
        d_ = os.path.dirname(path)
        e_ = maps_index(S, d_).get(os.path.basename(path))
        try:
            if e_ and e_.get("key") == full and os.path.getsize(path) == e_.get("size"):
                S.env.setdefault("maps_kept", []).append(os.path.basename(path))
                return out
        except Exception:
            pass
    base = tsec_base(S, G, res, season)
    img = base.astype(np.float32) / 255.0
    H_, W_ = img.shape[:2]
    tl = tsec_tree_layer(S, G, res, season)               # v16.6: the trees on the line, whole, UNDER the colours
    if tl is not None:                                    # (v16.4-v16.5 laid them over the analysis)
        Lc, La = tl
        hh, ww = min(H_, La.shape[0]), min(W_, La.shape[1])
        a_ = La[:hh, :ww].astype(np.float32)[..., None] / 255.0
        img[:hh, :ww] = img[:hh, :ww] * (1.0 - a_) + Lc[:hh, :ww].astype(np.float32) / 255.0
    s_px = (np.arange(W_) + 0.5) * res
    z_px = G["zhi"] - (np.arange(H_) + 0.5) * res
    if fld is not None and colour is not None:
        V, F_, empty = _tsec_grid(fld, G["cut"])
        val = _tsec_sample(fld, F_, s_px, z_px)
        gz = _ground_np(G, s_px)
        air = z_px[:, None] > gz[None, :] - 0.3
        col = _lut_apply(colour, val).astype(np.float32)
        m = (air & np.isfinite(val)).astype(np.float32)[..., None] * TSEC_WASH
        img = img * (1.0 - m + m * col)                  # multiply: the drawing stays legible under the colours
        # not computed: a light hatch over the drawing
        cs = np.asarray(fld["s"], float)
        if empty.any():
            jj = np.clip(np.searchsorted(cs, s_px) - 1, 0, cs.size - 1)
            jn = np.clip(jj + 1, 0, cs.size - 1)
            nod = empty[jj] & empty[jn]
            if nod.any():
                yy, xx = np.mgrid[0:H_, 0:W_]
                hatch = ((xx + yy) % 9 < 1.2) & nod[None, :] & air
                img[hatch] = img[hatch] * 0.55 + np.float32(0.55) * 0.45
    if bands:
        tb_cols = None
        for s0, s1, z0, z1, v in bands:
            if v is None:
                continue
            c = np.asarray(_lut_apply(colour, np.array([v], float))[0], np.float32)
            a0, a1 = max(0, int(round(s0 / res))), min(W_, int(round(s1 / res)))
            p0, p1 = max(0, int(round((G["zhi"] - z1) / res))), min(H_, int(round((G["zhi"] - z0) / res)))
            if a1 <= a0:
                a1 = min(W_, a0 + 1)
            if p1 <= p0:
                p1 = min(H_, p0 + 1)
            img[p0:p1, a0:a1] = c
    png_write_np(path, (np.clip(img, 0, 1) * 255 + 0.5).astype(np.uint8))
    if full is not None:
        try:
            d_ = os.path.dirname(path)
            maps_index(S, d_)[os.path.basename(path)] = dict(key=full, size=os.path.getsize(path), w=W_, h=H_)
            maps_index_save(S, d_)
        except Exception:
            pass
    return (path, W_ * res, H_ * res)


def png_write_np(path, a):
    """An (h, w, 3) uint8 array to PNG, each row filtered with Paeth (smaller files for drawings with soft colours)."""
    h, w = a.shape[:2]
    x = a.reshape(h, w * 3).astype(np.int16)
    left = np.zeros_like(x)
    left[:, 3:] = x[:, :-3]
    up = np.zeros_like(x)
    up[1:] = x[:-1]
    ul = np.zeros_like(x)
    ul[1:, 3:] = x[:-1, :-3]
    p = left + up - ul
    pa, pb, pc = np.abs(p - left), np.abs(p - up), np.abs(p - ul)
    pred = np.where((pa <= pb) & (pa <= pc), left, np.where(pb <= pc, up, ul))
    f = ((x - pred) & 0xFF).astype(np.uint8)
    raw = np.concatenate([np.full((h, 1), 4, np.uint8), f], 1).tobytes()

    def chunk(t, d):
        return _struct.pack(">I", len(d)) + t + d + _struct.pack(">I", _zlib.crc32(t + d) & 0xffffffff)
    with open(path, "wb") as fo:
        fo.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", _struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0))
                 + chunk(b"IDAT", _zlib.compress(raw, 6)) + chunk(b"IEND", b""))


def tsec_season_tag(season):
    """Leaf share of deciduous crowns and the foliage palette for a row: a season key or a (month, day)."""
    if isinstance(season, tuple):
        m = season[0]
        pal = "spring" if m in (3, 4, 5) else ("autumn" if m in (9, 10, 11) else "")
        return sa_leaf_day(*season), "d%02d%02d" % season, pal
    return sa_leaf(season), str(season), (season if season in ("spring", "autumn") else "")


# ------------------------------------------------------------ contours of a field in the plane of a section
def sa_contours(fld, levels):
    """Polylines [(level, [(s, z), ...])] of the field at each level (marching squares on the computed points only)."""
    V, F_, empty = _tsec_grid(fld)
    cs = np.asarray(fld["s"], float)
    zs = fld["zlo"] + (np.arange(fld["nz"]) + 0.5) * fld["dz"]
    if V.shape[0] < 2 or V.shape[1] < 2:
        return []
    a, b, c, d = V[:-1, :-1], V[1:, :-1], V[1:, 1:], V[:-1, 1:]
    ok = np.isfinite(a) & np.isfinite(b) & np.isfinite(c) & np.isfinite(d)
    out = []
    for lev in levels:
        A, Bb, C, D = a > lev, b > lev, c > lev, d > lev
        case = (A * 1 + Bb * 2 + C * 4 + D * 8) * ok
        J, K = np.nonzero((case > 0) & (case < 15))
        if J.size == 0:
            continue
        segs = []

        def pt(edge, j, k):
            if edge == 0:            # bottom: (j, k) - (j + 1, k)
                v0, v1 = V[j, k], V[j + 1, k]
                t = (lev - v0) / (v1 - v0) if v1 != v0 else 0.5
                return ("h", j, k), (cs[j] + t * (cs[j + 1] - cs[j]), zs[k])
            if edge == 1:            # right: (j + 1, k) - (j + 1, k + 1)
                v0, v1 = V[j + 1, k], V[j + 1, k + 1]
                t = (lev - v0) / (v1 - v0) if v1 != v0 else 0.5
                return ("v", j + 1, k), (cs[j + 1], zs[k] + t * (zs[k + 1] - zs[k]))
            if edge == 2:            # top: (j, k + 1) - (j + 1, k + 1)
                v0, v1 = V[j, k + 1], V[j + 1, k + 1]
                t = (lev - v0) / (v1 - v0) if v1 != v0 else 0.5
                return ("h", j, k + 1), (cs[j] + t * (cs[j + 1] - cs[j]), zs[k + 1])
            v0, v1 = V[j, k], V[j, k + 1]                        # left
            t = (lev - v0) / (v1 - v0) if v1 != v0 else 0.5
            return ("v", j, k), (cs[j], zs[k] + t * (zs[k + 1] - zs[k]))
        TABLE = {1: ((3, 0),), 2: ((0, 1),), 3: ((3, 1),), 4: ((1, 2),), 6: ((0, 2),), 7: ((3, 2),), 8: ((2, 3),),
                 9: ((0, 2),), 11: ((1, 2),), 12: ((1, 3),), 13: ((0, 1),), 14: ((3, 0),)}
        for j, k in zip(J.tolist(), K.tolist()):
            cse = int(case[j, k])
            if cse in (5, 10):                                    # saddle: decided by the cell's mean
                mid = (V[j, k] + V[j + 1, k] + V[j + 1, k + 1] + V[j, k + 1]) / 4.0 > lev
                if cse == 5:
                    pairs = ((0, 1), (3, 2)) if mid else ((3, 0), (1, 2))
                else:
                    pairs = ((3, 0), (1, 2)) if mid else ((0, 1), (2, 3))
            else:
                pairs = TABLE[cse]
            for e0, e1 in pairs:
                segs.append((pt(e0, j, k), pt(e1, j, k)))
        # chain the segments through their shared edges
        adj = {}
        for i_, ((k0, p0), (k1, p1)) in enumerate(segs):
            adj.setdefault(k0, []).append(i_)
            adj.setdefault(k1, []).append(i_)
        used = [False] * len(segs)
        for i_ in range(len(segs)):
            if used[i_]:
                continue
            used[i_] = True
            (k0, p0), (k1, p1) = segs[i_]
            line = [p0, p1]
            for end in (1, 0):
                key = k1 if end == 1 else k0
                while True:
                    nxt = [q for q in adj.get(key, []) if not used[q]]
                    if not nxt:
                        break
                    q = nxt[0]
                    used[q] = True
                    (qa, pa), (qb, pb) = segs[q]
                    if qa == key:
                        key, p = qb, pb
                    else:
                        key, p = qa, pa
                    if end == 1:
                        line.append(p)
                    else:
                        line.insert(0, p)
            if len(line) >= 3:
                out.append((lev, line))
    return out


def _pl_len(P):
    return sum(math.hypot(P[i + 1][0] - P[i][0], P[i + 1][1] - P[i][1]) for i in range(len(P) - 1))


# ------------------------------------------------------------ the cut over the picture
TSEC_SOIL = (232, 228, 221)
TSEC_ROAD = (207, 204, 197)    # v16.7: = ROAD_FILL (v16.6: 204, 202, 198): the street surface band under the ground line of the technical sections
TSEC_WATER_LINE = (64, 120, 168)
TSEC_CONTOUR = (78, 78, 86)


def tsec_streets(S, G, step=0.25):
    """v16.6: the stretches of the line on a surveyed street surface (S.road_net, the same areas the plans hatch):
    [(s0, s1)], tested every `step` along the line. Kept per line and bake."""
    memo = env_memo(S)
    mk = ("tsec_streets", G["key"], step)
    r = memo.get(mk)
    if r is not None:
        return r
    net = getattr(S, "road_net", None) or []
    (x0, y0), ux, uy, Lm = G["a"], G["ux"], G["uy"], G["L"]
    n = int(Lm / step) + 1
    ss_ = [min(Lm, k * step) for k in range(n)]
    xs = [x0 + ux * s_ for s_ in ss_]
    ys = [y0 + uy * s_ for s_ in ss_]
    lb = (min(xs), min(ys), max(xs), max(ys))
    on = [False] * n
    for rg_ in net:
        P = rg_["P"]
        bx0, by0 = min(p[0] for p in P), min(p[1] for p in P)
        bx1, by1 = max(p[0] for p in P), max(p[1] for p in P)
        if bx1 < lb[0] or bx0 > lb[2] or by1 < lb[1] or by0 > lb[3]:
            continue
        for k in range(n):
            if on[k]:
                continue
            x_, y_ = xs[k], ys[k]
            if bx0 <= x_ <= bx1 and by0 <= y_ <= by1 and pip(x_, y_, P) and not any(pip(x_, y_, H) for H in rg_["H"]):
                on[k] = True
    out = []
    k = 0
    while k < n:
        if on[k]:
            j = k
            while j + 1 < n and on[j + 1]:
                j += 1
            out.append((max(0.0, ss_[k] - 0.5 * step), min(Lm, ss_[j] + 0.5 * step)))
            k = j + 1
        else:
            k += 1
    memo[mk] = out
    return out


def tsec_draw(S, B, G, x, ytop, ss, U, L, num, png=None, contours=None, fmt="{:g}"):
    """The cut over the row's picture: soil under the ground, the water at the bed, the cut buildings (white, a line at
    every storey), the ground line (broken inside the cut buildings), contours with their values, heights and distances.
    Returns the bottom y of the drawing."""
    zhi, zlo, Lm = G["zhi"], G["zlo"], G["L"]

    def P(s, z):
        return (x + s * ss, ytop - (zhi - z) * ss)
    ybot = P(0.0, zlo)[1]
    if png:
        B.image(png[0], x, ytop - png[2] * ss, x + png[1] * ss, ytop, L, 5)
    gp = [P(s, z) for s, z in G["ground"]]
    B.fill([gp + [P(Lm, zlo), P(0.0, zlo)]], TSEC_SOIL, L, 20)
    for a_, b_ in tsec_streets(S, G):                     # v16.6: the streets cut by the line, hatched as on the plans
        pts = [(a_, tsec_zg(G, a_))] + [(s, z) for s, z in G["ground"] if a_ < s < b_] + [(b_, tsec_zg(G, b_))]
        dd_ = max(SEC_ROAD_D, 0.2 * U / ss)               # a drawing convention, not a surveyed thickness
        band_ = [P(s, z) for s, z in pts] + [P(s, z - dd_) for s, z in reversed(pts)]
        B.fill([band_], TSEC_ROAD, L, 20)
        if not ROAD_SOLID:                                # v16.7: solid by default
            B.hatch([band_], mix(T_INK, TSEC_ROAD, 0.45), L, 21, SEC_ROAD_HATCH * U, w=0.03)
    for s0, s1, bed, lvl in G["water"]:
        # v16.5: the water hatched in blue at its depth, the channel above it in a pale wash, over the analysis
        draw_stream(B, L, P, G["ground"], s0, s1, bed, lvl, U, (226, 236, 244), (206, 224, 238), TSEC_WATER_LINE,
                    TSEC_WATER_LINE, 21, lw=0.03)
    bl = (S.env.get("solids") or ([], None, []))[0]
    spans = []
    tags_ = []
    for c in G["cut"]:
        s0, s1, base, top, bi = c[:5]
        zb = min([base] + [z for s, z in G["ground"] if s0 - 0.5 <= s <= s1 + 0.5])
        u = bl[bi]["u"] if isinstance(bi, int) and 0 <= bi < len(bl) else {}
        fl = int(u.get("floors") or 0)
        # v16.3: the generic silhouette of the building's type, faintly tinted by its use, over the white of the cut
        fab, cat_ = c[5], c[6]
        uf_ = unit_flags(u) if u else (False, False, False)
        ms_ = minaret_s(u, G["a"][0], G["a"][1], G["ux"], G["uy"], s0, s1) if (u and fab == "sacred") else None
        prof = bld_profile(fab, cat_, s0, s1, zb, base, top, fl or 1, u.get("floors_src") == "published",
                           seed=int(s0 * 7.0), ruin=uf_[2], minaret=ms_)
        tint = mix(typo_tone(fab, cat_), (255, 255, 255), 0.35)      # v16.4: the tone of its type
        lab_ = None
        tag_ = typo_label(fab, cat_, fl or 1, uf_[0], label_name(live_unit(S, u)))
        if not c[7] and (s1 - s0) * ss > 0.6 * tw(tag_, 0.17 * U):
            lab_ = tag_
        bld_draw_cut(B, L, P, prof, tint, T_INK, ss, U, order=22, roof_c=None, label=lab_, placed=tags_)
        spans.append((s0, s1))
    spans.sort()
    run = []

    def flush():
        if len(run) >= 2:
            B.line(list(run), T_INK, L, 26, 0.2)
        del run[:]
    prev_in = False
    for s, z in G["ground"]:
        sp_ = next(((a_, b_) for a_, b_ in spans if a_ < s < b_), None)
        if sp_ is not None:
            if not prev_in:
                run.append(P(sp_[0], tsec_zg(G, sp_[0])))
                flush()
            prev_in = True
            continue
        if prev_in:
            sp0 = max((b_ for a_, b_ in spans if b_ <= s), default=None)
            if sp0 is not None:
                run.append(P(sp0, tsec_zg(G, sp0)))
        prev_in = False
        run.append(P(s, z))
    flush()
    # v16.4: the trees on the line are not cut: they stand whole in the row's picture, over the analysis colours
    # (tsec_tree_layer); v16.3 outlined each cut crown with a dashed box here
    rl_ = draw_sec_roads(S, B, L, P, lambda s_: tsec_zg(G, s_), (G["a"][0], G["a"][1], G["b"][0], G["b"][1]), Lm, U,
                         order=28, w=0.4)                 # v25: the streets crossed, named over the ground
    placed_r = []
    for sm, zg_, txt in rl_:
        q = P(sm, zg_)
        half = 0.5 * tw(txt, 0.17 * U) + 0.1 * U
        tier = 0
        while any(t2 == tier and q[0] - half < r2 and l2 < q[0] + half for l2, r2, t2 in placed_r):
            tier += 1
        placed_r.append((q[0] - half, q[0] + half, tier))
        ty = q[1] + (0.55 + 0.32 * tier) * U
        B.line([(q[0], q[1] + 0.05 * U), (q[0], ty - 0.04 * U)], T_INK, L, 28, 0.03)
        B.fill([rect(q[0] - half, ty - 0.03 * U, q[0] + half, ty + 0.22 * U)], (255, 255, 255), L, 28)
        B.text(txt, q[0], ty, 0.17 * U, T_INK, L, order=29, align="C")
    if contours:
        placed = []
        for lev, line in contours:
            pts = [P(s, z) for s, z in line]
            B.line(pts, TSEC_CONTOUR, L, 24, 0.03)
            if _pl_len(line) * ss > 6.0 * U:
                k = len(pts) // 2
                px, py = pts[k]
                if all(math.hypot(px - qx, py - qy) > 3.0 * U for qx, qy in placed):
                    placed.append((px, py))
                    B.text(fmt.format(lev), px, py + 0.06 * U, 0.17 * U, (60, 60, 66), L, order=25, align="C")
    # heights on the left, distances below, the ends of the line
    step = nice_step(zhi - zlo, 4)
    zt = math.ceil(zlo / step) * step
    while zt <= zhi + 1e-9:
        q = P(0.0, zt)
        B.line([(q[0] - 0.18 * U, q[1]), (q[0] - 0.05 * U, q[1])], T_GREY, L, 29, 0.04)
        B.text("+%.0f" % zt, q[0] - 0.25 * U, q[1] - 0.09 * U, 0.2 * U, T_GREY, L, align="R")
        zt += step
    step = nice_step(Lm, 8)
    st = 0.0
    while st <= Lm + 1e-9:
        q = P(st, zlo)
        B.line([q, (q[0], q[1] - 0.15 * U)], T_GREY, L, 29, 0.04)
        B.text("%.0f" % st, q[0], q[1] - 0.48 * U, 0.2 * U, T_GREY, L, align="C")
        st += step
    for s_, lab in ((0.0, num), (Lm, num + "'")):
        q = P(s_, tsec_zg(G, s_))
        B.text(lab, q[0], q[1] + 0.55 * U, 0.34 * U, T_INK, L, font=FONT_TITLE, bold=True, align="C")
    return ybot - 0.62 * U


# ------------------------------------------------------------ the sheet: rows in one or two columns, legends under them
TSEC_ROW_TOP = 1.0       # page units above a drawing: the row's title line
TSEC_ROW_AXIS = 1.1      # under a drawing: its distances
TSEC_LEG_H = 3.2         # the legend under a row (one column: legend and note side by side; v16.3: 2.6 -> 3.2 for
                         # the shared scale drawn above a stretched bar)
TSEC_HTICK = 2.4         # left of a drawing: its heights


def tsec_layout(S, G, U, nrows, graph_h=0.0):
    """One or two columns of rows, whichever draws the line larger (one column unless two are clearly larger)."""
    W = (PW - 2 * PM) * U
    avail = (PH - 6.4 - 5.0 - 1.3) * U
    Hz = G["zhi"] - G["zlo"]
    cand = []
    for cols in (1, 2):
        rpc = (nrows + cols - 1) // cols
        cw = (W - (cols - 1) * 3.0 * U) / cols
        leg = (TSEC_LEG_H if cols == 1 else TSEC_LEG_H + 1.5) * U
        rowh = avail / rpc
        dh = rowh - (TSEC_ROW_TOP + TSEC_ROW_AXIS + 0.55) * U - leg - graph_h
        ss = min((cw - TSEC_HTICK * U) / G["L"], max(0.2 * U, dh) / Hz)
        cand.append(dict(ss=ss, cols=cols, rpc=rpc, cw=cw, rowh=rowh, leg=leg, graph_h=graph_h))
    one, two = cand
    # two columns when they draw the line clearly larger, or when one column would leave more than a third of the
    # sheet's width empty and two draw it nearly as large
    fill = (G["L"] * one["ss"] + TSEC_HTICK * U) / W
    best = two if nrows > 1 and (two["ss"] > one["ss"] * 1.12 or (fill < 0.66 and two["ss"] >= 0.9 * one["ss"])) else one
    # height a row has left once its drawing is as wide as it can be: a graph of the pedestrian level uses it
    left = best["rowh"] - (TSEC_ROW_TOP + TSEC_ROW_AXIS + 0.55) * U - best["leg"] - best["graph_h"] - Hz * best["ss"]
    if left > 1.9 * U:                                # ... no taller than the drawing above it (the drawing leads)
        best["graph_h"] += max(0.0, min(4.5 * U, left - 0.4 * U,
                                        max(2.4 * U, 1.1 * Hz * best["ss"]) - best["graph_h"]))
    return best


def tsec_profile_graph(B, G, U, L, pts, lo, hi, unit, colour, caption, dec=VAL_DEC, trend=None):
    """A row's graph: the value along the line at one height above the ground, as a coloured ribbon."""
    q = nice_step(hi - lo, 14)

    def colour_q(v):                                  # one colour per legend step: fewer, calmer ribbon pieces
        return colour(round(v / q) * q)

    def graph(x, ytop, w, h):
        if h < 1.2 * U or not any(p_[1] is not None for p_ in pts):
            return
        tsec_graph(B, x, ytop, w, h, G["L"], [(pts, T_INK, 0.06)], lo, hi, U, L, unit, colour=colour_q, dec=dec,
                   trend=trend)
        cap = caption
        if trend:
            cap += " · blue line: the mean over {:g} m of line".format(trend)
        if any(len(p_) > 2 and p_[2] for p_ in pts):    # v38: keywords (was a clause)
            cap += " · dashed on grey: same height above the cut roof"
        B.text(cap, x + w - 0.15 * U, ytop - 0.32 * U, 0.2 * U, T_GREY, L, align="R")
    return graph


def tsec_sheet(S, B, X, Y, U, rects, num, title, subtitle, sources, G, lab, rows, lay):
    """One sheet of a technical section: its rows (the periods) at one true scale, each with its title, the drawing,
    its legend and a note; key plan in the header."""
    L = "LU_TECH::Sections"
    B.begin("TECHNICAL %s · %s" % (num, title), "LU_TECH")
    ref_scale = ""
    if isinstance(sources, (list, tuple)):             # v38: the scale note joins the sheet's numbered key
        sources = list(sources) + ["True scale: heights in m above sea level; {} = start of the line, {}' = end (key "
                                   "plan, top right); trees at their modelled size and leaf state, figures for "
                                   "scale.".format(lab, lab)]
        ref_scale = " [{}]".format(len(sources))
    top, bottom = tech_frame(S, B, X, Y, U, num, title, subtitle, sources)
    x0, W = X + PM * U, (PW - 2 * PM) * U
    kpw = min(18.0 * U, 4.0 * U * S.F.w / S.F.h)
    tsec_key_plan(S, B, x0 + W - kpw, Y - 1.6 * U, kpw, G, lab, U, L, S.env["tech_dir"])
    ss = lay["ss"]
    dwm = G["L"] * ss
    for i, row in enumerate(rows):
        c, r = i % lay["cols"], i // lay["cols"]              # left to right, then down
        cx = x0 + c * (lay["cw"] + 3.0 * U)
        y = top - r * lay["rowh"]
        dx = cx + TSEC_HTICK * U
        hd = row["head"]
        h1 = 0.4 * U
        need = tw(hd, h1, kind_of(FONT_TITLE))
        B.fit(hd, cx, y, h1, lay["cw"], T_INK, L, font=FONT_TITLE, bold=True)
        if row.get("sub") and need + 1.0 * U < lay["cw"] - 4.0 * U:
            B.fit(row["sub"], cx + need + 0.8 * U, y, 0.22 * U, lay["cw"] - need - 0.8 * U, T_GREY, L)
        ytop = y - TSEC_ROW_TOP * U
        yb = tsec_draw(S, B, G, dx, ytop, ss, U, L, lab, row.get("png"), contours=row.get("contours"),
                       fmt=row.get("cfmt", "{:g}"))
        if row.get("over"):
            row["over"](dx, ytop, ss)
        yy = yb - 0.1 * U
        if lay["graph_h"] > 0.0 and row.get("graph"):
            row["graph"](dx, yy, dwm, lay["graph_h"] - 0.45 * U)
            yy -= lay["graph_h"]
        if row.get("legend"):
            yy -= 0.4 * U
            if lay["cols"] == 1:
                lw = min(40.0 * U, max(26.0 * U, 0.45 * dwm))
                ly = row["legend"](dx, yy - 0.15 * U, lw)
                if row.get("note"):
                    nx_ = dx + lw + 2.0 * U
                    if isinstance(row["note"], list):     # v38: the row's readings as tiles beside its legend
                        vis_tiles(B, nx_, yy - 0.3 * U, min(x0 + W - nx_, 12.0 * U * len(row["note"])), row["note"], U,
                                  L, h=max(0.5, min(1.0, (lay["leg"] - 0.3 * U) / (1.9 * U))))
                    else:
                        B.para_fit(row["note"] + ".", nx_, yy - 0.3 * U, x0 + W - nx_, 0.25 * U, yy - lay["leg"], T_INK, L)
            else:
                lw = lay["cw"] - TSEC_HTICK * U
                ly = row["legend"](dx, yy - 0.15 * U, lw)
                if row.get("note"):
                    if isinstance(row["note"], list):     # v38: the row's readings as tiles under its legend
                        vis_tiles(B, dx, ly - 0.08 * U, lw, row["note"], U, L,
                                  h=max(0.5, min(1.0, (ly - 0.08 * U - (yy - lay["leg"])) / (1.9 * U))))
                    else:
                        B.para_fit(row["note"] + ".", dx, ly - 0.08 * U, lw, 0.23 * U, yy - lay["leg"], T_INK, L)
    sb = nice_floor(G["L"] / 5.0)
    draw_scalebar(B, x0 + W - sb * ss - 1.2 * U, bottom + 0.05 * U, ss, sb, U, L, h=0.26)
    B.fit("TRUE SCALE · m a.s.l. · {0} start, {0}' end (key plan){1}".format(lab, ref_scale), x0, bottom + 0.15 * U,
          0.24 * U, W * 0.7, T_GREY, L)                   # v38: keywords; the sentence is in the key
    rects.append(("%s · %s" % (num, title), (X, Y - PH * U, X + PW * U, Y)))


TSEC_SLOT = 2.0          # m: a slot narrower than this between two cut buildings is bridged by the roof line (v16.3)


def tsec_at_height_all(fld, cols, h, cut=None):
    """Per column: (s, value, on_roof). Outside the cut buildings the value h metres above the ground or water; over a
    cut building the value h metres above its roof (the plan shows a building by its roof), flagged True (v16.3: the
    graph under a section no longer breaks where the line crosses a house). With cut (G["cut"]), the columns in a slot
    narrower than TSEC_SLOT between two cut buildings (party-wall gaps, light wells, which the plan's grid does not
    resolve) are left out, so the roof line runs across instead of spiking to the bottom of the slot."""
    slots = []
    if cut:
        sp = sorted((c[0], c[1]) for c in cut)
        slots = [(a[1], b[0]) for a, b in zip(sp, sp[1:]) if 0.0 < b[0] - a[1] < TSEC_SLOT]
    out = []
    for i, c in enumerate(cols):
        if c[5] is not None:
            out.append((c[0], tsec_at(fld, i, c[5] + h), True))
        elif not any(e_ <= c[0] <= b_ for e_, b_ in slots):
            out.append((c[0], tsec_at(fld, i, c[4] + h), False))
    return out


def tsec_at_height(fld, cols, h):
    """Per column outside the cut buildings: (s, value h metres above the ground or water)."""
    out = []
    for i, c in enumerate(cols):
        if c[5] is not None:
            continue
        out.append((c[0], tsec_at(fld, i, c[4] + h)))
    return out


def tsec_facades(fld, cols):
    """Values in front of the cut facades, from the ground up to the roof."""
    out = []
    for i, c in enumerate(cols):
        if c[6] is None:
            continue
        for kz, v in enumerate(fld["vals"][i]):
            z = fld["zlo"] + (kz + 0.5) * fld["dz"]
            if v is not None and z <= c[6]:
                out.append(v)
    return out


def db_rng(vals):
    """A range of levels as the plan shows them: below 35 dB(A) is "< 35"."""
    vals = [v for v in vals if v is not None]
    if not vals:
        return "-"
    lo, hi = min(vals), max(vals)
    f = lambda v: "< 35" if v < 35.0 else "{:.2f}".format(v)           # v16.6: 2 decimals
    return f(lo) if f(lo) == f(hi) else (f(lo) + "–" + f(hi))


def tsec_rng(vals, fmt="{:.2f}"):           # v16.6: 2 decimals (v16.5: 0)
    vals = [v for v in vals if v is not None]
    if not vals:
        return "-"
    lo, hi = min(vals), max(vals)
    return fmt.format(lo) if fmt.format(lo) == fmt.format(hi) else (fmt.format(lo) + "–" + fmt.format(hi))


def tsec_name(num, what):
    return "%s_%s.png" % (num.replace(".", "_"), what)


def tsec_comfort_scales(S, lines):
    """Wind and temperature scales shared by every wind, air and felt section: the plan's, widened to what the
    sections reach (the colours stay tied to the same m/s and °C as on the plan)."""
    sc_ = comfort_scales(S)
    wmax, (lo, hi) = sc_["w_max"], sc_["t_range"]
    ws, ts = [], []
    for key in ("wind_sections", "air_sections", "felt_sections"):
        for k, a, b in lines.get(key, []):
            G = tsec_geom(S, a, b)
            cf = tsec_comfort(S, G)
            for sd in SEASONS:
                c = cf["seasons"][sd["key"]]
                if key == "wind_sections":
                    ws += [v for col in c["wind"] for v in col if v is not None]
                elif key == "air_sections":
                    ts += [v for col in c["ta"] for v in col if v is not None]
                else:
                    ts += [v for col in c["utci"] for v in col if v is not None]
    if ws:
        wmax = max(wmax, math.ceil(max(ws) * KT / 2.0) * 2.0 / KT)
    if ts:
        lo, hi = min(lo, 5.0 * math.floor(min(ts) / 5.0)), max(hi, 5.0 * math.ceil(max(ts) / 5.0))
    return wmax, lo, hi


# ------------------------------------------------------------ the seven technical section sheets (v16.2 layout)
def tsec_sheet_sound(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    res_ = tsec_noise(S, G)
    cols = tsec_cols(S, G, TSEC_DS_SOUND)
    edges = [35, 40, 45, 50, 55, 60, 65, 70, 75, 80]
    lut = lut_classes(edges, noise_pal())
    labels = ["< 35"] + ["%d-%d" % (edges[k], edges[k + 1]) for k in range(len(edges) - 1)] + ["> 80"]
    nm = S.env["noise"]
    rk = fp(G["key"], S.env["keys"]["noise_raw"], nm.get("offset", 0.0), TSEC_DS_SOUND, TSEC_DZ_SOUND)
    lay = tsec_layout(S, G, U, 4)
    res = tsec_px_res(G, lay["ss"])
    rows = []
    for key, head, sub, thr in (("lden", "Lden · DAY-EVENING-NIGHT LEVEL", "the weighted 24-hour level", 53.0),
                                ("day", "Ld · DAY 06-18", "", None), ("evening", "Le · EVENING 18-22", "", None),
                                ("night", "Ln · NIGHT 22-06", "", 45.0)):
        fld = dict(res_, vals=res_["vals"][key])
        png = tsec_compose(os.path.join(d, tsec_name(num, "sound_" + key)), S, G, res, "year", fld=fld, colour=lut,
                           rkey=fp(rk, key))
        f4 = [v for s_, v in tsec_at_height(fld, cols, 4.0) if v is not None]
        fa = tsec_facades(fld, cols)
        allv = [v for col in fld["vals"] for v in col if v is not None]
        if not allv:                                      # v38: the row's readings as tiles (were a sentence)
            txt = [("sound", "NO ROAD WITHIN 300 m", "not computed", "[3]")]
        else:
            txt = [("sound", "4 m ABOVE THE GROUND", "{} dB(A)".format(db_rng(f4)), "[2]"),
                   ("build", "IN FRONT OF CUT FACADES", "{} dB(A)".format(db_rng(fa)), "[2]")]
            if thr:
                txt.append(("limit", "AIR ABOVE WHO {:.0f} dB".format(thr), "{:.0f} %".format(
                    100.0 * sum(1 for v in allv if v > thr) / max(1, len(allv))), "[6]"))
            if any(all(v is None for v in col) for col in fld["vals"]):
                txt.append(("dot", "HATCHED", "not computed", "[3]"))

        def legend(x, y, w):
            return tech_bands(B, x, y, w, noise_pal(), labels, U, L, h=0.19, title="dB(A) · the bands of the plan (T1)")
        rows.append(dict(head=head, sub=sub, png=png, legend=legend, note=txt,
                         contours=sa_contours(fld, [55.0, 65.0, 75.0]) if allv else None, cfmt="{:.0f} dB",
                         graph=tsec_profile_graph(B, G, U, L, tsec_at_height_all(fld, cols, 4.0, G["cut"]), 35.0, 80.0, "", lut,
                                                  "dB(A) at 4 m above the ground")))
    cal = ("calibrated with {} measurements ({:+.1f} dB)".format(nm["n_meas"], nm["offset"]) if nm.get("n_meas")
           else "not yet calibrated with measurements")
    tsec_sheet(S, B, X, Y, U, rects, num, "SOUND · SECTION " + lab,
               "Lden · Ld · Le · Ln dB(A) · ground to above the roofs [1]",
               ["The plan's model (T1) at every receiver of the plane: RLS-90 emission of the counted road, segment method with "
                "distance, air, ground and screening by the surveyed buildings (ISO 9613-2 path difference over the most "
                "effective roof in each of 36 directions, and round the two sides of its block).",
                "Receivers every {:.1f} m along the line and in front of every cut "
                "facade, {:.0f} m apart in height, from 0.5 m above the ground or water; above a roof that roof screens "
                "too.".format(TSEC_DS_SOUND, TSEC_DZ_SOUND),
                "Sound model {}. Cut buildings are the analysis prisms; contours at 55, 65 and 75 dB(A). Hatched: no "
                "counted road within 300 m, not computed.".format(cal),
                traffic_note(S), height_note(S),
                "WHO Environmental Noise Guidelines (2018), as on T1: 53 dB Lden, 45 dB at night."], G, lab, rows, lay)


def tsec_sheet_heat(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    gh = 2.0 * U
    lay = tsec_layout(S, G, U, 4, graph_h=gh)
    ss = lay["ss"]
    res = tsec_px_res(G, ss)
    band = max(0.3 * U / ss, 2.0 * res)
    rows = []
    for sd in SEASONS:
        key = sd["key"]
        r = heat_scale(S, key)
        prof = tsec_heat(S, G, key)
        L_ = S.env["lst"].get(key, {})
        when = L_.get("datetime_utc", "")
        if not r or not prof:
            rows.append(dict(head="{} · no clear Landsat scene".format(sd["name"])))
            continue
        _, med, vmin, vmax = r
        lut = lut_ramp(vmin, vmax, TECH_PAL["heat"])
        bands = [(s_ - 0.5, s_ + 0.5, z_, z_ + band, v_) for s_, z_, v_, roof in prof]
        try:
            day = (int(when[5:7]), int(when[8:10]))
        except Exception:
            day = key
        png = tsec_compose(os.path.join(d, tsec_name(num, "surface_heat_" + key)), S, G, res, day, colour=lut,
                           bands=bands, rkey=fp(G["key"], S.env["E_fp"], key, band))
        pts = [(s_, v_) for s_, z_, v_, roof in prof]
        roofs = [v_ for s_, z_, v_, roof in prof if roof and v_ is not None]
        wat = [v_ for s_, z_, v_, roof in prof if v_ is not None and not roof and
               any(w0 <= s_ <= w1 for w0, w1, bed, lvl in G["water"])]
        grd = [v_ for s_, z_, v_, roof in prof if v_ is not None and not roof and
               not any(w0 <= s_ <= w1 for w0, w1, bed, lvl in G["water"])]
        txt = [("heat", "ALONG THE LINE", "{} °C".format(tsec_rng([v for s_, v in pts], "{:.2f}")), "[1]")]   # v38: tiles
        for ic_, nm_, vv in (("roof", "ROOFS · MEAN", roofs), ("ground", "OPEN GROUND · MEAN", grd),
                             ("water", "WATER · MEAN", wat)):
            if vv:
                txt.append((ic_, nm_, "{:.2f} °C".format(sum(vv) / len(vv)), "[1]"))

        def legend(x, y, w, vmin=vmin, vmax=vmax, med=med):
            return tech_colorbar(B, x, y, w, TECH_PAL["heat"], vmin, vmax, U, L,
                                 title="Surface temperature °C, the plan's scale (white = {:.2f} °C)".format(med))

        def graph(x, ytop, w, h, pts=pts, vmin=vmin, vmax=vmax, lut=lut):
            tsec_graph(B, x, ytop, w, h, G["L"], [(pts, T_INK, 0.06)], vmin, vmax, U, L, "°", colour=lut)
        if L_.get("n_scenes"):                       # the seasonal mean of every clear scene (as on the plan, T2)
            head = "{} · MEAN OF {} CLEAR LANDSAT SCENES".format(sd["name"], L_["n_scenes"])
            sub = "{} to {} · {} UTC · read the trend [2]".format(
                L_.get("first", ""), L_.get("last", ""), L_.get("utc_mean", ""))
        else:                                        # one scene (environment data of v1)
            head = "{} · LANDSAT {} · {}".format(sd["name"], L_.get("scene", "")[3:4], when[:10])
            sub = "scene {} UTC · read the trend [2]".format(when[11:16])
        rows.append(dict(head=head, sub=sub, png=png, legend=legend, note=txt, graph=graph))
    multi = any(v.get("n_scenes") for v in S.env["lst"].values())
    tsec_sheet(S, B, X, Y, U, rects, num, "SURFACE HEAT · SECTION " + lab,
               "LST °C · ground, roofs, water under the line · " +
               ("seasonal mean" if multi else "one scene a season") + " [1]",
               ["Landsat 8/9 Collection 2 Level-2 surface temperature (USGS), band 10, " +
                ("the seasonal means of the plan (T2): every scene of 2021-2026 with at least 95 % of the area clear, each "
                 "cell averaged over the scenes that saw it clear; " if multi else "the scenes of the plan (T2), ") +
                "sampled every metre along the line (bilinear in the 30 m grid): on the roof where the line crosses a "
                "building, else on the ground or water.",
                "The band on each surface carries its value; the graph below repeats "
                "it. Thermal pixels are 100 m: read the trend, not single roofs. Surface temperature is not air temperature.",
                ("Deciduous crowns are drawn in leaf for the share of the season's days they are in leaf." if multi else
                 "Deciduous crowns are drawn as they were on the scene's day.")], G, lab, rows, lay)


def tsec_sheet_shade(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    sh = tsec_shade(S, G)
    cols = tsec_cols(S, G, TSEC_DS_SHADE)
    lay = tsec_layout(S, G, U, 5)
    res = tsec_px_res(G, lay["ss"])
    rows = []
    items = [(sd["key"], sd["event"].upper(), sh["days"][sd["key"]], sd["day"]) for sd in SEASONS]
    items.append(("year", "THE MEAN DAY OF THE YEAR · ALL 365 DAYS", sh["year"], "year"))
    for key, head, se, day in items:
        n, cols_, edges = shade_scale(se["daylight"])
        # v16.3: the plan's class colours blended continuously (each class colour at its middle hour). With hard one-hour
        # classes, the sky's terrain shade, which hovers within minutes of a whole hour along the line, jumped between
        # two classes from column to column and read as full-height stripes; the values themselves are unchanged
        stops_ = [(k + 0.5, cols_[k]) for k in range(n)]
        lut = stops_table(stops_, 0.0, float(n))
        fld = dict(zlo=sh["zlo"], dz=sh["dz"], nz=sh["nz"], s=sh["s"], vals=se["vals"])
        png = tsec_compose(os.path.join(d, tsec_name(num, "shade_" + key)), S, G, res, day, fld=fld, colour=lut,
                           rkey=fp(G["key"], S.env["keys"]["solids"], key, TSEC_DS_SHADE, TSEC_DZ_SHADE, SUN_BINS))
        g0 = [v for s_, v in tsec_at_height(fld, cols, 0.5) if v is not None]
        g10 = [v for s_, v in tsec_at_height(fld, cols, 10.0) if v is not None]
        fa = tsec_facades(fld, cols)
        txt = [("shade", "GROUND 0.5 m · MEAN SHADE", "{} h".format(fmt_h(sum(g0) / len(g0)) if g0 else "-"), "[1]"),
               ("clock", "LINE SHADED > HALF THE DAY", "{:.0f} %".format(
                   100.0 * sum(1 for v in g0 if v >= se["daylight"] / 2.0) / max(1, len(g0))), "[1]")]   # v38: tiles
        if g10:
            txt.append(("shade", "10 m UP · MEAN", "{} h".format(fmt_h(sum(g10) / len(g10))), "[1]"))
        if fa:
            txt.append(("build", "IN FRONT OF CUT FACADES", "{}-{} h".format(fmt_h(min(fa)), fmt_h(max(fa))), "[1]"))

        def legend(x, y, w, stops_=stops_, n=n, lut=lut):
            return stretch_bar(B, x, y, w, stops_, 0.0, float(n), (lut, 0.0, float(n), 1.0), U, L,
                               "Hours in shade · T3 classes, blended [3]", th=0.22, dec=0)
        if key == "year":                            # v38: keywords
            sub = "all 365 days averaged · {} h daylight on the mean day [1]".format(fmt_h(se["daylight"]))
        else:
            sub = "sun up {}-{} local · {} h · every minute [1]".format(fmt_h(se["sunrise"]), fmt_h(se["sunset"]),
                                                                       fmt_h(se["daylight"]))
        half = se["daylight"] / 2.0
        rows.append(dict(head=head, sub=sub, png=png, legend=legend, note=txt,
                         contours=sa_contours(fld, [half]), cfmt="half the daylight",
                         graph=tsec_profile_graph(B, G, U, L, tsec_at_height_all(fld, cols, 0.5, G["cut"]), 0.0, se["daylight"], " h",
                                                  lut, "hours in shade at 0.5 m above the ground", dec=0,
                                                  trend=TSEC_TREND)))
    tsec_sheet(S, B, X, Y, U, rects, num, "SHADE · SECTION " + lab,
               "Hours in shade · every point of the plane · key days + year [1]",
               ["Every minute the sun is up (NOAA sun position, UTC+3), as on the plan (T3), at every point of the plane "
                "({:g} m along the line, {:g} m in height).".format(TSEC_DS_SHADE, TSEC_DZ_SHADE),
                "Casters: the exact obstruction of each point for every degree of sun "
               "azimuth by every building (its roof over the surveyed ground, concave footprints and courtyards included), "
               "the 3D tree crowns (canopy height map, modelled heights; olives 15 %, others in leaf 3 %, bare 46 % of the sun passes; deciduous ones in leaf "
               "from {} to {}, drawn bare or in leaf as on each day), the terrain horizon (PVGIS DEM, as seen from the "
               "ground; above the ground lowered by how much the terrain's horizon falls with height: the survey terrain "
               "inside the frame and the PVGIS DEM heights of the 100 m grid out to its edge, the terrain beyond taken as "
               "far) and, near the ground, the slope's own plane. The "
               "stream channel's walls are not casters.".format(*leaf_dates()),
                "The contour marks half the day's daylight in shade. Colours: the "
                "plan's one-hour classes blended between whole hours, so minutes either side of an hour do not jump a "
                "class.", height_note(S)], G, lab, rows, lay)


def rad_graph_hi(S, edges):
    """v16.5: the top of every solar section graph: the plan's 99.9th percentile over the four seasons (kWh/m2 per day,
    rounded up to 0.5), at least the top class edge."""
    rd = S.env["rad"]
    v = np.concatenate([np.asarray(rd["seasons"][sd["key"]]["kwh"], float).ravel() for sd in SEASONS])
    v = v[np.isfinite(v)]
    top = float(np.percentile(v, 99.9)) if v.size else edges[-1]
    return math.ceil(max(top, edges[-1]) * 2.0) / 2.0


def tsec_sheet_solar(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    so = tsec_solar(S, G)
    gh = 2.0 * U
    lay = tsec_layout(S, G, U, 4, graph_h=gh)
    ss = lay["ss"]
    res = tsec_px_res(G, ss)
    band = max(0.3 * U / ss, 2.0 * res)
    edges = rad_scale(S)
    cols_ = ramp_hex(TECH_PAL["rad"], len(edges) + 1)
    lut = lut_classes(edges, cols_)
    labels = ["< %.2f" % edges[0]] + ["%.2f-%.2f" % (edges[i], edges[i + 1]) for i in range(len(edges) - 1)] + ["> %.2f" % edges[-1]]
    months = {"spring": "MARCH-MAY", "summer": "JUNE-AUGUST", "autumn": "SEPTEMBER-NOVEMBER", "winter": "DECEMBER-FEBRUARY"}
    rows = []
    for sd in SEASONS:
        key = sd["key"]
        bands = [(p0, p1, z_, z_ + band, v[key]) for p0, p1, z_, v in so["ground"]]
        bands += [(a_, b_, top, top + band, v[key]) for a_, b_, top, v in so["roofs"]]
        bands += [((s_w - band, s_w) if side_ < 0 else (s_w, s_w + band)) + (z0, z1, v[key])
                  for s_w, z0, z1, side_, nrm, v in so["walls"]]
        png = tsec_compose(os.path.join(d, tsec_name(num, "solar_" + key)), S, G, res, key, colour=lut, bands=bands,
                           rkey=fp(G["key"], S.env["keys"]["solids"], key, band, edges, SUN_BINS))
        gpts = [(0.5 * (p0 + p1), v[key]) for p0, p1, z_, v in so["ground"]]
        # v16.4: the graph follows the top surface along the line, as the plan sees it: the ground where the line is in
        # the open, the roof (dashed, over a grey mark) where it crosses a cut building, joined at the walls. v16.3 drew
        # the ground alone, broken at every building, and the roofs as a separate red step line over it
        # the ground in a slot narrower than TSEC_SLOT between two cut buildings (a party-wall gap the plan's grid does not
        # resolve either) is left out of the graph, as in the other sections: the roof line runs across
        sp_ = sorted((c[0], c[1]) for c in G["cut"])
        slots_ = [(p[1], q[0]) for p, q in zip(sp_, sp_[1:]) if 0.0 < q[0] - p[1] < TSEC_SLOT]
        tpts = [(s_, v_, False) for s_, v_ in gpts if not any(e_ <= s_ <= f_ for e_, f_ in slots_)] + \
            [(0.5 * (a_ + b_), v[key], True) for a_, b_, top, v in so["roofs"]]
        gv = [v for s_, v in gpts]
        rv = [v[key] for a_, b_, top, v in so["roofs"]]
        wv = [v[key] for s_w, z0, z1, side_, nrm, v in so["walls"]]
        txt = []                                      # v38: the means as tiles, kWh/m2 per day (were a sentence)
        for ic_, nm_, vv in (("ground", "GROUND · kWh/m²·day", gv), ("roof", "ROOFS · kWh/m²·day", rv),
                             ("build", "CUT FACADES · MEAN", wv)):
            if vv:
                txt.append((ic_, nm_, "{:.2f}".format(sum(vv) / len(vv)), "[1]"))
        if wv:
            txt.append(("build", "FACADES · RANGE", "{:.2f}–{:.2f}".format(min(wv), max(wv)), "[1]"))
        # v16.5: one graph range for every solar section and season (0 to the plan's highest value), so the graphs
        # compare (v16.4: each row from its own lowest to highest value)
        lo_, hi_ = 0.0, rad_graph_hi(S, edges)

        def legend(x, y, w):
            return tech_bands(B, x, y, w, cols_, labels, U, L, h=0.17, title="kWh/m² per day · the classes of the plan (T4)")

        def graph(x, ytop, w, h, tpts=tpts, lo_=lo_, hi_=hi_):
            tsec_graph(B, x, ytop, w, h, G["L"], [(tpts, T_INK, 0.06)], lo_, hi_, U, L, "", colour=lut, trend=TSEC_TREND)
            B.text("kWh/m²·day top surface · dashed: roof · blue: {:g} m mean [2]".format(TSEC_TREND),
                   x + w - 0.15 * U, ytop - 0.32 * U, 0.2 * U, T_GREY, L, align="R")       # v38: keywords
        rows.append(dict(head="{} · {} · {} DAYS".format(sd["name"], months[key], days_in_season(key)),
                         sub="bands: ground, roofs, cut facades · graph: top surface [2]",
                         png=png, legend=legend, note=txt, graph=graph))
    tsec_sheet(S, B, X, Y, U, rects, num, "SOLAR RADIATION · SECTION " + lab,
               "kWh/m² per day · season means · ground, roofs, cut facades [1]",
               ["The plan's model (T4) at the surfaces of the section: every hour of the PVGIS-SARAH2 typical year with the "
               "sun at its exact position, each point (ground and roofs evenly every {:g} m, the ground on the surveyed "
               "slope, cut facades in bands of at most {:g} m) with its own exact 3D obstruction by buildings, crowns and terrain for "
               "every degree of sun azimuth, its cosine-weighted sky (72 sectors, its own plane hiding the sky behind it), "
               "the Perez horizon band and ground reflection (albedo 0.2).".format(TSEC_DS_SOLAR, TSEC_DZ_SOLAR),
                "Bands on the ground, the roofs and the cut facades. Graph: kWh/m² per day on the top surface along the "
                "line: the ground, and the roof where the line crosses a building (dashed over a grey mark); blue line: "
                "the mean over {:g} m of line.".format(TSEC_TREND)], G, lab, rows, lay)


def tsec_wind_arrows(B, G, x, ytop, ss, U, L, fld, cols, u_in, scale):
    """Arrows of the wind's component in the plane (length by speed) on a coarse grid of the open air."""
    zhi, Lm = G["zhi"], G["L"]
    if abs(u_in) < 0.12:
        return
    nx_ = max(4, int(Lm * ss / (3.2 * U)))
    for q in range(nx_):
        s_ = Lm * (q + 0.5) / nx_
        i = min(range(len(cols)), key=lambda j: abs(cols[j][0] - s_))
        c = cols[i]
        base = c[4] if c[5] is None else c[5]
        for hz in (2.0, 9.0, 18.0, 30.0):
            z = base + hz
            if z > zhi - 2.0:
                break
            v = tsec_at(fld, i, z)
            if v is None:
                continue
            ln = min(2.6 * U, max(0.35 * U, v * abs(u_in) * scale))
            dx = ln if u_in > 0 else -ln
            px, py = x + c[0] * ss - dx / 2.0, ytop - (zhi - z) * ss
            col = (40, 52, 78)
            B.line([(px, py), (px + dx, py)], col, L, 30, 0.07)
            hx_ = 0.2 * U * (1 if dx > 0 else -1)
            B.fill([[(px + dx, py), (px + dx - hx_, py + 0.1 * U), (px + dx - hx_ * 0.75, py), (px + dx - hx_, py - 0.1 * U)]],
                   col, L, 30)


def tsec_sheet_wind(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    wmax = ctx["wmax"]
    cols = tsec_cols(S, G, TSEC_DS)
    E = S.env["E"]
    CP = Compass(E["location"]["lon"], E["location"]["lat"])
    CF = S.env["comfort"]
    cf = tsec_comfort(S, G)
    lay = tsec_layout(S, G, U, 4)
    res = tsec_px_res(G, lay["ss"])
    rows = []
    for sd in SEASONS:
        key = sd["key"]
        c = cf["seasons"][key]
        fld = dict(zlo=cf["zlo"], dz=cf["dz"], nz=cf["nz"], s=cf["s"], vals=c["wind"])
        sc = stretch_scale(WINDY_WIND, 0.0, WIND_SCALE_HI, c["wind"], to=WIND_STRETCH_TO, ab=analysis_window(S, "wind"))
        lut = sc[0]
        png = tsec_compose(os.path.join(d, tsec_name(num, "wind_" + key)), S, G, res, key, fld=fld, colour=lut,
                           rkey=fp(G["key"], S.env["keys"]["comfort"], key, "wind", TSEC_DS, TSEC_DZ, wmax))
        dir_from, share = prevailing(CF["seasons"][key])
        wv = CP.vec((dir_from + 180.0) % 360.0)            # where the prevailing wind blows to
        u_in = wv[0] * G["ux"] + wv[1] * G["uy"]
        u_x = wv[0] * (-G["uy"]) + wv[1] * G["ux"]         # + = away from the viewer (into the page)
        ang = math.degrees(math.acos(min(1.0, abs(u_in))))
        how = []
        if abs(u_in) >= 0.12:
            how.append("towards {}{}".format(lab, "'" if u_in > 0 else ""))
        if abs(u_x) >= 0.12:
            how.append("into the page" if u_x > 0 else "out of the page")
        w15 = [v for s_, v in tsec_at_height(fld, cols, 1.5) if v is not None]
        w10 = [v for s_, v in tsec_at_height(fld, cols, 10.0) if v is not None]
        open15 = (c["u10_mean"] or 0.0) * PED_WIND
        shel = 100.0 * sum(1 for v in w15 if v < 0.5 * open15) / max(1, len(w15))
        txt = [("wind", "1.5 m ABOVE THE GROUND", "{} m/s".format(tsec_rng(w15, "{:.2f}")), "[6]"),     # v38: tiles
               ("build", "SHELTERED < HALF OPEN", "{:.0f} %".format(shel), "[6]"),
               ("wind", "OPEN GROUND · 1.5 m", "{:.2f} m/s".format(open15), "[6]"),
               ("wind", "10 m UP", "{} m/s".format(tsec_rng(w10, "{:.2f}")), "[6]")]

        def legend(x, y, w, sc=sc, vv=c["wind"]):
            return stretch_bar(B, x, y, w, WINDY_WIND, 0.0, WIND_SCALE_HI, sc, U, L,
                               "kt · mean · Windy colours 0-{:.0f} m/s, as T5".format(
                                   WIND_SCALE_HI), k=KT, th=0.22, vals=vv)

        def over(x, ytop, ss, fld=fld, u_in=u_in):
            tsec_wind_arrows(B, G, x, ytop, ss, U, L, fld, cols, u_in, 0.45 * U)
        step = 0.5 if wmax <= 4.0 else 1.0
        rows.append(dict(head="{} · MEAN OF {:,} HOURS · MOSTLY FROM {} · {:.2f} m/s AT 10 m".format(
            sd["name"], c["hours"], TSEC_NAMES16[int(round(dir_from / 22.5)) % 16], c["u10_mean"] or 0.0),
            sub="wind {:.0f}° to the line · {} · {:.0f} % of hours [6]".format(ang, " and ".join(how) or "along the line",
                                                                             100.0 * share),
            png=png, legend=legend, note=txt, over=over,
            contours=sa_contours(fld, stretch_levels(sc, [step * k for k in range(1, int(wmax / step) + 1)])),
            cfmt="{:.2f} m/s",
            graph=tsec_profile_graph(B, G, U, L, tsec_at_height_all(fld, cols, 1.5, G["cut"]), sc[1], sc[2], "", lut,
                                     "m/s at 1.5 m above the ground")))
    tsec_sheet(S, B, X, Y, U, rects, num, "WIND · SECTION " + lab,
               "Wind m/s · every height · season mean · Windy [6]",
               comfort_sources(S) + [
                   "Every hour's 10 m wind brought to each height above the ground with the log law (z0 "
                   "0.1 m) and reduced behind every building and crown upwind within 300 m by the windbreak wake curves of the "
                   "plan (Heisler & DeWalle 1988), each obstacle counted with its height above that point's level (height above "
                   "ground - 1.5 m), at its exact distance along that hour's wind (10-degree sectors); then averaged. At 1.5 m "
                   "this is the plan's wind (T5). An estimate of shelter, not CFD. Colour = speed, after Windy; the prevailing "
                   "wind's angle to the line and its share of the hours; arrows: its part in the plane."], G, lab, rows, lay)


def tsec_sheet_air(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    lo, hi = ctx["tlo"], ctx["thi"]
    cf = tsec_comfort(S, G)
    cols = tsec_cols(S, G, TSEC_DS)
    lay = tsec_layout(S, G, U, 4)
    res = tsec_px_res(G, lay["ss"])
    rows = []
    for sd in SEASONS:
        key = sd["key"]
        c = cf["seasons"][key]
        fld = dict(zlo=cf["zlo"], dz=cf["dz"], nz=cf["nz"], s=cf["s"], vals=c["ta"])
        sc = stretch_scale(WINDY_TEMP, lo, hi, c["ta"], ab=analysis_window(S, "ta"))
        lut = sc[0]
        png = tsec_compose(os.path.join(d, tsec_name(num, "air_temperature_" + key)), S, G, res, key, fld=fld, colour=lut,
                           rkey=fp(G["key"], S.env["keys"]["comfort"], key, "ta", TSEC_DS, TSEC_DZ, lo, hi))
        vals = [(v, fld["zlo"] + (kz + 0.5) * fld["dz"]) for col in fld["vals"] for kz, v in enumerate(col) if v is not None]
        vmin, vmax = min(vals), max(vals)
        txt = [("air", "HIGHEST POINT · +{:.0f} m".format(vmin[1]), "{:.2f} °C".format(vmin[0]), "[6]"),     # v38: tiles
               ("air", "LOWEST POINT · +{:.0f} m".format(vmax[1]), "{:.2f} °C".format(vmax[0]), "[6]")]

        def legend(x, y, w, sc=sc, vv=c["ta"]):
            return stretch_bar(B, x, y, w, WINDY_TEMP, lo, hi, sc, U, L, "°C · the scale of T6 and T7", th=0.22, vals=vv)
        lv = [round(v * 4.0) / 4.0 for v in np.arange(math.floor(vmin[0] * 4) / 4.0, vmax[0] + 0.25, 0.25)]
        lv = stretch_levels(sc, [v for v in lv if vmin[0] < v < vmax[0]][::2])
        rows.append(dict(head="{} · MEAN OF {:,} HOURS · AIR {:.2f} °C · RH {:.0f} %".format(
            sd["name"], c["hours"], c["ta_mean"] or 0.0, c["rh_mean"] or 0.0),
            sub="dry bulb 2 m · PVGIS point elevation {:.0f} m [6]".format(CLIMATE["elevation"]),
            png=png, legend=legend, note=txt, contours=sa_contours(fld, lv),
            cfmt="{:.2f} °C",
            graph=tsec_profile_graph(B, G, U, L, tsec_at_height_all(fld, cols, 2.0, G["cut"]), sc[1], sc[2], "°", lut,
                                     "°C at 2 m above the ground")))
    tsec_sheet(S, B, X, Y, U, rects, num, "AIR TEMPERATURE · SECTION " + lab,
               "Dry bulb °C · every height · season mean · Windy [6]",
               comfort_sources(S) + [
                   "Dry bulb from the PVGIS climate data (ERA5-Land 2 m air temperature of its grid cell, "
                   "whose ground height is not reported; taken at PVGIS's point elevation, {:.0f} m, an assumption), carried to every "
                   "height of the plane with the standard lapse rate (-0.65 K per 100 m), as on the plan (T6); colours after "
                   "Windy's temperature scale. The air is the same along the line, only height changes it.".format(
                       CLIMATE["elevation"]),
                   "Street-scale differences (shade, water, traffic, night inversions) are not modelled."],
               G, lab, rows, lay)


def tsec_sheet_felt(S, B, X, Y, U, rects, d, G, lab, num, ctx):
    L = "LU_TECH::Sections"
    lo, hi = ctx["tlo"], ctx["thi"]
    cols = tsec_cols(S, G, TSEC_DS)
    cf = tsec_comfort(S, G)
    lay = tsec_layout(S, G, U, 4)
    res = tsec_px_res(G, lay["ss"])
    rows = []
    for sd in SEASONS:
        key = sd["key"]
        c = cf["seasons"][key]
        fld = dict(zlo=cf["zlo"], dz=cf["dz"], nz=cf["nz"], s=cf["s"], vals=c["utci"])
        fsun = dict(fld, vals=c["sun"])
        sc = stretch_scale(WINDY_TEMP, lo, hi, c["utci"], ab=analysis_window(S, "utci"))
        lut = sc[0]
        png = tsec_compose(os.path.join(d, tsec_name(num, "felt_temperature_" + key)), S, G, res, key, fld=fld, colour=lut,
                           rkey=fp(G["key"], S.env["keys"]["comfort"], key, "utci", TSEC_DS, TSEC_DZ, lo, hi))
        u15pts = tsec_at_height(fld, cols, 1.5)
        u15 = [v for s_, v in u15pts if v is not None]
        f15 = [v for s_, v in tsec_at_height(fsun, cols, 1.5) if v is not None]
        fa = tsec_facades(fld, cols)
        txt = [("felt", "1.5 m ABOVE THE GROUND", "{} °C".format(tsec_rng(u15)), "[6]"),           # v38: tiles
               ("felt", "1.5 m · MEAN", "{:.2f} °C".format(sum(u15) / max(1, len(u15))), "[6]"),
               ("sun", "IN DIRECT SUN · SUNNY h", "{:.0f} %".format(100.0 * sum(f15) / max(1, len(f15))), "[6]")]
        if fa:
            txt.append(("build", "IN FRONT OF CUT FACADES", "{} °C".format(tsec_rng(fa)), "[6]"))

        def legend(x, y, w, sc=sc, vv=c["utci"]):
            yy = stretch_bar(B, x, y, w, WINDY_TEMP, lo, hi, sc, U, L, "UTCI °C, mean over the hours · the scale of T6 and T7", vals=vv,
                             th=0.22)
            return utci_band_marks(B, x, yy + 0.1 * U, w, sc[1], sc[2], U, L)
        thr = [t for t, nm_ in UTCI_STRESS if lo < t < hi]
        rows.append(dict(head="{} · MEAN OF {:,} HOURS · AIR {:.2f} °C".format(sd["name"], c["hours"], c["ta_mean"] or 0.0),
                         sub="air + humidity + wind + sun / shade + sky [6]",
                         png=png, legend=legend, note=txt, contours=sa_contours(fld, thr), cfmt="UTCI {:.2f} °C",
                         graph=tsec_profile_graph(B, G, U, L, tsec_at_height_all(fld, cols, 1.5, G["cut"]), sc[1], sc[2], "°", lut,
                                                  "UTCI °C at 1.5 m above the ground")))
    tsec_sheet(S, B, X, Y, U, rects, num, "FELT TEMPERATURE · SECTION " + lab,
               "UTCI °C · felt · every point of the plane · season mean [6]",
               comfort_sources(S) + ["What a person feels at each point: air, humidity, local wind, sun or shade and the sky "
               "it sees. UTCI (Broede et al. 2012) every hour at every point of the plane, then averaged: air "
               "with the lapse rate, that hour's wind as on the wind section (brought to the 10 m reference UTCI expects), "
               "mean radiant temperature from SolarCal (ASHRAE 55, outdoor form as in Ladybug) with that point's sun or "
               "shade in that hour (exact 3D obstruction) and its sky view (72 sectors through buildings, crowns and "
               "terrain), albedo 0.25 and the sky's long-wave radiation; as on the plan (T7). Contours: the UTCI stress "
               "category limits."], G, lab, rows, lay)


TSEC_SHEETS = {"sound_sections": tsec_sheet_sound, "heat_sections": tsec_sheet_heat, "shade_sections": tsec_sheet_shade,
               "solar_sections": tsec_sheet_solar, "wind_sections": tsec_sheet_wind, "air_sections": tsec_sheet_air,
               "felt_sections": tsec_sheet_felt}


def build_tech_sections(S, B, X, Y, U, rects, d):
    """Sheets of the technical sections, each under the plan sheet of its analysis (one row per line)."""
    lines = tsec_lines(S)
    if not any(lines.values()):
        return 0
    import time as _t
    t0 = _t.time()
    ctx = {}
    if S.env.get("comfort") and any(lines.get(k) for k in ("wind_sections", "air_sections", "felt_sections")):
        ctx["wmax"], ctx["tlo"], ctx["thi"] = tsec_comfort_scales(S, lines)
    step = (PW + 6.0) * U
    vstep = (PH + 6.0) * U
    made = 0
    for ci, (key, num, title) in enumerate(TSEC_DEF):
        if key in ("wind_sections", "air_sections", "felt_sections") and not S.env.get("comfort"):
            if lines.get(key):
                LOG.append("WARNING: {} need the wind and temperature analysis, which did not run.".format(key))
            continue
        for j, (k, a, b) in enumerate(lines.get(key, [])):
            G = tsec_geom(S, a, b)
            TSEC_SHEETS[key](S, B, X + ci * step, Y - (j + 1) * vstep, U, rects, d, G, str(k + 1), "%s.%d" % (num, k + 1), ctx)
            made += 1
    LOG.append("Technical sections: {} sheets (below the plan sheet of each analysis).".format(made))
    return made


def build_technical(S, B, X, Y, U, rects):
    if not getattr(S, "env", None):
        if HAVE_NP:
            LOG.append("WARNING: technical sheets need the environment data (env_path).")
        return
    d = tech_dir()
    S.env["tech_dir"] = d
    step = (PW + 6.0) * U
    try:
        tsec_noise_start(S)                              # v17: the sound sections run while the sheets are made
    except Exception as ex:
        S.env["tsec_noise_pre"] = {}
        LOG.append("Sound sections: not started early ({}); computed in turn.".format(ex))
    try:
        tsec_prefetch(S, U)                              # v18: the section drawings on the workers meanwhile
    except Exception as ex:
        S.env["sa_pre"] = {}
        LOG.append("Section drawings: not started early ({}); made in turn.".format(ex))
    sheet_sound(S, B, X, Y, U, rects, d)
    sheet_heat(S, B, X + step, Y, U, rects, d)
    sheet_shade(S, B, X + 2 * step, Y, U, rects, d)
    sheet_radiation(S, B, X + 3 * step, Y, U, rects, d)
    if S.env.get("comfort"):
        sheet_wind(S, B, X + 4 * step, Y, U, rects, d)
        sheet_air(S, B, X + 5 * step, Y, U, rects, d)
        sheet_felt(S, B, X + 6 * step, Y, U, rects, d)
        if S.env["comfort"].get("year"):
            sheet_comfort_year(S, B, X + 7 * step, Y, U, rects, d)
    try:
        S.env["n_tsec"] = build_tech_sections(S, B, X, Y, U, rects, d)
    finally:
        S.env["sa_pre"] = {}                                          # v18: none kept for a later run
        for pre in (S.env.get("tsec_noise_pre") or {}).values():      # v17: no worker left running
            if "h" in pre["job"] and "out" not in pre["job"]:
                _noise_par_stop(pre["job"]["h"])
                pre["job"]["out"] = None
    LOG.append("Technical maps written to " + d)


def tech_report(S):
    out = ["Frame {:.0f} x {:.0f} m{} - technical analyses only".format(
        S.F.w, S.F.h, "" if getattr(S, "frame_src", "survey") == "input" else " (the " + S.frame_src + ")"
        if getattr(S, "frame_src", "").startswith("analysis range") else " (the whole survey in the file)")]
    if getattr(S, "env", None):
        out.append("{} tree crowns; shade: the four key days and the mean day of the year, every minute; solar radiation: "
                   "mean kWh/m2 per day of each season from every hour of the typical year".format(len(S.env["solids"][2])))
        cf = S.env.get("comfort")
        if cf:
            out.append("Wind, air and felt temperature: means over {} of each season (input hours)".format(cf["label"]))
        if S.env.get("n_tsec"):
            out.append("Technical sections: {} sheets".format(S.env["n_tsec"]))
        out.append("Maps: " + S.env.get("tech_dir", ""))
    out.append(height_note(S))
    out.append(traffic_note(S))
    out.append(street_note(S) + " " + channel_note(S) + ".")
    return "\n".join(out)


# ============================================================ SECTION STRIPS (after the attached references)
SEC_POCHE = mix(KHAKI, PAPER, 0.62)
SEC_WALL = mix(INK, BG, 0.12)
SEC_CROWN = mix(TREE_COLS["tree"], PAPER, 0.15)       # a crown as measured on the canopy height map
SEC_PAVE = mix(C("BC6F45"), BG, 0.12)
SEC_ROAD_D = 0.6          # v16.5: depth of the street surface band under the ground line (m; v16.4: 0.4), drawing only
SEC_ROAD_HATCH = 0.07     # v16.5: its hatch, page units (U) between the lines
SURFACE = {"transport": mix(INK2, BG, 0.3), "void": mix(KHAKI, INK, 0.14), "green": CAT["green"][1],
           "agri": CAT["agri"][1], "vacant": CAT["vacant"][1]}


def fade(col, t):
    return mix(col, BG, max(0.0, min(1.0, t)))


# ------------------------------------------------------------ buildings in section
# A cut building is its measured volume: footprint cut by the line, from the ground to its height, tinted by use (or
# by fabric type for monuments and mosques), with a thin line at every storey of its floor count. Nothing the survey
# does not record (roof forms, openings, balconies) is drawn.
SEC_CHANNEL = mix(CAT["water"][1], PAPER, 0.5)        # v16.4: the stream channel's ground colour in section ...
SEC_CHANNEL_HATCH = C("3E7DAE")                      # ... and its blue hatch


def channel_polys(ground, a, b, pad=4.0, top=None, bank=None, lim=None):
    """v16.4: the stream channel in section: the area between the cut ground (the bed, carved from the surveyed bed
    levels) and the top of the lower bank, around the water span a..b (m along the line). The bank tops are the
    ground just outside the span; where the ground rises above that level the channel ends. Returns [[(s, z)...]].
    v50 (MIRAQUA 28 Oct, bank depth REPORT §4 1a): bank = the bank top given (the lower crest, or the DSİ walls'
    top) in place of the ground just outside, lim = (s0, s1) the stretch of the cut it is taken within (the crests)."""
    gs = [p[0] for p in ground]

    def g_at(s):
        k = max(0, min(len(ground) - 1, _bisect_right(gs, s) - 1))
        k1 = min(len(ground) - 1, k + 1)
        (sa_, za), (sb_, zb) = ground[k], ground[k1]
        return za if sb_ <= sa_ else za + (zb - za) * (s - sa_) / (sb_ - sa_)
    zt = min(g_at(max(gs[0], a - 1.0)), g_at(min(gs[-1], b + 1.0))) if bank is None else bank
    if top is not None:                                   # v16.5: up to the water surface instead
        zt = min(zt, top)
    lo, hi = (a - pad, b + pad) if lim is None else lim
    pts = [(s, z) for s, z in ground if lo <= s <= hi]
    out = []
    run = None
    for k, (s1, z1) in enumerate(pts):
        if z1 < zt:
            if run is None:                               # entering the channel: where the ground drops below zt
                if k == 0:
                    run = [(s1, zt)]
                else:
                    s0, z0 = pts[k - 1]
                    run = [(s0 + (s1 - s0) * (zt - z0) / (z1 - z0), zt)]
            run.append((s1, z1))
        elif run is not None:                             # leaving it
            s0, z0 = pts[k - 1]
            run.append((s0 + (s1 - s0) * (zt - z0) / (z1 - z0), zt))
            out.append(run)
            run = None
    if run is not None:
        run.append((run[-1][0], zt))
        out.append(run)
    return [p for p in out if len(p) >= 3 and p[0][0] < b and p[-1][0] > a]


def draw_channel(B, L, P, polys, U, fill, hatch, order, lw=0.035, spacing=0.16):
    """v16.4: the stream channel filled pale blue and hatched in blue (45°), in page coordinates through P; hatch None:
    the fill alone."""
    for poly in polys:
        Q = [P(s, z) for s, z in poly]
        B.fill([Q], fill, L, order)
        if hatch is not None:
            for seg in hatch_segments([Q], spacing * U, math.radians(45.0)):
                B.line(seg, hatch, L, order + 1, lw)


def draw_stream(B, L, P, ground, a, b, bed, lvl, U, wash, fill, hatch, line_c, order, lw=0.035, bank=None, lim=None):
    """v16.5: the stream in section: the channel from the bed to the lower bank top in a pale wash, the water from the
    bed to its surface (lvl) filled and hatched in blue, the water line on top. Without water (lvl at the bed) the
    channel itself is hatched, as in v16.4, and the bed drawn as a blue line. v50: bank, lim as channel_polys."""
    if lvl - bed > 0.005:
        draw_channel(B, L, P, channel_polys(ground, a, b, bank=bank, lim=lim), U, wash, None, order)
        wp = channel_polys(ground, a, b, top=lvl, bank=bank, lim=lim)
        draw_channel(B, L, P, wp, U, fill, hatch, order + 1, lw=lw, spacing=0.08)
        for poly in wp:                               # the water line, over the ground line, so a thin layer still reads
            B.line([P(poly[0][0], lvl), P(poly[-1][0], lvl)], line_c, L, order + 6, 0.35)
    else:
        draw_channel(B, L, P, channel_polys(ground, a, b, bank=bank, lim=lim), U, fill, hatch, order, lw=lw)
        B.line([P(a, bed), P(b, bed)], line_c, L, order + 5, 0.4)


def draw_crown(B, L, P, s, zg, hw, lo, hi, col, order):
    """A tree in section at its measured size: trunk to the crown base, crown from lo to hi, hw wide each side."""
    x0, y0 = P(s, zg)
    xb, yb = P(s, zg + lo)
    B.line([(x0, y0), (xb, yb)], fade(INK2, 0.25), L, order, 0.05)
    cx, cy = P(s, zg + (lo + hi) / 2.0)
    rx = abs(P(s + hw, 0)[0] - P(s, 0)[0])
    ry = abs(P(0, (hi - lo) / 2.0)[1] - P(0, 0)[1])
    if rx > 0 and ry > 0:
        B.fill([ellipse_pts(cx, cy, rx, ry, 20)], col, L, order + 1)


# ============================================================ BOARD SECTIONS v16.2: the lively drawing behind the cut
SEC_SOIL = mix(KHAKI, PAPER, 0.42)                   # the cut ground, a shade darker than the page
SA_STYLE_BOARD = dict(bg=BG, ground=mix(SEC_POCHE, BG, 0.25), ground_edge=mix(INK2, BG, 0.55), bld=FAINT,
                      bld_edge=mix(INK2, BG, 0.3), storey=mix(INK2, BG, 0.62), fade_to=BG, tree_alpha=0.88,
                      tree_wash=0.0, tree_fade0=0.04, people=mix(INK2, BG, 0.1), bridge=mix(INK2, BG, 0.35))


def sa_board_bld(bo):
    """A building beyond the cut in the tone of its type (v16.4; v16.3 tinted it by use, so the old town and the
    planned low-rise houses, both homes, looked alike)."""
    return mix(typo_tone(bo.get("fabric", "regular"), bo.get("cat", "residential")), BG, 0.32 + (0.1 if bo.get("annex") else 0.0))


def sa_env_key(S):
    E_fp = ((getattr(S, "env", None) or {}).get("E_fp"))
    if E_fp:
        return E_fp
    try:
        st = os.stat(ENV_PATH)
        return fp(os.path.basename(ENV_PATH), st.st_size, int(st.st_mtime))
    except Exception:
        return None


def sec_px_res(Lm, ss):
    """Metres per pixel for a board section drawn at ss (model units per metre): TSEC_DPI at the printed size."""
    mm_per_m = ss * MMU
    res = 25.4 / (TSEC_DPI * max(1e-6, mm_per_m))
    return round(max(0.06, min(0.6, max(res, Lm / 6000.0))), 4)


def sa_index(S, d):
    """Which section picture was drawn from what (its own index file: the board may run without the technical sheets)."""
    memo = getattr(S, "_sa_index", None)
    if memo is None:
        memo = S._sa_index = {}
    idx = memo.get(d)
    if idx is None:
        try:
            with open(os.path.join(d, ".selinus_section_art_index.json"), "r", encoding="utf-8") as f:
                idx = json.load(f)
        except Exception:
            idx = {}
        memo[d] = idx
    return idx


def sa_index_save(S, d):
    try:
        with open(os.path.join(d, ".selinus_section_art_index.json"), "w", encoding="utf-8") as f:
            json.dump(sa_index(S, d), f)
    except Exception:
        pass


def sec_art_png(S, sd_, ss, tag):
    """The picture behind a board section (or one part of it): ground, buildings and trees beyond the cut, the trees cut
    by it and scale figures, on the page's colour (white for a separate drawing). Kept when nothing it is made from
    changed. Returns (path, zlo, zhi) or None."""
    if not HAVE_NP:
        return None
    x0, y0, x1, y1, nm = sd_["line"]
    a, b = (x0, y0), (x1, y1)
    base = sd_["base"]
    Lm = sd_["L"]
    off = sd_.get("s_off", 0.0)
    k, n = sd_.get("part", (1, 1))
    zlo, zhi = base - 3.0, base + sd_["zmax"] + 1.0
    res = sec_px_res(Lm, ss)
    style = dict(SA_STYLE_BOARD)
    if tag != "page":
        style.update(bg=(255, 255, 255), fade_to=(255, 255, 255))
    d = tech_dir()
    path = os.path.join(d, "section_%s%s_%s.png" % (nm, "" if n == 1 else "_%dof%d" % (k, n), tag))
    pr = site_prints(S)
    full = fp("sec_art", SA_VERSION, a, b, off, Lm, res, round(zlo, 3), round(zhi, 3), pr["bld"], pr["terrain"],
              pr["frame"], sa_env_key(S), style["bg"])
    e_ = sa_index(S, d).get(os.path.basename(path))
    try:
        if e_ and e_.get("key") == full and os.path.getsize(path) == e_.get("size"):
            return (path, zlo, zhi)
    except Exception:
        pass
    sc = sa_scene(S, a, b)
    ground = [(s_ + off, z + base) for s_, z in sd_["ground"]]
    art, r_ = sa_render(S, sc, off, off + Lm, zlo, zhi, res, style, leaf=1.0, season="", ground=ground,
                        bld_col=sa_board_bld)
    png_write_np(path, art.to_bytes())
    try:
        sa_index(S, d)[os.path.basename(path)] = dict(key=full, size=os.path.getsize(path), w=art.W, h=art.H)
        sa_index_save(S, d)
    except Exception:
        pass
    return (path, zlo, zhi)


SEC_CALL_H = 0.6        # v40: the callouts' text height (page units): >= 7.5 pt when the booklet crops a section


def sec_callouts(B, L, P, calls, ytop, U, lh=None, xlo=None, xhi=None):
    """v40: callouts [(s, z, text)] in rows under a section from ytop down: each word on the first row where it
    clears the others (kept between xlo and xhi, still over its leader), a leader from its point on the drawing to
    its top, broken where it passes a word of a row above. Returns the lowest baseline."""
    lh = (lh or SEC_CALL_H) * U
    step = lh + 0.4 * U
    calls = sorted(calls, key=lambda c: (c[0], c[2]))
    base_y = ytop - lh
    low = base_y
    placed = []                                          # (left, right, tier) of every callout
    for s, zf, txt in calls:
        fx = P(s, zf)[0]
        half = 0.5 * tw(txt, lh)
        cx = fx
        if xlo is not None:
            cx = max(cx, min(fx + half - 0.3 * U, xlo + half))
        if xhi is not None:
            cx = min(cx, max(fx - half + 0.3 * U, xhi - half))
        tier = 0                                         # the first row where the text is clear of the others
        gap = max(0.6 * U, 2.2 * lh)                     # v44: two characters' width between words on one row
        while any(t2 == tier and cx - half < r2 + gap and l2 - gap < cx + half for l2, r2, t2 in placed):
            tier += 1
        placed.append((cx - half, cx + half, tier))
    for (s, zf, txt), (l1, r1, tier) in zip(calls, placed):
        fx, fy = P(s, zf)
        ly = base_y - tier * step
        cuts = sorted((base_y - t2 * step - 0.12 * U, base_y - t2 * step + lh + 0.12 * U)
                      for l2, r2, t2 in placed if t2 < tier and l2 - 0.15 * U < fx < r2 + 0.15 * U)
        ytop_ = fy
        for c0, c1 in reversed(cuts):
            if c1 < ytop_:
                B.line([(fx, ytop_), (fx, c1)], INK2, L, 35, 0.035)
            ytop_ = min(ytop_, c0)
        if ly + lh + 0.12 * U < ytop_:
            B.line([(fx, ytop_), (fx, ly + lh + 0.12 * U)], INK2, L, 35, 0.035)
        B.fill([circle_pts(fx, fy, 0.09 * U, 8)], INK2, L, 35)
        B.text(txt, 0.5 * (l1 + r1), ly, lh, INK, L, align="C")
        low = min(low, ly)
    return low


def sec_cut(B, L, sd_, P, Lm, ss, U, dry=False):
    """v40 (was inside draw_section_strip): what the section cuts, drawn through P (s, z) -> page: the ground in a
    light poche with its surface materials and a fine ground line, the stream, the channel walls, the surveyed walls,
    the cut buildings by type with a line at every storey; without the picture behind, the measured crowns."""
    # ---- the ground: light poche, a surface of materials, a fine ground line
    prof = [P(a, b) for a, b in sd_["ground"]]
    B.fill([prof + [P(Lm, -3.0), P(0.0, -3.0)]], SEC_SOIL, L, 20)
    wat = [(a, b) for a, b, _, _ in sd_["water"]]
    for a, b, cat in sd_["strip"]:
        col = SURFACE.get(cat)
        if col is None:
            continue
        if cat in ("transport", "void") and any(a < wb + 8.0 and b > wa - 8.0 for wa, wb in wat):
            col = SEC_PAVE
        pts = [(s, z) for s, z in sd_["ground"] if a <= s <= b]
        if len(pts) >= 2:
            band_ = [P(s, z) for s, z in pts] + [P(s, z - SEC_ROAD_D) for s, z in reversed(pts)]
            if cat == "transport" and col is not SEC_PAVE and ROAD_SOLID:
                col = ROAD_FILL                           # v16.7: the street in the plans' solid street colour
            B.fill([band_], col, L, 21)
            if cat == "transport" and col is not SEC_PAVE and not ROAD_SOLID:   # v16.5 hatch, kept as an option
                B.hatch([band_], mix(INK, col, 0.45), L, 22, SEC_ROAD_HATCH * U, w=0.03)
    spans = sorted((a, b) for a, b, z0, z1, cat, annex, ftype, fl, floors, fsrc in sd_["bld"])
    run = []
    for s, z in sd_["ground"]:                           # the ground line, broken inside the cut buildings
        if any(a_ + 0.01 < s < b_ - 0.01 for a_, b_ in spans):
            if len(run) >= 2:
                B.line(run, INK, L, 26, 0.22)
            run = []
            continue
        run.append(P(s, z))
    if len(run) >= 2:
        B.line(run, INK, L, 26, 0.22)
    bks = sd_.get("banks") or []
    for kw_, (a, b, bed, lvl) in enumerate(sd_["water"]):
        # v16.5: the water hatched in blue at its depth (approximate unless measured), the channel above it in a pale
        # wash (v16.4: the whole channel hatched, up to the lower bank top); v50 (MIRAQUA 28 Oct, bank depth REPORT
        # §4 1a-1b): up to the lower bank crest, or the DSİ walls' top in the walled town reach
        zt_, lim_ = site28_channel_top(sd_, bks[kw_] if kw_ < len(bks) else None, a, b)
        draw_stream(B, L, P, sd_["ground"], a, b, bed, lvl, U, mix(CAT["water"][1], PAPER, 0.72), SEC_CHANNEL,
                    SEC_CHANNEL_HATCH, SEC_CHANNEL_HATCH, 22, bank=zt_, lim=lim_)
    for s, zb, zt in sd_.get("chwalls", []):
        r0, r1 = P(s - 0.3, zb), P(s + 0.3, zt)
        B.fill([rect(r0[0], r0[1], r1[0], r1[1])], SEC_WALL, L, 27)
    for s, zg in sd_["walls"]:                           # a surveyed wall: its place on the ground, no height
        bx, by = P(s, zg)
        B.fill([[(bx, by + 0.16 * U), (bx - 0.11 * U, by), (bx + 0.11 * U, by)]], SEC_WALL, L, 28)
    # ---- cut buildings: the volume to its height, a line at every storey
    tags_ = []
    th_ = site28_sec_sizes(sd_, U)[2] if sd_.get("_txt") else None   # v50 (F12): the tags at the cut's minor size
    for a, b, z0, z1, cat, annex, ftype, fl, floors, fsrc in sd_["bld"]:
        r0, r1 = P(a, z0), P(b, z1)
        if b - a < 1.2:
            B.fill([rect(r0[0], r0[1], r1[0], r1[1])], SEC_WALL, L, 28)
            continue
        heritage = ftype in ("monument", "sacred")
        # v16.4: the cut building in the tone of its TYPE (old town ochre, planned low-rise pale render, blocks cool
        # grey ...); its use stays in the ribbon under the section and in its tag
        room = mix(typo_tone(ftype, cat), PAPER, 0.12 + (0.15 if annex else 0.0))
        wall_c = mix(FABRIC[ftype][2], INK, 0.45) if heritage else INK
        # the generic silhouette of the building's type over its measured volume (eaves at its height)
        prof = bld_profile(ftype, cat, a, b, z0, z0, z1, floors, fsrc == "published", seed=int(a * 7.0), ruin=fl[2],
                           minaret=fl[3] if len(fl) > 3 else None)
        tag_ = typo_label(ftype, cat, floors, fl[0], fl[4] if len(fl) > 4 else "")
        if tag_.endswith(u" fl"):                         # revision 30 Oct (G6): its height in m, never floors
            tag_ = tag_.rsplit(u" · ", 1)[0] + u" · " + u_height(z1 - z0)
        if th_ is None:
            lab_ = tag_ if (not annex and (b - a) * ss > 0.6 * tw(tag_, 0.17 * U)) else None
            bld_draw_cut(B, L, P, prof, room, wall_c, ss, U, order=27, label=lab_, placed=tags_)
            continue
        bld_draw_cut(B, L, P, prof, room, wall_c, ss, U, order=27)
        lab_ = None if annex else site28_tag_fit(tag_, (b - a) * ss, th_)   # v50: the tag, else its height alone
        if lab_:
            site28_bld_tag(B, L, P, prof, lab_, th_, wall_c, U, tags_)
    if dry or not HAVE_NP:                               # no picture: the measured crowns as before
        for s_, zg_, hw_, lo_, hi_ in sd_["trees"]:
            draw_crown(B, L, P, s_, zg_, hw_, lo_, hi_, SEC_CROWN, 30)
    return tags_


def nice_ratio(r):
    """v41 (Aras 26 Oct 06:35 "they need to be round numbers"): the first round scale at or above r (1:500, 1:1,000,
    1:2,000, 1:2,500, 1:5,000 ...)."""
    if r <= 0:
        return r
    e = 10 ** math.floor(math.log10(r))
    for m in (1.0, 2.0, 2.5, 5.0, 10.0):
        if r <= m * e * 1.0001:
            return m * e
    return 10 * e


def round_ss(ss):
    """v41: page units per metre made smaller to the nearest round printed scale (at SHEET_MM), x and y alike."""
    return 1000.0 / (nice_ratio(1000.0 / max(1e-9, ss * MMU)) * MMU)


def draw_section_key(B, x, y, w, U):
    L = "LU_BOARD::Sections"
    B.text("SECTION KEY", x, y, 0.6 * U, INK, L, font=FONT_TITLE, bold=True)
    items = [("box", SEC_PAVE, "Paving at the water"), ("box", ROAD_FILL if ROAD_SOLID else SURFACE["transport"],
                                                    "Street surface, as on the plans"),
             ("box", SURFACE["void"], "Bare and yard ground"), ("box", SURFACE["green"], "Planted ground"),
             # v38: drawn samples with short names; what each one means is an entry of the Sources key [n]
             ("box", SEC_CHANNEL, "Water · hatched from the bed " + bcite(
                 "Section key: water, hatched blue from the bed up to its surface; the channel above it pale blue.")),
             ("box", SEC_WALL, "Channel walls · triangles: surveyed, no height"),
             ("box", mix(typo_tone("traditional", "residential"), PAPER, 0.12), "Cut buildings · surveyed floors " + bcite(
                 "Section key: cut buildings at their surveyed floors, in the tone of their type (see the building "
                 "types), the far wall's windows seen through the cut; a line at every storey; use in the ribbon below.")),
             ("box", mix(typo_tone("monument", "heritage"), PAPER, 0.12), "Monuments and mosques " + bcite(
                 "Section key: monuments (stone and brick bands, arches) and mosques (dome, minaret).")),
             ("box", SEC_CROWN, "Trees · whole, never cut " + bcite(
                 "Section key: trees on and beyond the line drawn whole, never cut: their modelled height and crown "
                 "(canopy map), by leaf type.")),
             ("box", sa_board_bld(dict(cat="residential", fabric="regular")), "Beyond the cut · paler with distance " +
              bcite("Section key: beyond the cut: buildings by type, ground and trees, paler with distance (to 120 m); "
                    "figures for scale.")),
             ("hdr", None, "UNDER EACH SECTION · SATELLITE, METRE BY METRE " +
              bcite("Land cover: Copernicus CLC+ Backbone 2021, 10 m.") +
              bcite("Greenness: Sentinel-2 L2A monthly median NDVI 2019-2025, January and July."))]
    names = seam_pack().get("clc_names") or {}
    items += [("box", CLC_COL[k], "Land cover: " + names.get(str(k), str(k)).lower()) for k in sorted(CLC_COL)
              if str(k) in names and k not in (8, 11)]
    lo = None
    for t_, c_ in NDVI_STEPS:
        items.append(("box", c_, "Greenness (NDVI) " + ("under {:.2f}".format(t_) if lo is None else "{:.2f}+".format(lo)
                                                        if t_ > 1 else "{:.2f} - {:.2f}".format(lo, t_))))
        lo = t_
    return draw_legend_items(B, items, x, y - 1.0 * U, w, U, L, h=0.36)


def draw_typology_key(S, B, x, y, w, U, ymin=None, ss=None, th=None, crop=True, enl=1.0):
    """v16.3 · the building types as the sections draw them: one small generic section of each type found in the frame
    (types under 0.5 % of the footprint are left out, as on the fabric map; mosques and monuments always shown when
    present), with its name. Returns the y below it, or y unchanged when it would not fit above ymin. v44: with ss
    (page units per metre, a round booklet scale) and th (tag height) given, drawn at that scale under the cuts, each
    type as wide as its tag needs; draw_typology_key.last_w = the width used. v45: drawn at the cuts' own scale, so
    it writes no scale of its own (the page states the one scale). v50 (MIRAQUA 28 Oct, P05.1): under each type its
    floors and height, "2 fl · 6.00 m" (floors x the storey height: FLOOR_H, STOREY), the words centred by their
    real width and the subtitle's keywords in bold; enl > 1: ss is the cuts' scale x enl (sections_plan), the types
    drawn enlarged as a diagram, so said in the subtitle."""
    L = "LU_BOARD::Sections"
    draw_typology_key.last_w = 0.0
    tot = sum(S.fabric_area.values()) or 1.0
    present = set(t for t in FABRIC_ORDER if round(100.0 * S.fabric_area.get(t, 0.0) / tot) >= 1 or
                  (t in ("monument", "sacred") and S.fabric_area.get(t, 0.0) > 0))
    # (fabric type, use, width m, floors, tag)
    cand = [("traditional", "residential", 9.0, 2, "old town"),
            ("regular", "residential", 10.0, 2, "planned low-rise"),
            ("regular", "commercial", 10.0, 2, "shop below"),
            ("block", "residential", 14.0, 5, "apartment block"),
            ("selfbuilt", "residential", 6.0, 1, "small / shack"),
            ("large", "institutional", 16.0, 2, "civic hall"),
            ("large", "industrial", 18.0, 1, "industry"),
            ("sacred", "religious", 12.0, 1, "mosque"),
            ("monument", "heritage", 10.0, 3, "monument"),
            ("construction", "residential", 10.0, 3, "building site")]
    cand = [c for c in cand if c[0] in present]
    if not cand:
        return y
    gap = 3.0                                             # m between two buildings
    hmax = max(c[3] * STOREY.get(c[1], FLOOR_H) + typo_rise(c[0], c[1], c[2], c[3] * STOREY.get(c[1], FLOOR_H),
                                                            c[0] == "sacred") for c in cand)
    fixed = ss is not None
    if not fixed:
        ss = min(w / (sum(c[2] for c in cand) + gap * len(cand)), 0.3 * U)             # page units per metre
        if ymin is not None:
            ss = min(ss, (y - ymin - 2.4 * U) / hmax)
        if ss < 0.06 * U:
            return y
    t1, t2 = (th, th) if fixed else (0.2 * U, 0.17 * U)  # tag and floor-count heights
    hts = [u"at its height" if c[0] == "monument" else u"{} fl · {}".format(c[3], u_height(c[3] * STOREY.get(
        c[1], FLOOR_H))) for c in cand]                   # v50 (P05.1): floors and height
    slot = [max(c[2] + gap, (max(site28_tw(c[4], t1), site28_tw(h_, t2)) + t1) / ss) if fixed else c[2] + gap
            for c, h_ in zip(cand, hts)]                  # m per type
    ht = 1.5 * th if fixed else 0.6 * U
    draw_typology_key.last_w = max(sum(slot) * ss, site28_tw(u"BUILDING TYPES IN THE SECTIONS", ht, True) if fixed
                                   else 0.0)              # v50: the title within the width (its neighbours' room)
    B.text("BUILDING TYPES IN THE SECTIONS", x, y, ht, INK, L, font=FONT_TITLE, bold=True)
    ys_ = site28_para(B, u"generic silhouettes{} · height = **floors × storey height**: {}, civic {}, sacred {}, industry {} "
               u"· details by type ".format(u", enlarged (a diagram, not to the cuts' scale)" if enl > 1.0 else u"",
                                            u_height(FLOOR_H), u_height(STOREY["institutional"]),
                                            u_height(STOREY["religious"]), u_height(STOREY["industrial"])) + bcite(
        "Building types: generic silhouettes of each fabric type in its own tone: the height is the surveyed floors; "
        "the roof, jetty, windows, balconies, shopfront, dome and minaret height are drawn to the type, not surveyed."),
        x, y - ht - 0.4 * t1 - t1, draw_typology_key.last_w if fixed else max(w, draw_typology_key.last_w), t1, INK2,
        L, lead=1.45, bcol=INK)
    gy = ys_ + 0.85 * t1 - 0.6 * U - hmax * ss            # the common ground line (v50: under the wrapped subtitle)
    P = (lambda s_, z_: (x + s_ * ss, gy + z_ * ss))      # s_ in metres from x, z_ in metres above the ground line
    s0 = 0.5 * gap
    for (fab, cat, bw, fl, tag), sl, h_t in zip(cand, slot, hts):
        s0 += 0.5 * (sl - bw - gap)
        h = fl * STOREY.get(cat, FLOOR_H)
        prof = bld_profile(fab, cat, s0, s0 + bw, 0.0, 0.0, h, fl, seed=0,
                           minaret=(s0 + bw - 0.5 * MINARET_W - 0.4) if fab == "sacred" else None)
        heritage = fab in ("monument", "sacred")
        room = mix(typo_tone(fab, cat), PAPER, 0.12)
        wall_c = mix(FABRIC[fab][2], INK, 0.45) if heritage else INK
        bld_draw_cut(B, L, P, prof, room, wall_c, ss, U, order=27)
        site28_fit(B, tag, x + (s0 + 0.5 * bw) * ss, gy - 0.4 * t1 - t1, t1, sl * ss * 0.95, INK, L, align="C")
        site28_fit(B, h_t, x + (s0 + 0.5 * bw) * ss, gy - 0.8 * t1 - t1 - 1.45 * t2, t2, sl * ss * 0.95, INK2, L,
                   align="C")
        s0 += bw + gap + 0.5 * (sl - bw - gap)
    B.line([P(0.0, 0.0), P(s0 - 0.5 * gap, 0.0)], INK, L, 28, 0.12)
    yb = gy - 1.2 * t1 - t1 - 1.45 * t2
    if crop:
        crop_panel("building_types", x, yb - 0.1 * U, x + w, y - 1.1 * U, u"Building types in the sections")   # v40
    return yb - 0.1 * U


BED_TAG = {"surveyed": "", "interpolated": "", "input": "", "terrain": ""}   # v51: no status on any page (Aras 29 Oct)


def water_tag(depth, src):
    """v16.5: the water's callout in a section: its depth and where the depth comes from."""
    if depth <= 0.005:
        return "NO WATER" if src != "approx" else ""
    return "WATER {:.2f} M".format(depth)                 # v51: no status on any page (Aras 29 Oct 18:56)


